// ═══════════════════════════════════════════════════════════════════════════════
// CRASH PROTECTION — Keep server alive through any unhandled errors
// ═══════════════════════════════════════════════════════════════════════════════
process.on('uncaughtException', (err) => {
  // EADDRINUSE at startup means another server already owns the port. Do NOT
  // stay alive — a lingering duplicate keeps running every agent/warmer/poller
  // (booted before listen), which is what piles up stale servers and melts the
  // machine. Exit so the duplicate dies instead of busy-looping forever.
  if (err && err.code === 'EADDRINUSE') {
    console.error(`[Server] Port already in use — another server is running. Exiting.`);
    process.exit(1);
  }
  console.error('[Server] Uncaught exception (server stays alive):', err.message);
  console.error(err.stack);
});
process.on('unhandledRejection', (reason, promise) => {
  console.error('[Server] Unhandled rejection (server stays alive):', reason);
});

