// ═══════════════════════════════════════════════════════════════════════════════
// CoinGecko rate-limited fetch — queues requests to avoid 429 errors
// Free tier: ~10 calls/min (6500ms gap)
// Pro Lite: 500 calls/min = ~8.3/s, but per-second burst cap is lower.
// 250ms gap (~4/s, 240/min) keeps us well under both limits without
// starving the page (which can fire 20+ price calls on initial load).
// ═══════════════════════════════════════════════════════════════════════════════
const CG_MIN_INTERVAL = COINGECKO_API_KEY ? 250 : 6500;
let cgLastRequest = 0;
const cgQueue = [];
let cgProcessing = false;

function cgFetch(url) {
  return new Promise((resolve, reject) => {
    cgQueue.push({ url, resolve, reject, ts: Date.now() });
    if (!cgProcessing) processCgQueue();
  });
}

// Max time an item may SIT in the queue before fast-failing. Callers
// (coinGeckoApi etc.) all have stale-cache/fallback paths - a fast reject
// beats holding every page's data hostage behind a backed-up queue.
const CG_QUEUE_MAX_WAIT_MS = 15_000;

async function processCgQueue() {
  if (cgProcessing || cgQueue.length === 0) return;
  cgProcessing = true;
  while (cgQueue.length > 0) {
    const { url, resolve, reject, ts } = cgQueue.shift();
    if (ts && Date.now() - ts > CG_QUEUE_MAX_WAIT_MS) {
      reject(new Error('coingecko queue backlogged - fast fail'));
      continue;
    }
    const now = Date.now();
    const wait = Math.max(0, CG_MIN_INTERVAL - (now - cgLastRequest));
    if (wait > 0) await new Promise(r => setTimeout(r, wait));
    cgLastRequest = Date.now();
    try {
      // 8s bound on BOTH attempts (2026-06-10): this loop is strictly serial,
      // so a single hung upstream connection with no timeout froze the ENTIRE
      // CoinGecko layer for every page until the server restarted - the
      // "whole app takes 20s" dev symptom. The CMC queue below already had
      // its timeout; this one was missed.
      const opts = { headers: { Accept: 'application/json' }, signal: AbortSignal.timeout(8000) };
      if (COINGECKO_API_KEY) opts.headers[COINGECKO_HEADER_KEY] = COINGECKO_API_KEY;
      // One retry with exponential backoff on transient 429s. CG sometimes
      // returns 429 even within plan limits on bursty traffic; honor
      // retry-after if present (capped at 4s so we don't block the queue).
      let res = await fetch(url, opts);
      if (res.status === 429) {
        const retryAfterHeader = Number(res.headers?.get?.('retry-after')) || 0;
        const backoff = Math.min(4000, Math.max(500, retryAfterHeader * 1000));
        await new Promise(r => setTimeout(r, backoff));
        cgLastRequest = Date.now();
        res = await fetch(url, { ...opts, signal: AbortSignal.timeout(8000) });
      }
      resolve(res);
    } catch (err) {
      reject(err);
    }
  }
  cgProcessing = false;
}

// Queue watchdog (2026-06-10): the serial CG loop once wedged for 13 hours on
// a timeout-less fetch (bounded above now), bricking every CoinGecko-backed
// page until a manual restart. This covers UNKNOWN wedge causes: if the head
// item has sat queued > 60s while the loop claims to be processing, the loop
// is stuck on something un-timed - reject everything queued (every caller
// has stale-cache fallbacks) and reset the flag so the next request starts a
// fresh loop. If the old loop later wakes, two loops briefly share the
// interval pacing - harmless next to a dead app. unref() so the timer never
// holds the process open.
setInterval(() => {
  const head = cgQueue[0];
  if (!head || !head.ts || !cgProcessing) return;
  const stuckMs = Date.now() - head.ts;
  if (stuckMs < 60_000) return;
  console.error(`[cg-queue] WATCHDOG: head item stuck ${Math.round(stuckMs / 1000)}s - flushing ${cgQueue.length} queued requests and resetting the loop`);
  while (cgQueue.length > 0) {
    const item = cgQueue.shift();
    try { item.reject(new Error('cg queue watchdog flush')); } catch (_) { /* already settled */ }
  }
  cgProcessing = false;
}, 30_000).unref();

// ═══════════════════════════════════════════════════════════════════════════════
// CoinMarketCap rate-limited fetch — queues requests to avoid 429 errors
// ═══════════════════════════════════════════════════════════════════════════════
const CMC_MIN_INTERVAL = 2000;
let cmcLastRequest = 0;
const cmcQueue = [];
let cmcProcessing = false;

function cmcFetch(url) {
  return new Promise((resolve, reject) => {
    cmcQueue.push({ url, resolve, reject });
    if (!cmcProcessing) processCmcQueue();
  });
}

async function processCmcQueue() {
  if (cmcProcessing || cmcQueue.length === 0) return;
  cmcProcessing = true;
  while (cmcQueue.length > 0) {
    const { url, resolve, reject } = cmcQueue.shift();
    const now = Date.now();
    const wait = Math.max(0, CMC_MIN_INTERVAL - (now - cmcLastRequest));
    if (wait > 0) await new Promise(r => setTimeout(r, wait));
    cmcLastRequest = Date.now();
    try {
      const opts = {
        headers: {
          Accept: 'application/json',
          'X-CMC_PRO_API_KEY': CMC_API_KEY,
        },
        signal: AbortSignal.timeout(10000),
      };
      const res = await fetch(url, opts);
      resolve(res);
    } catch (err) {
      reject(err);
    }
  }
  cmcProcessing = false;
}

