  GRT: 'the-graph', SUSHI: 'sushiswap', RENDER: 'render-token', RNDR: 'render-token',
  INJ: 'injective-protocol', FIL: 'filecoin', FET: 'fetch-ai', JUP: 'jupiter-exchange-solana',
