/** Max entries per cache map. Oldest entries evicted when exceeded. */
const CACHE_MAX_ENTRIES = 500;

function getCached(map, key, ttlMs) {
  const entry = map.get(key);
  if (!entry) return null;
  if (Date.now() > entry.expires) {
    map.delete(key);
    return null;
  }
  return entry.data;
}

function setCached(map, key, data, ttlMs) {
  // Evict oldest entries if cache exceeds max size
  if (map.size >= CACHE_MAX_ENTRIES) {
    let oldest = null;
    let oldestKey = null;
    for (const [k, v] of map) {
      if (!oldest || v.expires < oldest.expires) {
        oldest = v;
        oldestKey = k;
      }
    }
    if (oldestKey !== null) map.delete(oldestKey);
  }
  map.set(key, { data, expires: Date.now() + ttlMs });
}

/**
 * Get top pair address for a token with 4-hour cache + in-flight dedup.
 * Pair addresses rarely change. At beta scale many concurrent requests for the
 * same fresh token would each fire listPairsForToken; the in-flight map
 * collapses them to a single upstream call.
 */
const _pairsInflight = new Map(); // cacheKey -> Promise<pairAddress|null>
async function getCachedTopPair(tokenAddress, networkId) {
  const isSolana = networkId === 1399811149;
  const addr = isSolana ? tokenAddress : tokenAddress.toLowerCase();
  const cacheKey = `${addr}_${networkId}`;

  const cached = getCached(cache.pairs, cacheKey, CACHE_TTL_PAIRS_MS);
  if (cached !== null) return cached;

  // Collapse concurrent identical lookups to one upstream Codex call.
  const inflight = _pairsInflight.get(cacheKey);
  if (inflight) return inflight;

  const promise = (async () => {
    try {
      const result = await executeCodexQuery(`
        query GetTopPair($tokenAddress: String!, $networkId: Int!) {
          listPairsForToken(tokenAddress: $tokenAddress, networkId: $networkId, limit: 1) {
            address
          }
        }
      `, { tokenAddress: addr, networkId });
      const pairAddress = result?.listPairsForToken?.[0]?.address || null;
      setCached(cache.pairs, cacheKey, pairAddress, CACHE_TTL_PAIRS_MS);
      return pairAddress;
    } catch {
      return null;
    } finally {
      _pairsInflight.delete(cacheKey);
    }
  })();
  _pairsInflight.set(cacheKey, promise);
  return promise;
}

/**
 * Evict oldest entry from a Map if it exceeds maxSize.
 * Works with maps storing { ..., expires|ts } shaped values.
 */
function evictIfFull(map, maxSize) {
  if (map.size < maxSize) return;
  // Delete the first (oldest-inserted) key — Map preserves insertion order
  const firstKey = map.keys().next().value;
  if (firstKey !== undefined) map.delete(firstKey);
}

/**
 * All standalone cache Maps registered here for periodic sweep.
 * Each entry: { map, ttlField } where ttlField is 'expires' or 'ts'.
 */
const _standaloneCaches = [];

/** Periodic sweep — garbage-collect expired entries from all cache maps every 5 minutes. */
setInterval(() => {
  const now = Date.now();
  let totalSwept = 0;
  // Sweep central cache object
  for (const [name, map] of Object.entries(cache)) {
    for (const [key, entry] of map) {
      if (entry.expires && now > entry.expires) {
        map.delete(key);
        totalSwept++;
      }
    }
  }
  // Sweep standalone caches
  for (const { map, ttlField, ttlMs } of _standaloneCaches) {
    for (const [key, entry] of map) {
      const expiry = ttlField === 'expires' ? entry.expires : (entry.ts ? entry.ts + (ttlMs || 0) : 0);
      if (expiry && now > expiry) {
        map.delete(key);
        totalSwept++;
      }
    }
  }
  if (totalSwept > 0) {
    console.log(`[Cache sweep] Removed ${totalSwept} expired entries`);
  }
}, 5 * 60 * 1000);

// ═══════════════════════════════════════════════════════════════════════════════
// CIRCUIT BREAKER — prevents cascade failures when Yahoo/Finnhub go down
// States: CLOSED (healthy) → OPEN (failing, skip calls) → HALF_OPEN (testing)
// ═══════════════════════════════════════════════════════════════════════════════
class CircuitBreaker {
  constructor(name, failureThreshold = 3, resetTimeout = 60000) {
    this.name = name;
    this.failureThreshold = failureThreshold;
    this.resetTimeout = resetTimeout;
    this.failures = 0;
    this.state = 'CLOSED'; // CLOSED = healthy
    this.lastFailureTime = 0;
    this.lastLatency = 0;
  }

  isAvailable() {
    if (this.state === 'CLOSED') return true;
    if (this.state === 'OPEN') {
      if (Date.now() - this.lastFailureTime >= this.resetTimeout) {
        this.state = 'HALF_OPEN';
        console.log(`[CircuitBreaker] ${this.name}: OPEN → HALF_OPEN (testing)`);
        return true;
      }
      return false;
    }
    return true; // HALF_OPEN — allow one request through
  }

  recordSuccess(latencyMs) {
    if (this.state !== 'CLOSED') {
      console.log(`[CircuitBreaker] ${this.name}: ${this.state} → CLOSED (recovered)`);
    }
    this.failures = 0;
    this.state = 'CLOSED';
    this.lastLatency = latencyMs || 0;
  }

  recordFailure(err) {
    this.failures++;
    this.lastFailureTime = Date.now();
    if (this.state === 'HALF_OPEN' || this.failures >= this.failureThreshold) {
      this.state = 'OPEN';
      console.warn(`[CircuitBreaker] ${this.name}: → OPEN (${this.failures} failures, resets in ${this.resetTimeout / 1000}s) — ${err?.message || 'unknown'}`);
    }
  }

  getStatus() {
    return {
      name: this.name,
      state: this.state,
      failures: this.failures,
      lastLatency: this.lastLatency,
      lastFailureTime: this.lastFailureTime ? new Date(this.lastFailureTime).toISOString() : null,
    };
  }
}

const breakers = {
  yahoo: new CircuitBreaker('Yahoo', 3, 60000),
  finnhub: new CircuitBreaker('Finnhub', 5, 60000),
  cmc: new CircuitBreaker('CMC', 3, 120000),  // 3 failures, 2min reset
  // Codex: 5 failures in window -> OPEN 2min. Stops a Codex outage / 429 burst
  // from billing us for thousands of doomed retries during beta peak load.
  // Callers should catch the BreakerOpen marker and fall through to CoinGecko
  // (for prices) or return last-cached data.
  codex: new CircuitBreaker('Codex', 5, 120000),
};

/**
 * Codex API Usage Metrics Tracker
 * Tracks query calls, subscription events, latency, and errors.
 * Persists daily stats to disk and exposes via /api/codex/metrics.
 */
const codexMetrics = {
  // Current session stats (reset on server restart)
  session: { startedAt: Date.now(), queries: {}, subscriptions: {} },
  // Today's accumulated stats
  today: null,
  _todayDate: null,

  _ensureToday() {
    const date = new Date().toISOString().slice(0, 10)
    if (this._todayDate !== date) {
      // Save previous day if exists
      if (this.today && this._todayDate) this._saveDailyFile(this._todayDate, this.today)
      this._todayDate = date
      this.today = this._loadDailyFile(date) || { date, queries: {}, subscriptions: {}, totalQueries: 0, totalSubEvents: 0 }
    }
    return this.today
  },

  trackQuery(operation, latencyMs, error = null) {
    this._ensureToday()
    // Session stats
    if (!this.session.queries[operation]) {
      this.session.queries[operation] = { calls: 0, errors: 0, totalLatencyMs: 0, cacheHits: 0 }
    }
    const sq = this.session.queries[operation]
    sq.calls++
    sq.totalLatencyMs += latencyMs
    if (error) sq.errors++

    // Daily persistent stats
    if (!this.today.queries[operation]) {
      this.today.queries[operation] = { calls: 0, errors: 0, totalLatencyMs: 0 }
    }
    const dq = this.today.queries[operation]
    dq.calls++
    dq.totalLatencyMs += latencyMs
    if (error) dq.errors++
    this.today.totalQueries++

    // Throttled save (every 50 queries)
    if (this.today.totalQueries % 50 === 0) this._saveDailyFile(this._todayDate, this.today)
  },

  trackCacheHit(operation) {
    if (!this.session.queries[operation]) {
      this.session.queries[operation] = { calls: 0, errors: 0, totalLatencyMs: 0, cacheHits: 0 }
    }
    this.session.queries[operation].cacheHits++
  },

  trackSubscriptionEvent(type) {
    this._ensureToday()
    // Session
    if (!this.session.subscriptions[type]) this.session.subscriptions[type] = 0
    this.session.subscriptions[type]++
    // Daily
    if (!this.today.subscriptions[type]) this.today.subscriptions[type] = 0
    this.today.subscriptions[type]++
    this.today.totalSubEvents++
    // Throttled save (every 500 events)
    if (this.today.totalSubEvents % 500 === 0) this._saveDailyFile(this._todayDate, this.today)
  },

  getMetrics(days = 7) {
    this._ensureToday()
    const history = []
    for (let i = 0; i < days; i++) {
      const d = new Date(Date.now() - i * 86400000).toISOString().slice(0, 10)
      if (d === this._todayDate) { history.push(this.today); continue }
      const data = this._loadDailyFile(d)
      if (data) history.push(data)
    }
    // Compute session averages
    const sessionSummary = {}
    for (const [op, s] of Object.entries(this.session.queries)) {
      sessionSummary[op] = { ...s, avgLatencyMs: s.calls > 0 ? Math.round(s.totalLatencyMs / s.calls) : 0 }
    }
    return {
      session: { ...this.session, queries: sessionSummary, uptimeMs: Date.now() - this.session.startedAt },
      today: this.today,
      history,
    }
  },

  _metricsDir() {
    const dir = path.join(__dirname, 'data', 'codex-metrics')
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true })
    return dir
  },

  _loadDailyFile(date) {
    try {
      const file = path.join(this._metricsDir(), `${date}.json`)
      if (fs.existsSync(file)) return JSON.parse(fs.readFileSync(file, 'utf-8'))
    } catch { /* ignore corrupt files */ }
    return null
  },

  _saveDailyFile(date, data) {
    try {
      const file = path.join(this._metricsDir(), `${date}.json`)
      fs.writeFileSync(file, JSON.stringify(data, null, 2))
    } catch (e) { console.error('[codex-metrics] Save failed:', e.message) }
  },

  // Cleanup old files (keep 90 days)
  cleanup() {
    try {
      const dir = this._metricsDir()
      const cutoff = Date.now() - 90 * 86400000
      for (const file of fs.readdirSync(dir)) {
        const date = file.replace('.json', '')
        if (new Date(date).getTime() < cutoff) fs.unlinkSync(path.join(dir, file))
      }
    } catch {}
  },
}

// Run cleanup daily
setInterval(() => codexMetrics.cleanup(), 24 * 60 * 60 * 1000)

// Detect GraphQL operation name from query string
function _detectCodexOperation(query) {
  // Try named operation first: "query GetTokenInfo" or "mutation ..."
  const named = query.match(/(?:query|mutation|subscription)\s+(\w+)/)
  if (named) return named[1]
  // Detect root field: first field after opening brace
  const field = query.match(/\{\s*(\w+)/)
  return field ? field[1] : 'unknown'
}

/**
 * Marker error thrown when the Codex circuit breaker is OPEN. Callers can
 * `if (err.codexBreakerOpen)` and fall through to CoinGecko / cached data
 * instead of bubbling a misleading "Codex error" to the user.
 */
class CodexBreakerOpenError extends Error {
  constructor() {
    super('Codex circuit breaker OPEN');
    this.codexBreakerOpen = true;
    this.name = 'CodexBreakerOpenError';
  }
}

/**
 * Execute GraphQL query against Codex API
 */
async function executeCodexQuery(query, variables = {}, signal) {
  const operation = _detectCodexOperation(query)
  const startTime = Date.now()
  let error = null

  // Fail-fast when the breaker is OPEN. A 429 burst or upstream outage
  // would otherwise stack thousands of doomed requests at peak load.
  if (!breakers.codex.isAvailable()) {
    error = 'breaker_open'
    codexMetrics.trackQuery(operation, 0, error)
    throw new CodexBreakerOpenError();
  }

  // Hard timeout so a hung Codex socket can't stall the snapshot assembly
  // (or any cold caller). Callers that pass their own signal keep it.
  const effectiveSignal = signal || AbortSignal.timeout(5000)

  try {
    const response = await fetch(CODEX_BASE_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': CODEX_API_KEY,
        // The Codex key is origin-restricted (allowlist = app.spectreai.io).
        // Server-to-server calls send no Origin -> "unauthorized origin:
        // undefined". Send the one allowed origin so the proxy passes.
        'Origin': CODEX_ORIGIN,
      },
      body: JSON.stringify({ query, variables }),
      signal: effectiveSignal,
    });

    const responseText = await response.text();

    if (!response.ok) {
      error = `${response.status}`
      console.error(`Codex API ${response.status} response:`, responseText);
      // Count rate-limits and 5xx toward the breaker. 4xx (auth, bad input)
      // are client errors that breaking the circuit on would only mask.
      if (response.status === 429 || response.status >= 500) {
        breakers.codex.recordFailure(new Error(`Codex ${response.status}`));
      }
      throw new Error(`Codex API error: ${response.status} ${response.statusText}`);
    }

    let data;
    try {
      data = JSON.parse(responseText);
    } catch (e) {
      error = 'parse_error'
      console.error('Failed to parse response:', responseText);
      breakers.codex.recordFailure(e);
      throw new Error('Invalid JSON response from Codex API');
    }

    if (data.errors) {
      error = 'graphql_error'
      console.error('GraphQL errors:', JSON.stringify(data.errors, null, 2));
      // Don't break on GraphQL semantic errors (e.g. token not found) - those
      // are caller-input issues, not Codex health issues.
      throw new Error(data.errors[0]?.message || 'GraphQL error');
    }

    breakers.codex.recordSuccess(Date.now() - startTime);
    return data.data;
  } finally {
    codexMetrics.trackQuery(operation, Date.now() - startTime, error)
  }
}

