// IP geolocation proxy - dev mirror of apps/{trading,research}/api/geo.js
// (the weather chip's fallback). Was Express-less, so dev 404'd and the
// widget silently fell back to NYC coords. Preserves the ipapi.co JSON shape.
let _geoCache = null; // dev = one developer IP, one entry is enough
let _geoCooldownUntil = 0; // set on any upstream failure (see the route below)
const GEO_COOLDOWN_MS = 10 * 60 * 1000;
app.get('/api/geo', async (req, res) => {
  res.setHeader('Cache-Control', 'private, max-age=3600');
  if (_geoCache && Date.now() - _geoCache.ts < 24 * 60 * 60 * 1000) {
    return res.json(_geoCache.data);
  }
  // ipapi.co free tier rate-limits by IP. The cache above only fills on
  // SUCCESS, so once it 429s every mount re-hit it and re-429'd - a console
  // error on each load and a burnt quota that never got a chance to reset.
  // Cooldown after any upstream failure, and keep serving the last good
  // answer past its TTL: a stale city is a fine answer for weather, an error
  // is not. (Same shape as the onchain-bridge-down cooldown.)
  if (_geoCooldownUntil && Date.now() < _geoCooldownUntil) {
    if (_geoCache) return res.json({ ..._geoCache.data, _stale: true });
    return res.status(503).json({ error: 'geo cooling down' });
  }
  try {
    const r = await fetch('https://ipapi.co/json/', {
      headers: { Accept: 'application/json' },
      signal: AbortSignal.timeout(5000),
    });
    if (!r.ok) throw new Error(`geo upstream ${r.status}`);
    const data = await r.json();
    _geoCache = { data, ts: Date.now() };
    _geoCooldownUntil = 0;
    res.json(data);
  } catch (err) {
    _geoCooldownUntil = Date.now() + GEO_COOLDOWN_MS;
    console.warn('[geo] upstream failed, cooling down:', err.message);
    if (_geoCache) return res.json({ ..._geoCache.data, _stale: true });
    res.status(502).json({ error: 'geo upstream failed' });
  }
});

// Codex request metrics - top offenders in the last N minutes.
// Use during beta to spot runaway hooks before they bill.
app.get('/api/health/codex-metrics', (req, res) => {
  const lookbackMin = Math.min(parseInt(req.query.minutes) || 10, 15);
  const minute = Math.floor(Date.now() / 60000);
  const totals = new Map();  // bucketKey -> count over the lookback window
  const actionTotals = new Map();
  let totalRequests = 0;
  for (let m = minute - lookbackMin + 1; m <= minute; m++) {
    const bucket = _codexMetrics.get(m);
    if (!bucket) continue;
    for (const [key, count] of bucket) {
      totals.set(key, (totals.get(key) || 0) + count);
      totalRequests += count;
      const action = key.split('|')[1] || 'unknown';
      actionTotals.set(action, (actionTotals.get(action) || 0) + count);
    }
  }
  const topOffenders = [...totals.entries()]
    .map(([key, count]) => {
      const [principal, action] = key.split('|');
      return { principal, action, count };
    })
    .sort((a, b) => b.count - a.count)
    .slice(0, 25);
  const byAction = [...actionTotals.entries()]
    .map(([action, count]) => ({ action, count }))
    .sort((a, b) => b.count - a.count);
  res.json({
    windowMinutes: lookbackMin,
    totalRequests,
    threshold: CODEX_RUNAWAY_THRESHOLD,
    byAction,
    topOffenders,
    timestamp: new Date().toISOString(),
  });
});

