// Image proxy — allows canvas to draw cross-origin token logos (CORS bypass)
// Restricted to known image CDNs to prevent SSRF
const ALLOWED_IMG_DOMAINS = [
  'assets.coingecko.com', 'coin-images.coingecko.com',
  'raw.githubusercontent.com', 'tokens.1inch.io', 'cryptologos.cc',
  'dd.dexscreener.com', 's2.coinmarketcap.com', 'static.alchemyapi.io',
  'logo.moralis.io', 'arweave.net', 'ipfs.io', 'cloudflare-ipfs.com',
  'metadata.ens.domains', 'i.imgur.com',
  'token-media.defined.fi',
  // X / Twitter profile pictures (used by XFullView KOL leaderboard)
  'pbs.twimg.com', 'abs.twimg.com',
  // Stock logo CDNs (getStockLogoUrl / getStockLogoFallback). The hero reads
  // these through the proxy to sample their alpha — a direct CDN read taints
  // the canvas and getImageData throws. Prod's serverless img-proxy has no
  // domain allowlist at all (SSRF checks only), so without these two the dev
  // and prod proxies disagree and the behaviour is unverifiable locally.
  'financialmodelingprep.com', 'companiesmarketcap.com',
];
app.get('/api/img-proxy', async (req, res) => {
  const { url } = req.query;
  if (!url) return res.status(400).json({ error: 'Missing url parameter' });
  try {
    const parsed = new URL(url);
    if (!['http:', 'https:'].includes(parsed.protocol)) {
      return res.status(400).json({ error: 'Invalid protocol' });
    }
    if (!ALLOWED_IMG_DOMAINS.some(d => parsed.hostname === d || parsed.hostname.endsWith('.' + d))) {
      return res.status(403).json({ error: 'Domain not allowed' });
    }
    const response = await fetch(url, { signal: AbortSignal.timeout(10000) });
    if (!response.ok) return res.status(response.status).end();
    const contentType = response.headers.get('content-type') || 'image/png';
    if (!contentType.startsWith('image/')) {
      return res.status(400).json({ error: 'Not an image' });
    }
    const arrayBuf = await response.arrayBuffer();
    res.set('Content-Type', contentType);
    res.set('Cache-Control', 'public, max-age=86400');
    res.set('Access-Control-Allow-Origin', '*');
    res.send(Buffer.from(arrayBuf));
  } catch {
    res.status(502).json({ error: 'Failed to fetch image' });
  }
});

// ──────────────────────────────────────────────────────────────
// Token Color Extraction - extracts dominant color from token logo PNG
// ──────────────────────────────────────────────────────────────
// Pair list per token, for /api/token/trades. Pools are effectively static and
// the route only uses the top one by liquidity, so this removes one of the two
// sequential Codex round trips that route made on EVERY request (~700ms
// measured, uncached, 2026-08-04). The trades themselves are never cached.
const tokenPairsCache = new Map(); // { 'address:networkId' -> { data, expires } }
const TOKEN_PAIRS_TTL = 600000; // 10 min

const tokenColorCache = new Map(); // { url -> { color, expires } }
const TOKEN_COLOR_TTL = 3600000; // 1 hour — for SUCCESSFUL extractions
const TOKEN_COLOR_FAIL_TTL = 60000; // 60s — for FAILED extractions (so we can retry soon)

/**
 * Minimal PNG pixel reader using Node.js built-in zlib.
 * Decodes IHDR + IDAT chunks to get raw RGBA pixel data.
 * Only handles the common case: 8-bit RGBA (color type 6) and RGB (color type 2).
 * Returns null on any unsupported format - caller falls back to default color.
 */
function decodePngPixels(buf) {
  const zlib = require('zlib');
  // Verify PNG signature
  const PNG_SIG = Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]);
  if (buf.length < 8 || !buf.subarray(0, 8).equals(PNG_SIG)) return null;

  let width = 0, height = 0, bitDepth = 0, colorType = 0;
  const idatChunks = [];
  let offset = 8;

  while (offset < buf.length) {
    if (offset + 8 > buf.length) break;
    const chunkLen = buf.readUInt32BE(offset);
    const chunkType = buf.toString('ascii', offset + 4, offset + 8);
    const dataStart = offset + 8;

    if (chunkType === 'IHDR' && chunkLen >= 13) {
      width = buf.readUInt32BE(dataStart);
      height = buf.readUInt32BE(dataStart + 4);
      bitDepth = buf[dataStart + 8];
      colorType = buf[dataStart + 9];
    } else if (chunkType === 'IDAT') {
      idatChunks.push(buf.subarray(dataStart, dataStart + chunkLen));
    } else if (chunkType === 'IEND') {
      break;
    }

    // chunk length + type (4) + CRC (4)
    offset = dataStart + chunkLen + 4;
  }

  // Only support 8-bit RGB (type 2) and RGBA (type 6)
  if (bitDepth !== 8 || (colorType !== 2 && colorType !== 6)) return null;
  if (width === 0 || height === 0 || idatChunks.length === 0) return null;

  const channels = colorType === 6 ? 4 : 3;
  const concatenated = Buffer.concat(idatChunks);

  let raw;
  try {
    raw = zlib.inflateSync(concatenated);
  } catch { /* decompression failed */ return null; }

  // Each row has a filter byte + width * channels bytes
  const rowBytes = 1 + width * channels;
  if (raw.length < rowBytes * height) return null;

  // Undo PNG row filters (None=0, Sub=1, Up=2, Average=3, Paeth=4)
  const pixels = Buffer.alloc(width * height * channels);
  const prevRow = Buffer.alloc(width * channels);
  prevRow.fill(0);

  for (let y = 0; y < height; y++) {
    const filterType = raw[y * rowBytes];
    const rowStart = y * rowBytes + 1;
    const pixStart = y * width * channels;

    for (let x = 0; x < width * channels; x++) {
      const rawByte = raw[rowStart + x];
      let a = x >= channels ? pixels[pixStart + x - channels] : 0;
      let b = prevRow[x];
      let c = x >= channels ? (y > 0 ? prevRow[x - channels] : 0) : 0;

      let val;
      switch (filterType) {
        case 0: val = rawByte; break;
        case 1: val = (rawByte + a) & 0xFF; break;
        case 2: val = (rawByte + b) & 0xFF; break;
        case 3: val = (rawByte + Math.floor((a + b) / 2)) & 0xFF; break;
        case 4: {
          // Paeth predictor
          const p = a + b - c;
          const pa = Math.abs(p - a);
          const pb = Math.abs(p - b);
          const pc = Math.abs(p - c);
          const pr = pa <= pb && pa <= pc ? a : pb <= pc ? b : c;
          val = (rawByte + pr) & 0xFF;
          break;
        }
        default: val = rawByte;
      }
      pixels[pixStart + x] = val;
    }
    // Copy current row to prevRow for next iteration
    pixels.copy(prevRow, 0, pixStart, pixStart + width * channels);
  }

  return { pixels, width, height, channels };
}

/**
 * Find the dominant vibrant color from pixel data.
 * Subsamples to at most ~256 pixels for speed.
 * Skips transparent, near-black, and near-white pixels.
 * Weights by saturation to prefer vibrant colors.
 */
function extractDominantColor(pixelData) {
  const { pixels, width, height, channels } = pixelData;
  const totalPixels = width * height;

  // Subsample on a 2D GRID, not a 1D linear stride. The previous code did
  //   for (let i = 0; i < totalPixels; i += step)
  // with `step = totalPixels / 256`. For a 256×256 image that step is 256,
  // which exactly equals `width`, so every sampled index `i` lands in
  // column 0 of the image. Token logos are typically centred marks on
  // transparent backgrounds — column 0 is empty → every sample has
  // alpha=0 → buckets stays empty → extraction returns null → caller
  // falls back to the hash hue, and the real brand colour is never seen.
  //
  // Walking a 2D grid (step ≈ 16 in both x and y for a 256² image) samples
  // ~256 pixels uniformly across the canvas, hitting the centred logo
  // content. Verified 2026-05-26 against PAAL: 1D stride saw 0 non-
  // transparent pixels, 2D grid sees the brand purple.
  const gridStep = Math.max(1, Math.round(Math.sqrt(totalPixels / 256)));

  // Collect color buckets (quantized to 5-bit per channel = 32 levels)
  const buckets = new Map(); // 'r,g,b' -> { r, g, b, weight, count }

  for (let y = 0; y < height; y += gridStep) {
    for (let x = 0; x < width; x += gridStep) {
      const offset = (y * width + x) * channels;
      const r = pixels[offset];
      const g = pixels[offset + 1];
      const b = pixels[offset + 2];
      const a = channels === 4 ? pixels[offset + 3] : 255;

    // Skip transparent pixels
    if (a < 128) continue;

    // Skip near-black (luminance < 25) and near-white (luminance > 240)
    const luminance = 0.299 * r + 0.587 * g + 0.114 * b;
    if (luminance < 25 || luminance > 240) continue;

    // Calculate saturation for weighting
    const max = Math.max(r, g, b);
    const min = Math.min(r, g, b);
    const saturation = max === 0 ? 0 : (max - min) / max;

    // Quantize to reduce color space
    const qr = (r >> 3) << 3;
    const qg = (g >> 3) << 3;
    const qb = (b >> 3) << 3;
    const key = `${qr},${qg},${qb}`;

    const existing = buckets.get(key);
    const weight = 0.3 + saturation * 0.7; // base weight + saturation bonus
    if (existing) {
      existing.r += r * weight;
      existing.g += g * weight;
      existing.b += b * weight;
      existing.weight += weight;
      existing.count++;
    } else {
      buckets.set(key, { r: r * weight, g: g * weight, b: b * weight, weight, count: 1 });
    }
    }
  }

  if (buckets.size === 0) return null;

  // Two-pass scoring:
  // Pass 1: Find the most SATURATED bucket (prefer vibrant accent colors even if rare)
  // Pass 2: Fall back to most common bucket if no saturated colors exist
  let bestVibrantKey = null, bestVibrantSat = 0;
  let bestCommonKey = null, bestCommonWeight = 0;

  for (const [key, bucket] of buckets) {
    const avgR = bucket.r / bucket.weight;
    const avgG = bucket.g / bucket.weight;
    const avgB = bucket.b / bucket.weight;
    const max = Math.max(avgR, avgG, avgB);
    const min = Math.min(avgR, avgG, avgB);
    const sat = max === 0 ? 0 : (max - min) / max;

    // Vibrant: high saturation AND at least 2 pixels (not noise)
    if (sat > 0.3 && bucket.count >= 2) {
      const vibrantScore = sat * Math.sqrt(bucket.count);
      if (vibrantScore > bestVibrantSat) {
        bestVibrantSat = vibrantScore;
        bestVibrantKey = key;
      }
    }

    // Common: highest total weight
    if (bucket.weight > bestCommonWeight) {
      bestCommonWeight = bucket.weight;
      bestCommonKey = key;
    }
  }

  // Prefer vibrant color if found, otherwise use most common
  const chosenKey = bestVibrantKey || bestCommonKey;
  if (!chosenKey) return null;

  const best = buckets.get(chosenKey);
  let r = Math.round(best.r / best.weight);
  let g = Math.round(best.g / best.weight);
  let b = Math.round(best.b / best.weight);

  // Reject only TRULY unusable results:
  //   • Near-greyscale (sat<0.1) AND not already light enough — these are
  //     muddy greys that read worse than the hash-derived hue.
  //   • The caller falls back to the hash hue (deterministic and distinct
  //     per token) when we return null. Do NOT substitute `#D4D4D8`, which
  //     is a legit warm-silver brand colour — using it as a failure value
  //     made every uncurated whose extraction tripped this branch converge
  //     to the same near-white, masking real brand identity.
  const finalLum0 = 0.299 * r + 0.587 * g + 0.114 * b;
  const finalMax0 = Math.max(r, g, b), finalMin0 = Math.min(r, g, b);
  const finalSat0 = finalMax0 === 0 ? 0 : (finalMax0 - finalMin0) / finalMax0;
  if (finalSat0 < 0.1 && finalLum0 < 180) return null; // grey — no usable hue

  // Lift dark but VIBRANT brand colours into a usable band. Pure purple,
  // navy, deep red, forest green all sit naturally at luminance <45 — the
  // previous `if (finalLum < 45) return null` threw all of them away and
  // forced uncurated brand-purple tokens (PAAL, AVAX-dark, etc.) onto the
  // hash hue. Boost matches the client canvas extractor's behaviour
  // (`extractColorFromImage` in tokenColors.js) so dev and prod produce
  // consistent values. Boost only when saturated — desaturated dark
  // colours are already filtered by the grey check above.
  if (finalLum0 < 80 && finalSat0 >= 0.1) {
    const boost = 80 / Math.max(finalLum0, 1);
    r = Math.min(255, Math.round(r * boost));
    g = Math.min(255, Math.round(g * boost));
    b = Math.min(255, Math.round(b * boost));
  }

  // Convert to hex
  const hex = '#' + [r, g, b].map(v => Math.max(0, Math.min(255, v)).toString(16).padStart(2, '0')).join('');
  return hex;
}

app.get('/api/token-color', async (req, res) => {
  const { url } = req.query;
  if (!url) return res.status(400).json({ error: 'Missing url parameter' });

  // Check cache first
  const cached = tokenColorCache.get(url);
  if (cached && Date.now() < cached.expires) {
    res.set('Cache-Control', 'public, s-maxage=3600, stale-while-revalidate=7200');
    return res.json({ color: cached.color });
  }

  // Validate URL. Every failure path below returns `{ color: null }` —
  // NOT a hex sentinel. Reason: `#D4D4D8` is a legit warm-silver brand
  // colour (SPECTRE uses it). Using it as a failure value collapses
  // every extraction-failed token into "looks like silver", making
  // distinct tokens indistinguishable. Null is the unambiguous "extract
  // failed, caller should fall back to the hash hue" signal. The client
  // pipeline (useAccentTheme priority 3) already produces a deterministic
  // distinct hue from `symbol|address` when this returns null.
  let parsed;
  try {
    parsed = new URL(url);
  } catch { /* invalid URL */ return res.json({ color: null }); }

  if (!['http:', 'https:'].includes(parsed.protocol)) {
    return res.json({ color: null });
  }

  // Restrict to known image CDNs (reuse ALLOWED_IMG_DOMAINS)
  if (!ALLOWED_IMG_DOMAINS.some(d => parsed.hostname === d || parsed.hostname.endsWith('.' + d))) {
    return res.json({ color: null });
  }

  try {
    const response = await fetch(url, { signal: AbortSignal.timeout(5000) });
    if (!response.ok) {
      // Cache the failure for SHORT TTL (60s) so a transient upstream
      // outage doesn't lock the token to "no colour" for an hour. Previous
      // behaviour cached `#D4D4D8` for 1h, which is why uncurated tokens
      // "felt cached" — they were, with the wrong value.
      tokenColorCache.set(url, { color: null, expires: Date.now() + TOKEN_COLOR_FAIL_TTL });
      return res.json({ color: null });
    }

    const arrayBuf = await response.arrayBuffer();
    const buf = Buffer.from(arrayBuf);

    // Attempt PNG decoding (most token logos are PNG). Future Layer 2 work:
    // swap in `sharp` for multi-format support (WebP/AVIF/SVG/paletted-PNG).
    let color = null;
    let pixelData = null;
    try {
      pixelData = decodePngPixels(buf);
    } catch { /* decode error */ }
    if (pixelData) {
      color = extractDominantColor(pixelData);
      console.log(`[token-color] extracted=${color}`);
    }

    // Success → cache 1h. Failure → cache null for 60s so we can retry
    // when the upstream image becomes decodable (or someone fixes the
    // logo URL). Both branches cache something so we don't hammer the
    // upstream on every page load.
    if (color) {
      tokenColorCache.set(url, { color, expires: Date.now() + TOKEN_COLOR_TTL });
    } else {
      tokenColorCache.set(url, { color: null, expires: Date.now() + TOKEN_COLOR_FAIL_TTL });
    }

    // Garbage sweep if cache too large
    if (tokenColorCache.size > 500) {
      const now = Date.now();
      for (const [k, v] of tokenColorCache) {
        if (now >= v.expires) tokenColorCache.delete(k);
      }
    }

    res.set('Cache-Control', 'public, s-maxage=3600, stale-while-revalidate=7200');
    res.json({ color });
  } catch {
    /* fetch timeout or other error */
    tokenColorCache.set(url, { color: null, expires: Date.now() + TOKEN_COLOR_FAIL_TTL });
    res.json({ color: null });
  }
});

// POST write-through: the client canvas extractor (apps/trading/src/utils/
// tokenColors.js extractColorFromImage) posts back its computed hex so the
// next request — and any other surface / user — skips re-extraction. Before
// this handler existed the POST 404'd (5x per token page load), spamming
// the console + wasting a round-trip in the critical load window. Mirrors
// the Vercel apps/trading/api/token-color.js POST branch. Fire-and-forget
// from the client, so we just ack 200.
app.post('/api/token-color', express.json({ limit: '2kb' }), (req, res) => {
  try {
    const { url, color } = req.body || {};
    if (url && typeof color === 'string' && /^#[0-9a-fA-F]{6}$/.test(color)) {
      tokenColorCache.set(url, { color, expires: Date.now() + TOKEN_COLOR_TTL });
    }
  } catch { /* ignore malformed body */ }
  res.json({ ok: true });
});

// Token security (Deployer Security panel) - GoPlus Security API, free tier.
// Codex has no honeypot/tax/LP-burn data (only isScam + mintable/freezable),
// so GoPlus is the source: buy/sell tax, honeypot, cooldown, anti-whale,
// LP burned computed from lp_holders. Solana uses GoPlus's dedicated endpoint.
// Mirrors apps/trading/api/token-tax.js (keep the two in sync).
// Tiered TTL: established tokens (>=1000 holders) 24h - profile effectively
// immutable; fresh launches 30min - renounce/LP-burn/limits change early.
// Optional signed auth via GOPLUS_APP_KEY + GOPLUS_APP_SECRET moves the
// 30/min free quota from per-IP to per-key. Unauthenticated works too.
const _tokenTaxCache = new Map();
const TOKEN_TAX_TTL_ESTABLISHED = 24 * 60 * 60 * 1000;
const TOKEN_TAX_TTL_FRESH = 30 * 60 * 1000;
const TOKEN_TAX_ESTABLISHED_HOLDERS = 1000;
const SOLANA_NETWORK_ID = 1399811149;

let _goplusToken = null;
let _goplusTokenExpiry = 0;
async function goplusAuthHeaders() {
  const appKey = process.env.GOPLUS_APP_KEY;
  const appSecret = process.env.GOPLUS_APP_SECRET;
  if (!appKey || !appSecret) return {};
  const now = Date.now();
  if (_goplusToken && now < _goplusTokenExpiry) return { Authorization: _goplusToken };
  try {
    const time = Math.floor(now / 1000);
    const sign = require('crypto').createHash('sha1').update(`${appKey}${time}${appSecret}`).digest('hex');
    const r = await fetch('https://api.gopluslabs.io/api/v1/token', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ app_key: appKey, time, sign }),
      signal: AbortSignal.timeout(5000),
    });
    const j = await r.json();
    const token = j && j.result && j.result.access_token;
    if (token) {
      _goplusToken = token;
      // renew 5min before expiry (GoPlus default validity ~1h)
      _goplusTokenExpiry = now + Math.max(60, (Number(j.result.expires_in) || 3600) - 300) * 1000;
      return { Authorization: token };
    }
  } catch { /* fall through to unauthenticated */ }
  return {};
}
const LP_BURN_ADDRESSES = new Set([
  '0x0000000000000000000000000000000000000000',
  '0x000000000000000000000000000000000000dead',
]);

function goplusTop10Percent(holders) {
  if (!Array.isArray(holders) || holders.length === 0) return null;
  let sum = 0;
  for (const h of holders.slice(0, 10)) sum += parseFloat(h.percent) || 0;
  return Math.min(100, sum * 100);
}

function mapGoPlusEvm(d, tokenAddress) {
  const pct = (v) => (v === '' || v == null || isNaN(parseFloat(v)) ? null : parseFloat(v) * 100);
  let burned = 0, locked = 0;
  const lockers = [];
  const addrLower = String(tokenAddress).toLowerCase();
  for (const h of d.lp_holders || []) {
    const a = String(h.address || '').toLowerCase();
    const p = parseFloat(h.percent) || 0;
    // LP sent to zero/dead or to the token's own contract is unrecoverable -
    // market convention (PEPE holds 99.9% of its V2 LP in the token contract).
    if (LP_BURN_ADDRESSES.has(a) || a === addrLower) burned += p;
    else if (h.is_locked === 1 || h.is_locked === '1') {
      locked += p;
      // Who holds the lock - GoPlus tags known lockers (TeamFinance, UNCX, PinkLock...)
      if (p >= 0.001) lockers.push({ tag: h.tag || null, address: h.address, percent: Math.min(100, p * 100) });
    }
  }
  lockers.sort((x, y) => y.percent - x.percent);
  // Main pool pair (V2-style 20-byte addresses only - V4 pool ids are 32 bytes
  // and have no token page). lp_holders refer to this pair's LP token; the
  // explorer link {explorer}/token/{pair}?a={locker} is the on-chain lock proof.
  let lpPair = null, lpLiq = -1;
  for (const p of d.dex || []) {
    const liq = parseFloat(p.liquidity) || 0;
    if (/^0x[0-9a-fA-F]{40}$/.test(p.pair || '') && liq > lpLiq) { lpPair = p.pair; lpLiq = liq; }
  }
  // Ownership: '' or zero/dead owner = renounced (GoPlus: ownerless / black
  // hole owner). hidden_owner or take-back trumps - that "renounce" is a rug vector.
  const owner = d.owner_address == null ? null : String(d.owner_address).toLowerCase();
  const hiddenOwner = d.hidden_owner === '1';
  const renounced = owner == null ? null
    : (!hiddenOwner && d.can_take_back_ownership !== '1' && (owner === '' || LP_BURN_ADDRESSES.has(owner)));
  // GoPlus capability flags report function EXISTENCE in the contract. With
  // ownership truly renounced nobody can call the owner-gated setters, so
  // report the exploitable state, not the dead code (SPECTRE: slippage_modifiable
  // =1 but owner is the zero address - taxes can never change).
  const ownerDead = renounced === true;
  return {
    buyTax: pct(d.buy_tax),
    sellTax: pct(d.sell_tax),
    isHoneypot: d.is_honeypot === '1',
    cannotSellAll: d.cannot_sell_all === '1',
    taxModifiable: ownerDead ? false : (d.slippage_modifiable === '1' || d.personal_slippage_modifiable === '1'),
    mintable: d.is_mintable == null ? null : (ownerDead ? false : d.is_mintable === '1'),
    canFreeze: ownerDead ? false : (d.is_blacklisted === '1' || d.transfer_pausable === '1'),
    renounced,
    hiddenOwner,
    openSource: d.is_open_source == null ? null : d.is_open_source === '1',
    top10Percent: goplusTop10Percent(d.holders),
    hasCooldown: d.trading_cooldown === '1',
    hasAntiWhale: d.is_anti_whale == null ? null : d.is_anti_whale === '1',
    maxTxPercent: null, // GoPlus reports anti-whale as a flag, not a percent
    lpBurnedPercent: (d.lp_holders || []).length ? Math.min(100, burned * 100) : null,
    lpLockedPercent: (d.lp_holders || []).length ? Math.min(100, locked * 100) : null,
    lpLockers: lockers.slice(0, 3),
    lpPair,
  };
}

function mapGoPlusSolana(d) {
  // Token-2022 transfer fee; classic SPL has no transfer tax (fee = 0).
  // Shape is sparse/evolving - try fraction, then basis points.
  const tf = (d && d.transfer_fee) || {};
  let feePct = parseFloat(tf.fee_rate ?? (d && d.transfer_fee_rate));
  if (!Number.isFinite(feePct)) {
    const bps = parseFloat(tf.current_fee_rate ?? tf.transfer_fee_basis_points);
    feePct = Number.isFinite(bps) ? bps / 10000 : 0;
  }
  const tax = feePct * 100;
  let burn = null;
  for (const pool of d.dex || []) {
    const b = parseFloat(pool.burn_percent);
    if (Number.isFinite(b)) burn = Math.max(burn ?? 0, b);
  }
  let locked = 0;
  const lockers = [];
  for (const h of d.lp_holders || []) {
    const p = parseFloat(h.percent) || 0;
    if ((h.is_locked === 1 || h.is_locked === '1') && p >= 0.001) {
      locked += p;
      lockers.push({ tag: h.tag || null, address: h.address || h.account || null, percent: Math.min(100, p * 100) });
    }
  }
  lockers.sort((x, y) => y.percent - x.percent);
  const status = (k) => !!(d && d[k] && d[k].status === '1');
  const mintable = status('mintable');
  const canFreeze = status('freezable');
  const balanceMutable = status('balance_mutable_authority');
  const closable = status('closable');
  return {
    buyTax: tax,
    sellTax: tax,
    isHoneypot: d.non_transferable === '1',
    cannotSellAll: false,
    taxModifiable: status('transfer_fee_upgradable'),
    mintable,
    canFreeze,
    // "Renounced" on Solana = the dangerous authorities are all revoked.
    // metadata_mutable excluded - even BONK keeps its metadata authority.
    renounced: !(mintable || canFreeze || balanceMutable || closable),
    hiddenOwner: null,
    openSource: null, // N/A for SPL programs
    top10Percent: goplusTop10Percent(d.holders),
    balanceMutable,
    closable,
    transferHook: status('transfer_hook'),
    hasCooldown: false,
    hasAntiWhale: null,
    maxTxPercent: null,
    lpBurnedPercent: burn,
    lpLockedPercent: lockers.length ? Math.min(100, locked * 100) : null,
    lpLockers: lockers.slice(0, 3),
  };
}

app.get('/api/token-tax', async (req, res) => {
  const { address, networkId } = req.query;
  if (!address) return res.status(400).json({ error: 'Missing address' });

  const netId = parseInt(networkId) || 1;
  const isSolana = netId === SOLANA_NETWORK_ID;
  const cacheKey = `${netId}:${String(address).toLowerCase()}`;
  const cached = _tokenTaxCache.get(cacheKey);
  if (cached && Date.now() < cached.expires) {
    res.set('Cache-Control', 'public, s-maxage=1800, stale-while-revalidate=3600');
    return res.json(cached.data);
  }

  try {
    const url = isSolana
      ? `https://api.gopluslabs.io/api/v1/solana/token_security?contract_addresses=${encodeURIComponent(address)}`
      : `https://api.gopluslabs.io/api/v1/token_security/${netId}?contract_addresses=${encodeURIComponent(address)}`;
    const headers = await goplusAuthHeaders();
    const response = await fetch(url, { headers, signal: AbortSignal.timeout(8000) });
    if (!response.ok) throw new Error(`goplus ${response.status}`);

    const json = await response.json();
    const resultMap = json.result || {};
    // GoPlus keys EVM results by lowercased address; Solana keeps case.
    const entry = resultMap[address] || resultMap[String(address).toLowerCase()];
    if (!entry) {
      // Token not indexed by GoPlus (very fresh / unsupported chain) - short negative cache
      const result = { buyTax: null, sellTax: null, isHoneypot: null };
      _tokenTaxCache.set(cacheKey, { data: result, expires: Date.now() + 5 * 60 * 1000 });
      return res.json(result);
    }

    const result = isSolana ? mapGoPlusSolana(entry) : mapGoPlusEvm(entry, address);
    const holderN = parseInt(entry.holder_count, 10);
    const ttl = Number.isFinite(holderN) && holderN >= TOKEN_TAX_ESTABLISHED_HOLDERS
      ? TOKEN_TAX_TTL_ESTABLISHED : TOKEN_TAX_TTL_FRESH;
    _tokenTaxCache.set(cacheKey, { data: result, expires: Date.now() + ttl });

    // Garbage sweep
    if (_tokenTaxCache.size > 500) {
      const now = Date.now();
      for (const [k, v] of _tokenTaxCache) { if (now >= v.expires) _tokenTaxCache.delete(k); }
    }

    res.set('Cache-Control', 'public, s-maxage=1800, stale-while-revalidate=3600');
    res.json(result);
  } catch {
    res.json({ buyTax: null, sellTax: null, isHoneypot: null });
  }
});

