// SPECTRE BRAIN — DOSSIER-SCOPED PROXIES
// Per-asset views into the Tier-6 brain consciousness for the Dossier "Brain Says" panel.
// REGISTERED BEFORE the dossier router mount so /:asset/brain-* doesn't fall into
// the dossier router's catch-all /:chain/:ca route.
// ═══════════════════════════════════════════════════════════════════════════════
// Use SPECTRE_API_ORIGIN (e.g. http://204.168.244.18:3850) to bypass Cloudflare bot-fight
// when running server-to-server. Falls back to public DNS which may 403 from non-browser UAs.
const BRAIN_PROXY_BASE = (process.env.SPECTRE_API_ORIGIN || 'https://api.spectreai.io').replace(/\/$/, '') + '/v1/brain';
const BRAIN_PROXY_KEY = process.env.SPECTRE_DATA_API_KEY;
if (!BRAIN_PROXY_KEY) console.warn('[server] SPECTRE_DATA_API_KEY not set - brain proxy endpoints will fail');

async function brainProxyFetch(path, signal) {
  const url = `${BRAIN_PROXY_BASE}/${path}`;
  const r = await fetch(url, { headers: { 'X-API-Key': BRAIN_PROXY_KEY }, signal: signal || AbortSignal.timeout(15000) });
  if (!r.ok) throw new Error(`brain ${path} returned ${r.status}`);
  return r.json();
}

// Fallback: unified /v1/dossier/:asset. Used when /v1/brain/ask is 502
// (LLM upstream dead). Returns per-asset brain_voice + voices + the macro
// thesis so the dossier UI never sees empty content.
async function dossierFallbackFetch(asset, signal) {
  const base = (process.env.SPECTRE_API_ORIGIN || 'http://204.168.244.18:3850').replace(/\/$/, '');
  const url = `${base}/v1/dossier/${encodeURIComponent(asset.toLowerCase())}`;
  const r = await fetch(url, { headers: { 'X-API-Key': BRAIN_PROXY_KEY }, signal: signal || AbortSignal.timeout(8000) });
  if (!r.ok) throw new Error(`dossier ${asset} returned ${r.status}`);
  const j = await r.json();
  return j?.data || j || {};
}

// /api/dossier/:asset/brain-thesis
// Primary: /v1/brain/ask (LLM-generated per-asset thesis)
// Fallback: /v1/dossier/:asset extract — macro thesis + per-asset brain_voice + voices
// Never 502s — returns whatever's available with a `source` flag.
app.get('/api/dossier/:asset/brain-thesis', async (req, res) => {
  const asset = String(req.params.asset || '').toUpperCase().slice(0, 12);
  if (!asset || !/^[A-Z0-9]+$/.test(asset)) return res.status(400).json({ error: 'invalid asset' });
  // Try primary: brain /ask
  try {
    const q = encodeURIComponent(`current thesis for ${asset}`);
    const j = await brainProxyFetch(`ask?q=${q}&asset=${asset}`);
    return res.json({
      asset,
      source: 'brain_ask',
      thesis: j.answer || null,
      voice_280: j.voice_280 || null,
      voice_280_meta: j.voice_280_meta || null,
      raw_thesis: j.raw_answer || null,
      fact_check: j.fact_check || null,
      sources_used: j.meta?.sources_used || null,
      generated_at: j.meta?.generated_at || new Date().toISOString(),
    });
  } catch (e) {
    console.warn('[brain-thesis] /ask failed, falling back to dossier:', e.message);
  }
  // Fallback: pull from unified dossier so the UI never sees empty content
  try {
    const d = await dossierFallbackFetch(asset);
    const macroThesis = d.thesis || {};
    const brainVoice = d.brain_voice || null;
    const voices = Array.isArray(d.voices) ? d.voices : [];
    // Prefer per-asset brain_voice text if present; otherwise the macro summary
    const thesisText = brainVoice?.voice_280
      || brainVoice?.text
      || voices[0]?.voice_280
      || voices[0]?.text
      || macroThesis.summary
      || null;
    return res.json({
      asset,
      source: brainVoice ? 'brain_voice' : (voices.length ? 'voices' : 'macro_fallback'),
      thesis: thesisText,
      voice_280: brainVoice?.voice_280 || voices[0]?.voice_280 || null,
      voice_280_meta: brainVoice?.meta || voices[0]?.meta || null,
      raw_thesis: macroThesis.summary || null,
      macro_thesis: {
        bull_case: macroThesis.bull_case || [],
        bear_case: macroThesis.bear_case || [],
        neutral_case: macroThesis.neutral_case || null,
        conviction: macroThesis.conviction || null,
        confidence: macroThesis.confidence ?? null,
        horizon: macroThesis.horizon || null,
        last_updated: macroThesis.last_updated || null,
      },
      voices: voices.slice(0, 10),
      fact_check: d.fact_check || null,
      sources_used: d.brain_sources_used || d.metadata?.sources_used || null,
      generated_at: d.metadata?.generated_at || new Date().toISOString(),
      degraded: true,
      degraded_reason: 'brain /ask upstream unavailable, served from dossier composite',
    });
  } catch (e2) {
    console.error('[brain-thesis] both upstreams failed:', e2.message);
    res.status(502).json({ error: 'brain-thesis unavailable', asset, primary: 'brain_ask_failed', fallback: e2.message });
  }
});

