// /api/dossier/:asset/brain-stance
// Primary: brain state-of-mind + voice/tide
// Fallback: extract conviction + brain_voice from unified dossier so the
// stance card always renders something on a per-asset page.
app.get('/api/dossier/:asset/brain-stance', async (req, res) => {
  const asset = String(req.params.asset || '').toUpperCase().slice(0, 12);
  if (!asset || !/^[A-Z0-9]+$/.test(asset)) return res.status(400).json({ error: 'invalid asset' });
  try {
    const [som, voiceTide, dossierR] = await Promise.allSettled([
      brainProxyFetch(`state-of-mind`),
      brainProxyFetch(`voice/tide?asset=${asset}`),
      dossierFallbackFetch(asset),
    ]);
    const j = som.status === 'fulfilled' ? som.value : null;
    const voice = voiceTide.status === 'fulfilled' ? voiceTide.value : null;
    const d = dossierR.status === 'fulfilled' ? dossierR.value : null;

    // state-of-mind sometimes wraps in { data: {...} }
    const somData = j?.data || j || {};
    const assetSignals = (somData.critical_signals_6h || [])
      .filter(s => Array.isArray(s.assets) && s.assets.map(a => String(a).toUpperCase()).includes(asset))
      .slice(0, 5);
    const assetObservations = (somData.recent_high_importance_observations || [])
      .filter(o => String(o.asset || '').toUpperCase() === asset)
      .slice(0, 5);

    // If brain returned nothing for this asset, pull asset-level conviction from dossier
    const dossierConv = d?.conviction || {};
    const dossierBrainVoice = d?.brain_voice || null;

    res.json({
      asset,
      stances: {
        wave: somData.synthesis?.wave?.stance || null,
        tide: somData.synthesis?.tide?.stance || dossierConv.tier === 'tide' ? dossierConv.stance : null,
        ocean: somData.synthesis?.ocean?.stance || null,
        latest_conviction: somData.latest_conviction?.market_stance || dossierConv.stance || null,
      },
      asset_conviction: {
        tier: dossierConv.tier || null,
        stance: dossierConv.stance || null,
        score: dossierConv.score ?? null,
        has_conviction: !!dossierConv.has_conviction,
        last_changed_at: dossierConv.last_changed_at || null,
      },
      coherence: somData.stance_coherence || null,
      voice_tide: voice?.voice_280 || dossierBrainVoice?.voice_280 || null,
      voice_alpha: voice?.voice_alpha || dossierBrainVoice?.voice_alpha || null,
      asset_critical_signals: assetSignals,
      asset_observations: assetObservations,
      asset_voices: Array.isArray(d?.voices) ? d.voices.slice(0, 5) : [],
      sources: {
        state_of_mind: som.status,
        voice_tide: voiceTide.status,
        dossier: dossierR.status,
      },
      generated_at: somData.generated_at || new Date().toISOString(),
    });
  } catch (e) {
    console.error('[brain-stance] error:', e.message);
    res.status(502).json({ error: 'brain-stance unavailable', asset });
  }
});

