  'OUSG','VUSD','MIM','MKUSD','TGBP','EUROC','FEI','SAI','VAI','BILL','JTRSY',
  'BUIDL','SUSDS','SUSDE','EURI','APXUSD','APYUSD','BFUSD','SBTC','USTC',
