let binanceCatalogCache = { pairs: [], updatedAt: 0 };
async function refreshBinanceCatalog() {
  const r = await fetch('https://api.binance.com/api/v3/exchangeInfo', {
    signal: AbortSignal.timeout(10_000),
  });
  if (!r.ok) throw new Error(`Binance exchangeInfo ${r.status}`);
  const data = await r.json();
  const ascii = /^[A-Z0-9]+$/;
  const pairs = (data.symbols || [])
    .filter((s) => s.quoteAsset === 'USDT' && s.status === 'TRADING')
    .map((s) => s.baseAsset)
    .filter((b) => ascii.test(b) && !BINANCE_CATALOG_STABLES.has(b) && !BINANCE_CATALOG_WRAPPED.has(b))
    .sort();
  if (pairs.length === 0) {
    // 1-minute negative cache on empty upstream so we don't hammer Binance.
    binanceCatalogCache.updatedAt = Date.now() - (BINANCE_CATALOG_TTL_MS - 60_000);
    throw new Error('Binance exchangeInfo returned no USDT pairs');
  }
  binanceCatalogCache = { pairs, updatedAt: Date.now() };
  return binanceCatalogCache;
}
const binanceUsdtPairsHandler = async (req, res) => {
  try {
    const stale = Date.now() - binanceCatalogCache.updatedAt > BINANCE_CATALOG_TTL_MS;
    if (stale || binanceCatalogCache.pairs.length === 0) {
      await refreshBinanceCatalog();
    }
    res.setHeader('Cache-Control', 'public, s-maxage=3600, stale-while-revalidate=86400');
    res.json(binanceCatalogCache);
  } catch (err) {
    console.error('Binance catalog error:', err.message);
    if (binanceCatalogCache.pairs.length > 0) {
      res.setHeader('Cache-Control', 'public, s-maxage=60');
      return res.json(binanceCatalogCache);
    }
    res.status(502).json({ error: 'Binance catalog unavailable', pairs: [] });
  }
};
app.get('/api/binance-usdt-pairs', binanceUsdtPairsHandler);
app.get('/api/binance/usdt-pairs', binanceUsdtPairsHandler);

// ── Binance klines — dev parity with prod (vercel.json -> /api/data-api?fn=extended-proxy&route=binance-klines) ──
// The chart adapter (src/chart/adapters/binanceAdapter.js) and Traders Corner
// PriceCard fetch /api/binance-klines for OHLCV. Prod serves it via the
// extended-proxy handler; the dev Express server had NO matching route, so
// every local chart 404'd here and silently fell back to the slower Codex/UDF
// path. This restores dev/prod parity. Returns the RAW Binance kline array
// (the adapter calls normalizeBinanceKlines on it). Local IPs aren't geo-blocked
// by Binance, so a direct proxy is enough (prod needs the allorigins fallback).
const binanceKlinesCache = new Map();
app.get('/api/binance-klines', async (req, res) => {
  const symbol = (req.query.symbol || 'BTCUSDT').toString();
  const interval = (req.query.interval || '1h').toString();
  const limit = Math.min(parseInt(req.query.limit) || 100, 1000);
  const startTime = Number.isFinite(parseInt(req.query.startTime)) ? parseInt(req.query.startTime) : null;
  const endTime = Number.isFinite(parseInt(req.query.endTime)) ? parseInt(req.query.endTime) : null;
  // A specific time-range is a unique pagination window — only cache latest-N.
  const cacheable = startTime == null && endTime == null;
  const cacheKey = `bk:${symbol}:${interval}:${limit}`;
  if (cacheable) {
    const cached = getCached(binanceKlinesCache, cacheKey, 15000);
    if (cached) { res.setHeader('Cache-Control', 'public, s-maxage=15'); return res.json(cached); }
  }
  let url = `https://api.binance.com/api/v3/klines?symbol=${encodeURIComponent(symbol)}&interval=${interval}&limit=${limit}`;
  if (startTime != null) url += `&startTime=${startTime}`;
  if (endTime != null) url += `&endTime=${endTime}`;
  try {
    const r = await fetch(url, { signal: AbortSignal.timeout(5000) });
    if (r.ok) {
      const data = await r.json();
      if (cacheable) setCached(binanceKlinesCache, cacheKey, data, 15000);
      res.setHeader('Cache-Control', cacheable ? 'public, s-maxage=15' : 'public, s-maxage=60');
      return res.json(data);
    }
    console.error(`[binance-klines] direct failed: ${r.status} ${symbol} ${interval}`);
  } catch (err) {
    console.error('[binance-klines] direct error:', err.message);
  }
  if (cacheable) {
    const stale = binanceKlinesCache.get(cacheKey);
    if (stale && stale.data) return res.json(stale.data);
  }
  return res.status(502).json({ error: 'Binance unavailable' });
});

// ── /api/data-api DefiLlama passthroughs — dev parity with prod ──
// Prod serves /api/data-api?fn=extended-proxy&route=llama-* via the Vercel
// serverless api/data-api.js -> extended-proxy handleLlama*Passthrough. The
// ZIGChain page (useZIGTvlHistory + useZigComparison) fetches those routes
// DIRECTLY (not a friendly /api/* path), and the dev Express server had NO
// /api/data-api route at all -> every local TVL chart 404'd -> "TVL history
// unavailable". This restores dev/prod parity for the llama routes only;
// unknown (fn,route) pairs still 404 exactly as before (no regression).
const llamaProxyCache = new Map();
app.get('/api/data-api', async (req, res) => {
  const fn = String(req.query.fn || '');
  if (fn !== 'extended-proxy') {
    return res.status(404).json({ error: `data-api dev shim: unhandled fn '${fn}'` });
  }
  const route = String(req.query.route || '');
  const chain = String(req.query.chain || '').trim();
  const slug = String(req.query.slug || '').trim();
  const chainOk = /^[A-Za-z0-9._-]{1,40}$/.test(chain);
  const slugOk = /^[A-Za-z0-9._-]{1,60}$/.test(slug);
  const LLAMA = 'https://api.llama.fi';
  let upstream = null;
  if (route === 'llama-lite-charts' && chainOk) upstream = `${LLAMA}/lite/charts/${encodeURIComponent(chain)}`;
  else if (route === 'llama-chain-tvl-history' && chainOk) upstream = `${LLAMA}/v2/historicalChainTvl/${encodeURIComponent(chain)}`;
  else if (route === 'llama-protocol-raw' && slugOk) upstream = `${LLAMA}/protocol/${encodeURIComponent(slug)}`;
  else if (route === 'llama-chains-raw') upstream = `${LLAMA}/v2/chains`;
  else return res.status(404).json({ error: `data-api dev shim: unhandled route '${route}'` });

  const cacheKey = `llama:${route}:${chain}:${slug}`;
  const cached = getCached(llamaProxyCache, cacheKey, 60000);
  if (cached) { res.setHeader('Cache-Control', 'public, s-maxage=60'); return res.json(cached); }
  try {
    const r = await fetch(upstream, { headers: { Accept: 'application/json' }, signal: AbortSignal.timeout(12000) });
    if (!r.ok) return res.status(r.status).json({ error: `Llama ${r.status}` });
    const data = await r.json();
    setCached(llamaProxyCache, cacheKey, data, 60000);
    res.setHeader('Cache-Control', 'public, s-maxage=60');
    return res.json(data);
  } catch (err) {
    console.error('[data-api llama shim] error:', err.message);
    return res.status(502).json({ error: 'llama proxy failed', message: err.message });
  }
});

// ═══════════════════════════════════════════════════════════════════════════════
// DERIVATIVES PROXY — Forward requests to Binance Futures, Bybit, OKX, Deribit
// Browser can't call these directly due to CORS. Same pattern as binance ticker.
// ═══════════════════════════════════════════════════════════════════════════════

const DERIVATIVES_TARGETS = {
  binance: 'https://fapi.binance.com',
  'binance-spot': 'https://api.binance.com',
  bybit: 'https://api.bybit.com',
  okx: 'https://www.okx.com',
  deribit: 'https://www.deribit.com',
};

const derivativesCache = new Map();
const DERIV_CACHE_TTL = 10_000; // 10s - derivatives data is time-sensitive
_standaloneCaches.push({ map: derivativesCache, ttlField: 'ts', ttlMs: DERIV_CACHE_TTL });

app.get('/api/derivatives/:exchange/*', async (req, res) => {
  const { exchange } = req.params;
  const baseUrl = DERIVATIVES_TARGETS[exchange];
  if (!baseUrl) return res.status(400).json({ error: `Unknown exchange: ${exchange}` });

  // Reconstruct the path after /api/derivatives/:exchange/
  const restPath = req.params[0];
  const qs = new URLSearchParams(req.query).toString();
  const targetUrl = `${baseUrl}/${restPath}${qs ? '?' + qs : ''}`;

  // Cache key is the full target URL
  const cached = derivativesCache.get(targetUrl);
  if (cached && Date.now() - cached.ts < DERIV_CACHE_TTL) {
    res.setHeader('Cache-Control', 'public, max-age=10');
    res.setHeader('X-Cache', 'HIT');
    return res.json(cached.data);
  }

  try {
    const response = await fetch(targetUrl, {
      headers: { Accept: 'application/json' },
      signal: AbortSignal.timeout(10000),
    });
    if (!response.ok) throw new Error(`${exchange} ${response.status} ${response.statusText}`);
    const data = await response.json();
    derivativesCache.set(targetUrl, { data, ts: Date.now() });
    res.setHeader('Cache-Control', 'public, max-age=10');
    res.setHeader('X-Cache', 'MISS');
    res.json(data);
  } catch (err) {
    // Return stale cache if available
    if (cached) {
      res.setHeader('X-Cache', 'STALE');
      return res.json(cached.data);
    }
    console.error(`[Derivatives] ${exchange} proxy error:`, err.message);
    res.status(502).json({ error: `${exchange} unavailable` });
  }
});

// ═══════════════════════════════════════════════════════════════════════════════
// COINGLASS — Accurate OI, liquidation, funding, L/S data
// Requires COINGLASS_API_KEY env var
// ═══════════════════════════════════════════════════════════════════════════════

const coinglassCache = new Map();
const CG_GLASS_TTL = 30_000; // 30s - derivatives data is time-sensitive
_standaloneCaches.push({ map: coinglassCache, ttlField: 'ts', ttlMs: CG_GLASS_TTL });

async function fetchCoinglass(path) {
  const key = process.env.COINGLASS_API_KEY;
  if (!key) throw new Error('COINGLASS_API_KEY not configured');
  const url = `https://open-api-v4.coinglass.com/api${path}`;
  const res = await fetch(url, {
    headers: { 'CG-API-KEY': key, Accept: 'application/json' },
    signal: AbortSignal.timeout(10000),
  });
  if (!res.ok) throw new Error(`CoinGlass ${res.status} ${res.statusText}`);
  const json = await res.json();
  if (json.code !== '0') throw new Error(`CoinGlass error: ${json.msg}`);
  return json.data;
}

// Spectre data-api fallback for the CoinGlass totals (2026-07-02). With no
// COINGLASS_API_KEY these routes 502'd, and the client's direct Hetzner
// fallback times out whenever the data-api has a slow spell - the Command
// Center strip and the Liquidation Heatmap header then showed +$0 across the
// board. The server derives the same row shape from our own /v1/derivatives
// endpoints instead, with the 30s cache + stale-serving this block already has.
const SPECTRE_V1_ORIGIN = (process.env.SPECTRE_API_ORIGIN || 'http://204.168.244.18:3850').replace(/\/$/, '');
const SPECTRE_V1_KEY = process.env.SPECTRE_DATA_BRIDGE_KEY
  || process.env.SPECTRE_DATA_API_KEY
  || 'spectre_dev_internal_key_change_me';
async function fetchSpectreV1(path) {
  const r = await fetch(`${SPECTRE_V1_ORIGIN}/v1${path}`, {
    headers: { 'X-API-Key': SPECTRE_V1_KEY, Accept: 'application/json' },
    signal: AbortSignal.timeout(15000),
  });
  if (!r.ok) throw new Error(`spectre v1 ${path} ${r.status}`);
  return r.json();
}
async function spectreTotalOiUsd() {
  const j = await fetchSpectreV1('/derivatives/open-interest?limit=500');
  let total = Number(j?.meta?.total_oi_usd) || 0;
  if (!total) {
    const rows = Array.isArray(j?.data) ? j.data : [];
    total = rows.reduce((s, r) => s + (Number(r?.oi_usd ?? r?.total_oi_usd) || 0), 0);
  }
  if (!total) throw new Error('spectre oi empty');
  return total;
}
async function spectreLiqWindow(range = '24h') {
  const j = await fetchSpectreV1('/derivatives/liquidation-windows');
  const w = j?.data?.windows?.[range] || j?.windows?.[range];
  const long = Number(w?.long) || 0;
  const short = Number(w?.short) || 0;
  const total = Number(w?.total) || long + short;
  if (!total) throw new Error(`spectre liq window ${range} empty`);
  return { long, short, total };
}

// GET /api/coinglass/coins-markets?per_page=50&page=1
// Returns per-coin OI, liquidations (all windows), funding, volume, L/S ratios
app.get('/api/coinglass/coins-markets', async (req, res) => {
  const perPage = parseInt(req.query.per_page) || 50;
  const page = parseInt(req.query.page) || 1;
  const cacheKey = `coins-markets-${perPage}-${page}`;
  const cached = coinglassCache.get(cacheKey);
  if (cached && Date.now() - cached.ts < CG_GLASS_TTL) {
    res.setHeader('X-Cache', 'HIT');
    return res.json(cached.data);
  }
  try {
    const data = await fetchCoinglass(`/futures/coins-markets?per_page=${perPage}&page=${page}`);
    coinglassCache.set(cacheKey, { data, ts: Date.now() });
    res.setHeader('Cache-Control', 'public, s-maxage=30');
    res.json(data);
  } catch (err) {
    if (cached) { res.setHeader('X-Cache', 'STALE'); return res.json(cached.data); }
    console.error('[CoinGlass] coins-markets error:', err.message);
    res.status(502).json({ error: 'CoinGlass unavailable' });
  }
});

// GET /api/coinglass/total-oi
// Returns aggregate OI across all exchanges as { data: [rows] } - both
// consumers (use-market-intelligence, tradersCornerApi) sum
// rows[].open_interest_usd from a `data` array. Falls back to the Spectre
// data-api aggregate when CoinGlass is keyless/unavailable.
app.get('/api/coinglass/total-oi', async (req, res) => {
  const cacheKey = 'total-oi';
  const cached = coinglassCache.get(cacheKey);
  if (cached && Date.now() - cached.ts < CG_GLASS_TTL) {
    res.setHeader('X-Cache', 'HIT');
    return res.json(cached.data);
  }
  try {
    let payload;
    try {
      const rows = await fetchCoinglass('/futures/open-interest/exchange-list?symbol=');
      payload = { data: Array.isArray(rows) ? rows : [], source: 'coinglass' };
      if (payload.data.length === 0) throw new Error('coinglass oi empty');
    } catch (cgErr) {
      const total = await spectreTotalOiUsd();
      payload = { data: [{ exchange: 'Aggregate', open_interest_usd: total }], source: 'spectre-data-api' };
    }
    coinglassCache.set(cacheKey, { data: payload, ts: Date.now() });
    res.setHeader('Cache-Control', 'public, s-maxage=30');
    res.json(payload);
  } catch (err) {
    if (cached) { res.setHeader('X-Cache', 'STALE'); return res.json(cached.data); }
    console.error('[CoinGlass] total-oi error:', err.message);
    res.status(502).json({ error: 'CoinGlass unavailable' });
  }
});

// GET /api/coinglass/total-liquidations?range=24h
// Returns aggregate liquidations for a window as { data: [rows] } - consumers
// sum rows[].long/short_liquidation_usd from a `data` array. Falls back to the
// Spectre data-api liquidation windows when CoinGlass is keyless/unavailable.
app.get('/api/coinglass/total-liquidations', async (req, res) => {
  const range = req.query.range || '24h';
  const cacheKey = `total-liq-${range}`;
  const cached = coinglassCache.get(cacheKey);
  if (cached && Date.now() - cached.ts < CG_GLASS_TTL) {
    res.setHeader('X-Cache', 'HIT');
    return res.json(cached.data);
  }
  try {
    let payload;
    try {
      const rows = await fetchCoinglass(`/futures/liquidation/exchange-list?symbol=&range=${range}`);
      payload = { data: Array.isArray(rows) ? rows : [], source: 'coinglass' };
      if (payload.data.length === 0) throw new Error('coinglass liq empty');
    } catch (cgErr) {
      const w = await spectreLiqWindow(range);
      payload = {
        data: [{ exchange: 'Aggregate', long_liquidation_usd: w.long, short_liquidation_usd: w.short }],
        source: 'spectre-data-api',
      };
    }
    coinglassCache.set(cacheKey, { data: payload, ts: Date.now() });
    res.setHeader('Cache-Control', 'public, s-maxage=30');
    res.json(payload);
  } catch (err) {
    if (cached) { res.setHeader('X-Cache', 'STALE'); return res.json(cached.data); }
    console.error('[CoinGlass] total-liquidations error:', err.message);
    res.status(502).json({ error: 'CoinGlass unavailable' });
  }
});

// ═══════════════════════════════════════════════════════════════════════════════
// TOKEN EXCHANGES — Real exchange data from CoinGecko + DexScreener
// Never return fabricated exchange listings
// ═══════════════════════════════════════════════════════════════════════════════

const exchangeCache = new Map(); // symbol -> { data, ts }
const EXCHANGE_CACHE_TTL = 60 * 60 * 1000; // 1 hour
_standaloneCaches.push({ map: exchangeCache, ttlField: 'ts', ttlMs: EXCHANGE_CACHE_TTL });

// CoinGecko ID lookup — same as frontend majorTokens.js
const SYMBOL_TO_CG_ID = {
  BTC: 'bitcoin', ETH: 'ethereum', SOL: 'solana', BNB: 'binancecoin',
  XRP: 'ripple', ADA: 'cardano', DOGE: 'dogecoin', AVAX: 'avalanche-2',
  DOT: 'polkadot', LINK: 'chainlink', UNI: 'uniswap', MATIC: 'matic-network',
  ARB: 'arbitrum', OP: 'optimism', NEAR: 'near', APT: 'aptos', SUI: 'sui',
  INJ: 'injective-protocol', AAVE: 'aave', MKR: 'maker', PEPE: 'pepe',
  WIF: 'dogwifcoin', BONK: 'bonk', SHIB: 'shiba-inu', FET: 'fetch-ai',
  RNDR: 'render-token', RENDER: 'render-token', TAO: 'bittensor',
  SPECTRE: 'spectre-ai', LTC: 'litecoin', ATOM: 'cosmos', FIL: 'filecoin',
  GRT: 'the-graph', CRV: 'curve-dao-token', LDO: 'lido-dao',
};

// Token address lookup for DexScreener fallback
const SYMBOL_TO_ADDRESS = {
  SPECTRE: '0x9cf0ed013e67db12ca3af8e7506fe401aa14dad6',
};

/**
 * GET /api/token-exchanges?symbol=BTC
 * Returns { exchanges: ['Binance', 'Coinbase', ...], source: 'coingecko'|'dexscreener' }
 */
app.get('/api/token-exchanges', async (req, res) => {
  const symbol = (req.query.symbol || '').toUpperCase();
  if (!symbol) return res.status(400).json({ error: 'symbol required' });

  // Check cache
  const cached = exchangeCache.get(symbol);
  if (cached && (Date.now() - cached.ts) < EXCHANGE_CACHE_TTL) {
    res.setHeader('Cache-Control', 'public, max-age=3600');
    return res.json(cached.data);
  }

  try {
    let exchanges = [];
    let source = '';

    // 1. Try CoinGecko /coins/{id}/tickers (has CEX data)
    const cgId = SYMBOL_TO_CG_ID[symbol];
    if (cgId) {
      try {
        const url = `${COINGECKO_BASE}/coins/${cgId}/tickers?include_exchange_logo=false&depth=false&order=trust_score_desc`;
        const opts = { headers: { Accept: 'application/json' } };
        if (COINGECKO_API_KEY) opts.headers[COINGECKO_HEADER_KEY] = COINGECKO_API_KEY;
        const cgRes = await fetch(url, opts);
        if (cgRes.ok) {
          const data = await cgRes.json();
          const tickers = data.tickers || [];
          // Well-known exchanges get priority (tier 1 CEXes + major DEXes)
          const knownExchanges = new Set([
            'Binance', 'Coinbase Exchange', 'Kraken', 'OKX', 'Bybit',
            'KuCoin', 'Bitfinex', 'Bitstamp', 'Crypto.com Exchange',
            'HTX', 'Gate.io', 'Upbit', 'MEXC', 'Bitget',
            'Uniswap V2 (Ethereum)', 'Uniswap V3 (Ethereum)', 'Uniswap V3 (Arbitrum One)',
            'Jupiter', 'Raydium', 'PancakeSwap V2 (BSC)', 'PancakeSwap V3 (BSC)',
            'Trader Joe', 'Curve (Ethereum)', 'SushiSwap',
          ]);
          // Sort: known exchanges first, then by trust_score, then volume
          const trustOrder = { green: 0, yellow: 1, red: 2 };
          const sorted = [...tickers].sort((a, b) => {
            const aKnown = knownExchanges.has(a.market?.name) ? 0 : 1;
            const bKnown = knownExchanges.has(b.market?.name) ? 0 : 1;
            if (aKnown !== bKnown) return aKnown - bKnown;
            const ta = trustOrder[a.trust_score] ?? 3;
            const tb = trustOrder[b.trust_score] ?? 3;
            if (ta !== tb) return ta - tb;
            return (b.converted_volume?.usd || 0) - (a.converted_volume?.usd || 0);
          });
          // Deduplicate exchange names, prefer known/high-trust first
          const seen = new Set();
          for (const t of sorted) {
            let name = t.market?.name;
            if (!name || seen.has(name)) continue;
            seen.add(name);
            // Shorten verbose exchange names for display
            name = name.replace(' Exchange', '').replace(' (Ethereum)', '').replace(' (BSC)', '').replace(' (Arbitrum One)', '');
            exchanges.push(name);
          }
          if (exchanges.length > 0) source = 'coingecko';
        }
      } catch (e) {
        console.warn(`CoinGecko tickers for ${symbol}:`, e.message);
      }
    }

    // 2. Fallback: DexScreener (DEX data, works for any on-chain token)
    if (exchanges.length === 0) {
      const address = SYMBOL_TO_ADDRESS[symbol];
      if (address) {
        try {
          const dsRes = await fetch(`https://api.dexscreener.com/latest/dex/tokens/${address}`);
          if (dsRes.ok) {
            const data = await dsRes.json();
            const pairs = data.pairs || [];
            const seen = new Set();
            for (const p of pairs) {
              // Capitalise DEX name nicely
              const dex = p.dexId;
              if (dex && !seen.has(dex)) {
                seen.add(dex);
                const name = dex.charAt(0).toUpperCase() + dex.slice(1).replace(/v(\d)/, ' V$1');
                exchanges.push(name);
              }
            }
            if (exchanges.length > 0) source = 'dexscreener';
          }
        } catch (e) {
          console.warn(`DexScreener tickers for ${symbol}:`, e.message);
        }
      }
    }

    // Take top 5 exchanges max
    const result = { exchanges: exchanges.slice(0, 5), source };

    // Only cache non-empty results — empty means API was rate-limited, retry next time
    if (exchanges.length > 0) {
      evictIfFull(exchangeCache, CACHE_MAX_ENTRIES);
      exchangeCache.set(symbol, { data: result, ts: Date.now() });
    }

    res.setHeader('Cache-Control', 'public, max-age=3600');
    res.json(result);
  } catch (err) {
    console.error('Token exchanges error:', err.message);
    res.status(500).json({ error: 'Failed to fetch exchanges' });
  }
});

/**
 * GET /api/token-markets?symbol=BTC
 * Returns full market/ticker data for a token from CoinGecko tickers endpoint.
 * { markets: [{ exchange, pair, price, depthPlus2, depthMinus2, volume24h, volumePct, liquidity, type }], source }
 */
const marketsCache = new Map();
const MARKETS_CACHE_TTL = 10 * 60 * 1000; // 10 min (CoinGecko free tier is rate-limited)

const KNOWN_DEX_NAMES = new Set([
  'Uniswap', 'Uniswap V2', 'Uniswap V3', 'Uniswap V4', 'SushiSwap', 'PancakeSwap', 'PancakeSwap V2', 'PancakeSwap V3',
  'Curve', 'Balancer', 'Balancer V2', 'Jupiter', 'Raydium', 'Orca', 'Trader Joe',
  'QuickSwap', 'Camelot', 'Velodrome', 'Aerodrome', 'Osmosis', 'THORSwap',
  'Dexalot', 'SoDEX', 'Lighter', 'Fluid', 'O2', 'Maverick Protocol',
  '1inch', 'ParaSwap', 'KyberSwap', 'DODO', 'ShibaSwap', 'SpookySwap',
  'Pangolin', 'Biswap', 'Lifinity', 'Meteora', 'Orca', 'Serum',
  'GMX', 'dYdX', 'Vertex', 'Drift', 'Hyperliquid',
]);

// Tier-1 exchanges get priority in sorting (same list as /api/token-exchanges).
// Names match CoinGecko's exact `market.name` values — verified against the
// CG tickers payload for BTC: "Gate" not "Gate.io", "Coinbase Exchange" stays
// raw because shortName strip turns it into "Coinbase".
const TIER1_EXCHANGES = new Set([
  // CEX — top-of-book real volume
  'Binance', 'Coinbase Exchange', 'Coinbase', 'Kraken', 'OKX', 'Bybit',
  'KuCoin', 'Bitfinex', 'Bitstamp', 'Crypto.com Exchange', 'Crypto.com',
  'HTX', 'Gate', 'Gate.io', 'Upbit', 'MEXC', 'Bitget', 'BingX', 'Bithumb',
  'Gemini',
  // DEX
  'Uniswap V2 (Ethereum)', 'Uniswap V3 (Ethereum)', 'Uniswap V3 (Arbitrum One)',
  'Jupiter', 'Raydium', 'PancakeSwap V2 (BSC)', 'PancakeSwap V3 (BSC)',
  'Trader Joe', 'Curve (Ethereum)', 'SushiSwap',
]);

// Mid-tier — legitimate but smaller. Get rank-2 (below tier-1, above unknown).
const TIER2_EXCHANGES = new Set([
  'BitMart', 'WhiteBIT', 'Bitvavo', 'LBank', 'XT.com', 'Phemex', 'Bitrue',
  'CoinEx', 'Poloniex', 'Bittrex', 'AscendEX', 'BTSE', 'OrangeX', 'BitForex',
  'Coinone', 'Korbit', 'Indodax', 'OKCoin', 'Probit Global',
]);

// Known wash-trading / sketchy venues — push to bottom. The free-tier CG API
// strips `trust_score` so we can't rely on it; this list mirrors what CG's
// trust-score model historically marked yellow/red for BTC tickers.
const WASH_TRADE_EXCHANGES = new Set([
  'BTCC', 'Azbit', 'Pionex', 'CoinUp.io', 'KCEX', 'GroveX', 'CoinW', 'BVOX',
  'Biconomy.com', 'P2B', 'CITEX', 'Hotbit', 'BiONE', 'Bitkub', 'Toobit',
  'BTSE Futures', 'BHEX', 'Hibt', 'BitForex', 'Coinsbit', 'P2PB2B',
]);

// Cache for resolved CoinGecko IDs (symbol → cgId)
const cgIdResolveCache = new Map();
const CG_RESOLVE_TTL = 24 * 60 * 60 * 1000; // 24h

async function resolveCoinGeckoId(symbol) {
  // 1. Hardcoded mapping (fastest) — try both raw and dehyphenated
  if (SYMBOL_TO_CG_ID[symbol]) return SYMBOL_TO_CG_ID[symbol];
  const symNoHyphen = symbol.replace(/-/g, '');
  if (symNoHyphen !== symbol && SYMBOL_TO_CG_ID[symNoHyphen]) return SYMBOL_TO_CG_ID[symNoHyphen];

  // 2. Cached resolution
  const cached = cgIdResolveCache.get(symbol);
  if (cached && (Date.now() - cached.ts) < CG_RESOLVE_TTL) return cached.id;

  // 3. Dynamic search via CoinGecko (rate-limited)
  // CoinGecko search fails on hyphens (e.g. "PALM-AI" returns empty), so replace with spaces
  const searchQuery = symbol.replace(/-/g, ' ');
  try {
    const url = `${COINGECKO_BASE}/search?query=${encodeURIComponent(searchQuery)}`;
    const searchRes = await cgFetch(url);
    if (searchRes.ok) {
      const data = await searchRes.json();
      const coins = data.coins || [];
      // Match priority: exact symbol > dehyphenated > coin ID matches lowercased symbol
      const symLower = symbol.toLowerCase();
      const match =
        coins.find(c => (c.symbol || '').toUpperCase() === symbol) ||
        coins.find(c => (c.symbol || '').toUpperCase() === symNoHyphen) ||
        coins.find(c => c.id === symLower) ||
        null;
      if (match?.id) {
        cgIdResolveCache.set(symbol, { id: match.id, ts: Date.now() });
        return match.id;
      }
    }
  } catch (e) {
    console.warn(`CoinGecko search for ${symbol}:`, e.message);
  }
  return null;
}

app.get('/api/token-markets', async (req, res) => {
  const symbol = (req.query.symbol || '').toUpperCase();
  if (!symbol) return res.status(400).json({ error: 'symbol required' });

  // Accept optional CoinGecko ID from frontend (avoids search step)
  const clientCgId = req.query.id || null;

  try {
    // Resolve CoinGecko ID first so we can include it in the cache key
    const cgId = clientCgId || await resolveCoinGeckoId(symbol);
    if (!cgId) return res.json({ markets: [], source: '' });

    // Fetch up to 2 pages (500 tickers) to ensure we get both CEX and DEX markets
    const baseUrl = `${COINGECKO_BASE}/coins/${cgId}/tickers?include_exchange_logo=true&depth=true&order=volume_desc&per_page=250`;
    let tickers = [];

    const page1Res = await cgFetch(`${baseUrl}&page=1`);
    if (!page1Res.ok) {
      console.warn(`CoinGecko tickers for ${symbol} (${cgId}): ${page1Res.status}`);
      return res.json({ markets: [], source: '' });
    }
    const page1 = await page1Res.json();
    tickers = page1.tickers || [];

    // Fetch page 2 if page 1 was full (250 results = more pages exist)
    if (tickers.length >= 250) {
      try {
        const page2Res = await cgFetch(`${baseUrl}&page=2`);
        if (page2Res.ok) {
          const page2 = await page2Res.json();
          if (page2.tickers?.length > 0) tickers = tickers.concat(page2.tickers);
        }
      } catch (_) { /* page 2 fetch optional */ }
    }

    // Calculate total volume for volumePct
    let totalVolume = 0;
    for (const t of tickers) {
      totalVolume += (t.converted_volume?.usd || 0);
    }

    // Sort tickers: tier-1 exchanges first, then trust score, then volume
    const trustOrder = { green: 0, yellow: 1, red: 2 };
    const sorted = [...tickers].sort((a, b) => {
      const aT1 = TIER1_EXCHANGES.has(a.market?.name) ? 0 : 1;
      const bT1 = TIER1_EXCHANGES.has(b.market?.name) ? 0 : 1;
      if (aT1 !== bT1) return aT1 - bT1;
      const ta = trustOrder[a.trust_score] ?? 3;
      const tb = trustOrder[b.trust_score] ?? 3;
      if (ta !== tb) return ta - tb;
      return (b.converted_volume?.usd || 0) - (a.converted_volume?.usd || 0);
    });

    // Deduplicate by exchange+pair, prefer higher-ranked entries
    const seen = new Map();
    for (const t of sorted) {
      const rawName = t.market?.name || 'Unknown';
      const pair = `${(t.base || '').toUpperCase()}/${(t.target || '').toUpperCase()}`;
      const key = `${rawName}::${pair}`;
      if (seen.has(key)) continue;

      // Classify as CEX or DEX
      const shortName = rawName
        .replace(' Exchange', '')
        .replace(/ \(Ethereum\)/, '')
        .replace(/ \(BSC\)/, '')
        .replace(/ \(Arbitrum One\)/, '')
        .replace(/ \(Optimism\)/, '')
        .replace(/ \(Base\)/, '')
        .replace(/ \(Polygon\)/, '')
        .replace(/ \(Solana\)/, '');

      const isDex = KNOWN_DEX_NAMES.has(shortName) ||
        /uniswap|sushiswap|pancakeswap|curve|balancer|raydium|jupiter|orca|trader joe|quickswap|camelot|velodrome|aerodrome|osmosis|thorswap|dexalot|sodex|lighter|fluid|maverick|1inch|paraswap|kyberswap|dodo|shibaswap|spookyswap|pangolin|biswap|lifinity|meteora|serum|gmx|dydx|vertex|drift|hyperliquid|swap|dex/i.test(rawName);

      const vol = t.converted_volume?.usd || 0;
      const pct = totalVolume > 0 ? ((vol / totalVolume) * 100) : 0;

      seen.set(key, {
        exchange: shortName,
        exchangeId: t.market?.identifier || null,
        logo: t.market?.logo || null,
        pair,
        price: t.converted_last?.usd || t.last || 0,
        depthPlus2: t.cost_to_move_up_usd || 0,
        depthMinus2: t.cost_to_move_down_usd || 0,
        volume24h: vol,
        volumePct: Math.round(pct * 10) / 10,
        liquidity: (t.cost_to_move_up_usd || 0) + (t.cost_to_move_down_usd || 0),
        type: isDex ? 'dex' : 'cex',
        trustScore: t.trust_score || null,
        tradeUrl: t.trade_url || null,
      });
    }

    // Split into CEX and DEX, keep top of each to ensure both filters have data
    const allMarkets = [...seen.values()];

    // Tier ranking — preserves the curated reputation order across the final
    // top-N slice. Without this, the previous final `.sort(by volume desc)`
    // promoted wash-trade venues (BTCC, Azbit, Pionex, KCEX, ...) above
    // Binance/Coinbase because they self-report inflated volume. Match CG's
    // approach: tier-1 first, tier-2 next, unknown after, wash-trade last.
    const tierRank = (m) => {
      const name = m.exchange;
      if (TIER1_EXCHANGES.has(name)) return 0;
      if (m.trustScore === 'green') return 1;
      if (TIER2_EXCHANGES.has(name)) return 2;
      if (WASH_TRADE_EXCHANGES.has(name)) return 5;
      if (m.trustScore === 'yellow') return 3;
      if (m.trustScore === 'red') return 5;
      return 4; // unknown — between tier-2/yellow and wash-trade
    };
    const tierThenVolume = (a, b) => {
      const ra = tierRank(a);
      const rb = tierRank(b);
      if (ra !== rb) return ra - rb;
      return (b.volume24h || 0) - (a.volume24h || 0);
    };
    const cexMarkets = allMarkets.filter(m => m.type === 'cex').sort(tierThenVolume);
    const dexMarkets = allMarkets.filter(m => m.type === 'dex').sort(tierThenVolume);
    // Take top 60 each. Concatenate in tier order (CEX first, then DEX).
    const markets = [...cexMarkets.slice(0, 60), ...dexMarkets.slice(0, 60)];

    const result = { markets, source: 'coingecko' };
    res.setHeader('Cache-Control', markets.length > 0 ? 'public, max-age=300' : 'no-cache');
    res.json(result);
  } catch (err) {
    console.error('Token markets error:', err.message);
    res.status(500).json({ error: 'Failed to fetch markets' });
  }
});

