/**
 * CoinGecko OHLCV data for BTC, ETH, SOL charts
 */
app.get('/api/coingecko/ohlcv/:coinId', async (req, res) => {
  try {
    const { coinId } = req.params;
    const { from, to, resolution = '60' } = req.query;
    const coinIdMap = { 'BTC': 'bitcoin', 'ETH': 'ethereum', 'SOL': 'solana' };
    const coinInfo = coinIdMap[coinId.toUpperCase()];
    if (!coinInfo) return res.status(400).json({ error: `Unsupported coin: ${coinId}` });

    const resolutionToDays = { '1': 1, '5': 1, '15': 7, '60': 30, '240': 90, '1D': 365, '1W': 'max' };
    let bars = [];
    const opts = { headers: { Accept: 'application/json' } };
    if (COINGECKO_API_KEY) opts.headers[COINGECKO_HEADER_KEY] = COINGECKO_API_KEY;

    if (from && to) {
      const fromTs = parseInt(from), toTs = parseInt(to);
      const diffDays = Math.min(Math.max(Math.ceil(Math.abs(toTs - fromTs) / 86400), 1), 365);
      try {
        const rangeUrl = `${COINGECKO_BASE}/coins/${coinInfo}/ohlc/range?vs_currency=usd&from=${fromTs}&to=${toTs}`;
        const response = await fetch(rangeUrl, opts);
        if (response.ok) {
          const data = await response.json();
          if (Array.isArray(data)) {
            bars = data.filter(i => Array.isArray(i) && i.length >= 5).map(i => ({ t: Math.floor(i[0] / 1000), o: parseFloat(i[1]) || 0, h: parseFloat(i[2]) || 0, l: parseFloat(i[3]) || 0, c: parseFloat(i[4]) || 0, v: 0 }));
            bars = bars.filter(b => b.t >= fromTs && b.t <= toTs);
          } else throw new Error('Invalid format');
        } else throw new Error('Range endpoint unavailable');
      } catch (e) {
        const apiUrl = `${COINGECKO_BASE}/coins/${coinInfo}/ohlc?vs_currency=usd&days=${diffDays}`;
        const response = await fetch(apiUrl, opts);
        if (!response.ok) throw new Error(`CoinGecko OHLC error: ${response.status}`);
        const data = await response.json();
        if (Array.isArray(data)) {
          bars = data.filter(i => Array.isArray(i) && i.length >= 5).map(i => ({ t: Math.floor(i[0] / 1000), o: parseFloat(i[1]) || 0, h: parseFloat(i[2]) || 0, l: parseFloat(i[3]) || 0, c: parseFloat(i[4]) || 0, v: 0 }));
          bars = bars.filter(b => b.t >= fromTs && b.t <= toTs);
        }
      }
    } else {
      const apiDays = resolutionToDays[resolution] || 30;
      const apiUrl = `${COINGECKO_BASE}/coins/${coinInfo}/ohlc?vs_currency=usd&days=${apiDays}`;
      const response = await fetch(apiUrl, opts);
      if (!response.ok) throw new Error(`CoinGecko OHLC error: ${response.status}`);
      const data = await response.json();
      if (Array.isArray(data)) {
        bars = data.filter(i => Array.isArray(i) && i.length >= 5).map(i => ({ t: Math.floor(i[0] / 1000), o: parseFloat(i[1]) || 0, h: parseFloat(i[2]) || 0, l: parseFloat(i[3]) || 0, c: parseFloat(i[4]) || 0, v: 0 }));
      }
    }
    bars.sort((a, b) => a.t - b.t);
    res.json({ bars });
  } catch (error) {
    console.error('CoinGecko OHLCV error:', error.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * CoinGecko coin details for BTC, ETH, SOL token pages
 */
app.get('/api/coingecko/coin/:coinId', async (req, res) => {
  try {
    const { coinId } = req.params;
    const coinIdMap = {
      'BTC': { cgId: 'bitcoin', defaultAddress: '0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599', defaultNetworkId: 1 },
      'ETH': { cgId: 'ethereum', defaultAddress: '0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2', defaultNetworkId: 1 },
      'SOL': { cgId: 'solana', defaultAddress: 'So11111111111111111111111111111111111111112', defaultNetworkId: 1399811149 }
    };
    const info = coinIdMap[coinId.toUpperCase()];
    if (!info) return res.status(400).json({ error: `Unsupported coin: ${coinId}` });
    const apiUrl = `${COINGECKO_BASE}/coins/${info.cgId}?localization=false&tickers=false&market_data=true&community_data=false&developer_data=false&sparkline=false`;
    const opts = { headers: { Accept: 'application/json' } };
    if (COINGECKO_API_KEY) opts.headers[COINGECKO_HEADER_KEY] = COINGECKO_API_KEY;
    const response = await fetch(apiUrl, opts);
    if (!response.ok) throw new Error(`CoinGecko API error: ${response.status}`);
    const data = await response.json();
    let address = info.defaultAddress, networkId = info.defaultNetworkId;
    if (data.platforms) {
      if ((coinId.toUpperCase() === 'BTC' || coinId.toUpperCase() === 'ETH') && data.platforms.ethereum) { address = data.platforms.ethereum; networkId = 1; }
      else if (coinId.toUpperCase() === 'SOL' && data.platforms.solana) { address = data.platforms.solana; networkId = 1399811149; }
    }
    res.json({
      symbol: data.symbol?.toUpperCase() || coinId.toUpperCase(),
      name: data.name || '',
      address, networkId,
      price: data.market_data?.current_price?.usd || 0,
      change: data.market_data?.price_change_percentage_24h || 0,
      marketCap: data.market_data?.market_cap?.usd || 0,
      volume24: data.market_data?.total_volume?.usd || 0,
      liquidity: 0,
      logo: data.image?.large || data.image?.small || '',
      description: data.description?.en || '',
      socials: {
        twitter: data.links?.twitter_screen_name ? `https://twitter.com/${data.links.twitter_screen_name}` : null,
        website: data.links?.homepage?.[0] || null,
        telegram: data.links?.telegram_channel_identifier ? `https://telegram.me/${data.links.telegram_channel_identifier}` : null,
        discord: null
      },
      circulatingSupply: data.market_data?.circulating_supply || 0,
      totalSupply: data.market_data?.total_supply || 0,
    });
  } catch (error) {
    console.error('CoinGecko coin error:', error.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ═══════════════════════════════════════════════════════════════════════════════
// RZ COMPARE — Rate-queued market_chart for the Research Zone compare overlay.
// Uses cgFetch (serial queue + API key) so rapid token swaps don't 429.
// ═══════════════════════════════════════════════════════════════════════════════

const _rzCompareCache = new Map(); // cgId|days -> { ts, body }
const RZ_COMPARE_TTL_MS = 5 * 60 * 1000;

app.get('/api/rz/compare-chart', async (req, res) => {
  const cgId = String(req.query.cgId || '').trim();
  const days = String(req.query.days || '90').trim();
  if (!cgId) return res.status(400).json({ error: 'Missing cgId' });
  const cacheKey = `${cgId}|${days}`;
  const cached = _rzCompareCache.get(cacheKey);
  if (cached && Date.now() - cached.ts < RZ_COMPARE_TTL_MS) {
    res.setHeader('Cache-Control', 'public, max-age=60');
    return res.status(200).json(cached.body);
  }
  try {
    const url = `${COINGECKO_BASE}/coins/${encodeURIComponent(cgId)}/market_chart?vs_currency=usd&days=${encodeURIComponent(days)}`;
    const cgRes = await cgFetch(url);
    if (!cgRes.ok) {
      const stale = _rzCompareCache.get(cacheKey);
      if (stale) {
        res.setHeader('Cache-Control', 'public, max-age=60');
        return res.status(200).json(stale.body);
      }
      return res.status(cgRes.status).json({ error: `CoinGecko status ${cgRes.status}` });
    }
    const body = await cgRes.json();
    _rzCompareCache.set(cacheKey, { ts: Date.now(), body });
    res.setHeader('Cache-Control', 'public, max-age=60');
    res.status(200).json(body);
  } catch (err) {
    const stale = _rzCompareCache.get(cacheKey);
    if (stale) {
      res.setHeader('Cache-Control', 'public, max-age=60');
      return res.status(200).json(stale.body);
    }
    console.error('RZ compare-chart error:', err.message);
    res.status(502).json({ error: 'CoinGecko unavailable' });
  }
});

// ═══════════════════════════════════════════════════════════════════════════════
// COINGECKO PROXY — Wildcard catch-all for remaining CoinGecko calls
// ═══════════════════════════════════════════════════════════════════════════════

app.get('/api/coingecko/*', async (req, res) => {
  const path = req.params[0]; // everything after /api/coingecko/
  const qs = new URLSearchParams(req.query).toString();
  const url = `${COINGECKO_BASE}/${path}${qs ? '?' + qs : ''}`;

  try {
    /* Route through cgFetch so the wildcard proxy participates in the
       same per-request gap + retry as the dedicated CG handlers. Without
       this, the browser fires 20+ parallel price/sparkline calls on
       drawer open and CG returns 429 on the burst even within the Pro
       per-minute limit. */
    const cgRes = await cgFetch(url);
    const data = await cgRes.text();
    res.setHeader('Content-Type', cgRes.headers.get('content-type') || 'application/json');
    /* Cache successful responses for 15s. NEVER cache an error response -
       a cached 429 leaves the drawer broken for 15 seconds even after
       CG recovers. */
    if (cgRes.ok) {
      res.setHeader('Cache-Control', 'public, max-age=15');
    } else {
      res.setHeader('Cache-Control', 'no-store');
    }
    res.status(cgRes.status).send(data);
  } catch (err) {
    console.error('CoinGecko proxy error:', err.message);
    res.status(502).json({ error: 'CoinGecko unavailable' });
  }
});

/** DexScreener chainId -> our networkId (Codex) */
const DEXSCREENER_CHAIN_TO_NETWORK = {
  solana: 1399811149,
  ethereum: 1,
  bsc: 56,
  base: 8453,
  arbitrum: 42161,
  polygon: 137,
  avalanche: 43114,
  optimism: 10,
  fantom: 250,
  pulsechain: 369,
  ton: 607,
  cronos: 25,
  sui: 784,
  aptos: 637,
  sei: 1329,
  injective: 6900,
  'near-protocol': 397,
  linea: 59144,
  zksync: 324,
  scroll: 534352,
  mantle: 5000,
  blast: 81457,
  'polygon-zkevm': 1101,
  mode: 34443,
  treos: 606,
  berachain: 80094,
  robinhood: 4663,
};

/**
 * GET /api/dexscreener-watchlist/:id
 * Fetch a DexScreener shared watchlist by ID (from URL .../watchlist/ID).
 * Uses Firebase Firestore directly (DexScreener stores watchlists in project dex-screener-16543).
 * Then enriches each pair with live data via DexScreener's public pairs API.
 */
app.get('/api/dexscreener-watchlist/:id', async (req, res) => {
  try {
    const id = (req.params.id || '').trim();
    if (!id) {
      return res.status(400).json({ error: 'Watchlist ID is required' });
    }

    console.log(`DexScreener import: Fetching watchlist "${id}" via Firestore`);

    // DexScreener stores shared watchlists in Firebase Firestore
    const firestoreUrl = `https://firestore.googleapis.com/v1/projects/dex-screener-16543/databases/(default)/documents/watchlists/${encodeURIComponent(id)}`;
    const fsRes = await fetch(firestoreUrl, {
      headers: { Accept: 'application/json' },
      signal: AbortSignal.timeout(10000),
    });

    if (!fsRes.ok) {
      console.log(`DexScreener Firestore: status ${fsRes.status}`);
      return res.status(404).json({
        error: 'Watchlist not found. Check the URL and try again.',
      });
    }

    const fsData = await fsRes.json();
    const pairsField = fsData?.fields?.pairs?.arrayValue?.values;
    if (!pairsField || pairsField.length === 0) {
      return res.status(404).json({ error: 'Watchlist is empty.' });
    }

    console.log(`DexScreener: Found ${pairsField.length} pairs in Firestore, enriching via pairs API...`);

    // Extract pair IDs and chains from Firestore
    const rawPairs = pairsField.map((v) => {
      const f = v.mapValue?.fields || {};
      return {
        pairId: f.pairId?.stringValue || '',
        chainId: f.chainId?.stringValue || '',
        symbol: f.baseTokenSymbol?.stringValue || '',
        name: f.baseTokenName?.stringValue || '',
      };
    }).filter((p) => p.pairId && p.chainId);

    // Batch-enrich via DexScreener pairs API (5 concurrent)
    const BATCH_SIZE = 5;
    const tokens = [];
    for (let i = 0; i < rawPairs.length; i += BATCH_SIZE) {
      const batch = rawPairs.slice(i, i + BATCH_SIZE);
      const results = await Promise.all(
        batch.map(async (rp) => {
          try {
            const url = `https://api.dexscreener.com/latest/dex/pairs/${rp.chainId}/${rp.pairId}`;
            const r = await fetch(url, {
              headers: { Accept: 'application/json' },
              signal: AbortSignal.timeout(8000),
            });
            if (!r.ok) return { ...rp, enriched: false };
            const data = await r.json();
            const p = data.pair || (data.pairs && data.pairs[0]);
            if (!p) return { ...rp, enriched: false };
            const base = p.baseToken || {};
            const chainId = (p.chainId || rp.chainId).toLowerCase();
            const networkId = DEXSCREENER_CHAIN_TO_NETWORK[chainId] || 1;
            return {
              symbol: base.symbol || rp.symbol || '?',
              name: base.name || rp.name || 'Unknown',
              address: base.address || rp.pairId,
              networkId,
              price: parseFloat(p.priceUsd || 0) || 0,
              change: parseFloat(p.priceChange?.h24 || 0) || 0,
              marketCap: parseFloat(p.fdv || p.marketCap || 0) || 0,
              liquidity: parseFloat(p.liquidity?.usd || 0) || 0,
              logo: p.info?.imageUrl || null,
              enriched: true,
            };
          } catch {
            return { ...rp, enriched: false };
          }
        })
      );

      results.forEach((r) => {
        if (r.enriched) {
          tokens.push(r);
        } else {
          // Fallback: use raw Firestore data without live price
          const networkId = DEXSCREENER_CHAIN_TO_NETWORK[r.chainId] || 1;
          tokens.push({
            symbol: r.symbol || '?',
            name: r.name || 'Unknown',
            address: r.pairId,
            networkId,
            price: 0,
            change: 0,
            marketCap: 0,
            logo: null,
          });
        }
      });
    }

    // De-duplicate by address
    const seen = new Set();
    const uniqueTokens = tokens.filter((t) => {
      const key = (t.address || '').toLowerCase();
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });

    console.log(`DexScreener: Returning ${uniqueTokens.length} tokens`);
    res.json({ tokens: uniqueTokens, source: 'firestore', count: uniqueTokens.length });
  } catch (error) {
    console.error('DexScreener watchlist error:', error?.message);
    res.status(500).json({
      error: 'Failed to fetch DexScreener watchlist',
    });
  }
});

/**
 * GET /api/dexscreener-pair/:chain/:address
 * Fetch a single token from DexScreener pair page using their public API.
 * Example: /api/dexscreener-pair/solana/abc123
 */
app.get('/api/dexscreener-pair/:chain/:address', async (req, res) => {
  try {
    const { chain, address } = req.params;
    if (!chain || !address) {
      return res.status(400).json({ error: 'Chain and address are required' });
    }
    
    console.log(`DexScreener pair lookup: ${chain}/${address}`);
    
    // Use DexScreener's documented public API for pairs
    const url = `https://api.dexscreener.com/latest/dex/pairs/${chain}/${address}`;
    const r = await fetch(url, {
      headers: { Accept: 'application/json' },
      signal: AbortSignal.timeout(10000),
    });
    
    if (!r.ok) {
      return res.status(404).json({ error: 'Pair not found on DexScreener' });
    }
    
    const data = await r.json();
    const pair = data.pair || (data.pairs && data.pairs[0]);
    
    if (!pair) {
      return res.status(404).json({ error: 'Pair data not found' });
    }
    
    const base = pair.baseToken || {};
    const chainId = (pair.chainId || chain).toLowerCase();
    const networkId = DEXSCREENER_CHAIN_TO_NETWORK[chainId] || 1;
    
    const token = {
      symbol: base.symbol || '?',
      name: base.name || base.symbol || 'Unknown',
      address: base.address,
      networkId,
      price: parseFloat(pair.priceUsd || 0) || 0,
      change: parseFloat(pair.priceChange?.h24 || 0) || 0,
      marketCap: parseFloat(pair.fdv || pair.marketCap || 0) || 0,
      liquidity: parseFloat(pair.liquidity?.usd || 0) || 0,
      volume24: parseFloat(pair.volume?.h24 || 0) || 0,
      logo: pair.info?.imageUrl || base.info?.imageUrl,
    };
    
    console.log(`DexScreener pair found: ${token.symbol} on ${chainId}`);
    res.json({ token, source: 'dexscreener-pairs-api' });
    
  } catch (error) {
    console.error('DexScreener pair error:', error?.message);
    res.status(500).json({ error: 'Failed to fetch pair' });
  }
});

const dexscreenerTokensCache = new Map();

/**
 * GET /api/dexscreener-tokens?addresses=<csv>
 *
 * Batch lookup against DexScreener's /latest/dex/tokens endpoint.
 * Accepts up to 30 comma-separated token addresses, returns the most-liquid
 * pair per address normalized to a flat shape callers can merge with Codex
 * data (price, % changes for 5m/1h/6h/24h, volume, market cap, liquidity,
 * 24h txn count, oldest pairCreatedAt, logo).
 *
 * Previously the research app fanned out one direct browser fetch per token
 * to api.dexscreener.com (no batching, no shared cache, burned per-user IP
 * rate limits). This route collapses that into one upstream call per 30s.
 *
 * Optional `chains` CSV (aligned with `addresses`, canonical chain keys)
 * routes each address through the CHAIN-SCOPED /tokens/v1/{chain}/{csv}
 * endpoint and rejects cross-chain pairs: /latest/dex/tokens caps the
 * response at 30 pairs TOTAL across all addresses, and the same contract can
 * be a DIFFERENT token on another chain (CULT on Ethereum vs RVLT on Polygon,
 * same 0xf0f9… address — RVLT's $447K mcap replaced CULT's real $2.7M and
 * fired a false "Rug Risk"). With a hint and no matching-chain pair, the
 * address gets NO entry — callers keep their fallback, never twin data.
 * Mirrored in apps/research/api/dexscreener-tokens.js — keep in sync.
 */
const DS_CHAIN_IDS = {
  hyperliquid: 'hyperevm', hyperevm: 'hyperevm', xrp: 'xrpl',
  'binance-smart-chain': 'bsc', 'arbitrum-one': 'arbitrum',
  'optimistic-ethereum': 'optimism', 'polygon-pos': 'polygon',
};
app.get('/api/dexscreener-tokens', async (req, res) => {
  try {
    const raw = String(req.query.addresses || '').trim();
    if (!raw) return res.status(400).json({ error: 'addresses query param required' });
    const rawAddrs = raw.split(',').map(s => s.trim());
    const rawChains = String(req.query.chains || '').split(',').map(s => s.trim().toLowerCase());
    const seenAddr = new Set();
    const entries = [];
    rawAddrs.forEach((addr, i) => {
      if (!addr) return;
      const key = addr.toLowerCase();
      if (seenAddr.has(key)) return;
      seenAddr.add(key);
      const canon = rawChains[i] || '';
      entries.push({ addr, dsChain: canon ? (DS_CHAIN_IDS[canon] || canon) : '' });
    });
    const capped = entries.slice(0, 30); // DS limit
    if (capped.length === 0) return res.status(400).json({ error: 'no valid addresses' });

    const cacheKey = capped.map(e => `${e.addr}:${e.dsChain}`).sort().join(',');
    const cached = getCached(dexscreenerTokensCache, cacheKey);
    if (cached) {
      res.setHeader('Cache-Control', 'public, s-maxage=30, stale-while-revalidate=60');
      return res.json(cached);
    }

    const chainByAddr = new Map(capped.map(e => [e.addr.toLowerCase(), e.dsChain]));
    const byChain = new Map();
    for (const e of capped) {
      const k = e.dsChain || '';
      if (!byChain.has(k)) byChain.set(k, []);
      byChain.get(k).push(e.addr);
    }
    const legacyAddrs = byChain.get('') || [];
    byChain.delete('');

    const pairs = [];
    await Promise.all([...byChain.entries()].map(async ([chain, addrs]) => {
      try {
        const r = await fetch(`https://api.dexscreener.com/tokens/v1/${chain}/${addrs.join(',')}`, {
          headers: { Accept: 'application/json' },
          signal: AbortSignal.timeout(10000),
        });
        if (!r.ok) throw new Error(`upstream ${r.status}`);
        const data = await r.json();
        const arr = Array.isArray(data) ? data : (Array.isArray(data?.pairs) ? data.pairs : []);
        pairs.push(...arr);
      } catch {
        // Fall back to the legacy batch; the chain FILTER below still applies.
        legacyAddrs.push(...addrs);
      }
    }));
    if (legacyAddrs.length) {
      const r = await fetch(`https://api.dexscreener.com/latest/dex/tokens/${legacyAddrs.join(',')}`, {
        headers: { Accept: 'application/json' },
        signal: AbortSignal.timeout(10000),
      });
      if (!r.ok && pairs.length === 0) return res.status(502).json({ error: `DexScreener upstream ${r.status}` });
      if (r.ok) {
        const data = await r.json();
        if (Array.isArray(data?.pairs)) pairs.push(...data.pairs);
      }
    }

    // Group pairs by base token address; for each address pick the most
    // liquid pair as the canonical price source and track the oldest
    // pairCreatedAt across every returned pair (pump.fun→Raydium migrations
    // create newer pairs that hide a token's true age).
    const byAddress = new Map();
    for (const p of pairs) {
      const baseAddr = (p?.baseToken?.address || '').toLowerCase();
      if (!baseAddr) continue;
      if (!byAddress.has(baseAddr)) byAddress.set(baseAddr, []);
      byAddress.get(baseAddr).push(p);
    }

    const tokens = {};
    for (const [addr, group] of byAddress) {
      const wantChain = chainByAddr.get(addr) || '';
      const arr = wantChain ? group.filter(p => p?.chainId === wantChain) : group;
      if (!arr.length) continue;
      arr.sort((a, b) => parseFloat(b?.liquidity?.usd || 0) - parseFloat(a?.liquidity?.usd || 0));
      const top = arr[0];
      let oldestCreatedAt = null;
      for (const p of arr) {
        const ts = Number(p?.pairCreatedAt);
        if (!Number.isFinite(ts) || ts <= 0) continue;
        if (oldestCreatedAt == null || ts < oldestCreatedAt) oldestCreatedAt = ts;
      }
      const parseFloatSafe = (v) => {
        const n = parseFloat(v);
        return Number.isFinite(n) ? n : null;
      };
      tokens[addr] = {
        price: parseFloatSafe(top?.priceUsd) || 0,
        change5m: parseFloatSafe(top?.priceChange?.m5),
        change1h: parseFloatSafe(top?.priceChange?.h1),
        change6h: parseFloatSafe(top?.priceChange?.h6),
        change24h: parseFloatSafe(top?.priceChange?.h24) || 0,
        volume24: parseFloatSafe(top?.volume?.h24) || 0,
        marketCap: parseFloatSafe(top?.marketCap ?? top?.fdv) || 0,
        liquidity: parseFloatSafe(top?.liquidity?.usd) || 0,
        txns24: (parseInt(top?.txns?.h24?.buys) || 0) + (parseInt(top?.txns?.h24?.sells) || 0),
        logo: top?.info?.imageUrl || top?.baseToken?.info?.imageUrl || null,
        pairCreatedAt: oldestCreatedAt,
        chainId: top?.chainId || null,
        pairAddress: top?.pairAddress || null,
      };
    }

    const body = { tokens, source: 'dexscreener', cached_at: new Date().toISOString() };
    setCached(dexscreenerTokensCache, cacheKey, body, 30_000);
    res.setHeader('Cache-Control', 'public, s-maxage=30, stale-while-revalidate=60');
    res.json(body);
  } catch (err) {
    console.error('DexScreener tokens batch error:', err);
    res.status(500).json({ error: err?.message || 'Failed' });
  }
});

/**
 * Resolve a token symbol to its full identity (CoinGecko ID, Binance pair, contract address, networkId, name).
 * Used by research-zone-lite and other consumers that start from a symbol string.
 */

// Helper: resolve Codex address from CoinGecko ID via convert_ids service
async function resolveCodexAddressFromCgId(cgId) {
  if (!cgId) return null;
  // charts-proxy convert_ids is dead — go straight to CoinGecko platforms.
  return resolveViaCoingeckoPlatforms(cgId);
}

/**
 * Public passthrough for the charts-proxy convert_ids service with a
 * CoinGecko `platforms` fallback. Consumers (e.g. the embed-chart Advanced
 * TV mode) use this to turn a CoinGecko slug into a Codex-compatible
 * {address, networkId}.
 *
 * Resolution chain:
 *   1. charts-proxy convert_ids → pair address (preferred, most specific)
 *   2. CoinGecko /coins/{id} → platforms.{chain} → token address
 *      /api/bars on our server can resolve token addresses via Codex
 *      getTokenBars, so a token address is sufficient for the datafeed.
 *
 * Returns null fields only when both sources fail so callers can disable
 * Advanced mode gracefully.
 */
const CG_PLATFORM_TO_NETWORK_ID = {
  'ethereum': 1,
  'binance-smart-chain': 56,
  'polygon-pos': 137,
  'avalanche': 43114,
  'arbitrum-one': 42161,
  'optimistic-ethereum': 10,
  'base': 8453,
  'solana': 1399811149,
  'robinhood': 4663, // Robinhood Chain (Arbitrum Orbit L2, mainnet 2026-07-01)
};

async function resolveViaCoingeckoPlatforms(cgId) {
  try {
    const url = `${COINGECKO_BASE}/coins/${encodeURIComponent(cgId)}?localization=false&tickers=false&market_data=false&community_data=false&developer_data=false&sparkline=false`;
    const opts = { signal: AbortSignal.timeout(5000), headers: { Accept: 'application/json' } };
    if (COINGECKO_API_KEY) opts.headers[COINGECKO_HEADER_KEY] = COINGECKO_API_KEY;
    const r = await fetch(url, opts);
    if (!r.ok) return null;
    const data = await r.json();
    const platforms = data?.platforms || {};
    for (const [chain, netId] of Object.entries(CG_PLATFORM_TO_NETWORK_ID)) {
      const addr = platforms[chain];
      if (addr && typeof addr === 'string' && addr.length > 3) {
        return { address: addr, networkId: netId };
      }
    }
    return null;
  } catch (_) {
    return null;
  }
}

app.get('/api/convert-ids', async (req, res) => {
  const cgId = (req.query.cgid || req.query.cgId || '').toString().trim().toLowerCase();
  if (!cgId) return res.status(400).json({ error: 'cgid query parameter is required' });

  const cacheKey = `convert-ids:${cgId}`;
  const cached = getCached(cache.details, cacheKey, 3600000); // 1h TTL
  if (cached) return res.json(cached);

  // Step 1: charts-proxy convert_ids
  let codex_id = null;
  let cmc_id = null;
  let quote = null;
  let address = null;
  let networkId = null;
  let source = null;

  try {
    const upstream = await fetch(
      `${CHARTS_PROXY_BASE}/convert_ids?cgid=${encodeURIComponent(cgId)}`,
      { signal: AbortSignal.timeout(5000) }
    );
    if (upstream.ok) {
      const data = await upstream.json();
      codex_id = data?.codex_id || null;
      cmc_id = data?.cmc_id || null;
      quote = data?.quote || null;
      if (typeof codex_id === 'string') {
        const parts = codex_id.split(':');
        if (parts[0] && parts[0].length > 3) address = parts[0];
        if (parts[1]) {
          const nid = parseInt(parts[1], 10);
          if (Number.isFinite(nid)) networkId = nid;
        }
        if (address) source = 'convert_ids';
      }
    }
  } catch (err) {
    console.warn('[convert-ids] upstream failed:', err?.message || err);
  }

  // Step 2: CoinGecko platforms fallback (when upstream didn't give us a pair)
  if (!address) {
    const cg = await resolveViaCoingeckoPlatforms(cgId);
    if (cg) {
      address = cg.address;
      networkId = cg.networkId;
      source = 'coingecko-platforms';
    }
  }

  const result = { cgid: cgId, codex_id, cmc_id, quote, address, networkId, source };
  // Short TTL for full misses so we retry once upstream learns the token
  const ttl = address ? 3600000 : 600000;
  setCached(cache.details, cacheKey, result, ttl);
  return res.json(result);
});

app.get('/api/token/resolve', async (req, res) => {
  try {
    const rawInput = (req.query.symbol || '').trim();
    const symbol = rawInput.toUpperCase();
    if (!symbol) {
      return res.status(400).json({ error: 'symbol query parameter is required' });
    }

    const cacheKey = `token-resolve:${rawInput.toLowerCase()}`;
    const cached = getCached(cache.details, cacheKey, 3600000); // 1 hour TTL
    if (cached) {
      return res.json(cached);
    }

    // Helper: cache result under all known keys
    const cacheResult = (result) => {
      setCached(cache.details, cacheKey, result, 3600000);
      if (result.symbol) setCached(cache.details, `token-resolve:${result.symbol.toLowerCase()}`, result, 3600000);
      if (result.cgId) setCached(cache.details, `token-resolve:${result.cgId}`, result, 3600000);
    };

    // 1. Check token registry first (most complete data, instant)
    const registryInfo = getTokenInfo(symbol);
    if (registryInfo) {
      const cgId = registryInfo.coingeckoId || SYMBOL_TO_COINGECKO_ID[symbol] || null;
      let address = registryInfo.address || null;
      let netId = registryInfo.networkId || null;
      // If registry has cgId but no address, try convert_ids to get Codex address
      if (!address && cgId) {
        const codexAddr = await resolveCodexAddressFromCgId(cgId);
        if (codexAddr) {
          address = codexAddr.address;
          netId = codexAddr.networkId;
        }
      }
      const result = {
        symbol,
        name: registryInfo.name || symbol,
        cgId,
        binancePair: registryInfo.binanceSymbol || null,
        address,
        networkId: netId,
      };
      cacheResult(result);
      return res.json(result);
    }

    // 2. Check SYMBOL_TO_COINGECKO_ID map
    const knownCgId = SYMBOL_TO_COINGECKO_ID[symbol];

    // 3. Try CoinGecko /coins/{id} - input might be a CoinGecko ID (e.g. "world-liberty-financial")
    //    Also try if we have a known cgId from the symbol map
    // Platform slug -> Codex network id: the ONE shared canonical map (the
    // old ethereum-only pick left every BSC/Base/Solana/HyperEVM-contract
    // token address-less here — the "M"/HYPE chartless class, 2026-08-25).
    const { CG_PLATFORM_TO_NETWORK_ID: CG_PLATFORM_NETWORKS } =
      await import('../../apps/research/api/_lib/cg-platforms.js');
    const resolveViaCgProfile = async (cgIdCandidate) => {
      const cgUrl = `${COINGECKO_BASE}/coins/${encodeURIComponent(cgIdCandidate)}?localization=false&tickers=false&community_data=false&developer_data=false`;
      const cgOpts = { headers: {} };
      if (COINGECKO_API_KEY) cgOpts.headers[COINGECKO_HEADER_KEY] = COINGECKO_API_KEY;
      const cgRes = await fetch(cgUrl, { ...cgOpts, signal: AbortSignal.timeout(5000) });
      if (!cgRes.ok) return null;
      const coin = await cgRes.json();
      if (!coin || !coin.symbol) return null;
      const realSymbol = coin.symbol.toUpperCase();
      const platforms = coin.platforms || {};
      const registryForReal = getTokenInfo(realSymbol);
      let address = registryForReal?.address || null;
      let netId = registryForReal?.networkId || null;
      if (!address) {
        for (const [slug, n] of CG_PLATFORM_NETWORKS) {
          const addr = platforms[slug];
          if (typeof addr === 'string' && addr.trim()) { address = addr.trim(); netId = n; break; }
        }
      }
      // Legacy CG records keyed the ETH address under '' — last resort.
      if (!address && typeof platforms[''] === 'string' && platforms[''].trim()) {
        address = platforms[''].trim();
        netId = 1;
      }
      // If CoinGecko found the token but no address, try convert_ids
      if (!address && coin.id) {
        const codexAddr = await resolveCodexAddressFromCgId(coin.id);
        if (codexAddr) {
          address = codexAddr.address;
          netId = codexAddr.networkId;
        }
      }
      return {
        symbol: realSymbol,
        name: coin.name || realSymbol,
        cgId: coin.id,
        // Real registry pair only — fabricated `${sym}USDT` pairs sent the
        // chart pipeline to a dead Binance tier (task #22, 2026-06-10).
        binancePair: registryForReal?.binanceSymbol || null,
        address,
        networkId: netId,
      };
    };
    const cgIdToTry = knownCgId || rawInput.toLowerCase();
    try {
      const result = await resolveViaCgProfile(cgIdToTry);
      if (result) {
        cacheResult(result);
        return res.json(result);
      }
    } catch (_) { /* CoinGecko lookup failed, continue */ }

    // 3.2 CoinGecko /search — the input may be a plain TICKER whose cgId
    // differs from the lowercased symbol ('m' → 'memecore'). Without this
    // rung, every CG-listed ticker outside the registry fell straight to the
    // Codex phrase search below, whose liquidity-ranked pick is
    // collision-prone (2026-08-25: a Monad-testnet clone "DIOSDELA MUERTOS"
    // was served as MemeCore's identity). CG /search orders by market-cap
    // rank, so the first exact-symbol hit is the coin a reader means.
    try {
      const sUrl = `${COINGECKO_BASE}/search?query=${encodeURIComponent(rawInput)}`;
      const sOpts = { headers: {} };
      if (COINGECKO_API_KEY) sOpts.headers[COINGECKO_HEADER_KEY] = COINGECKO_API_KEY;
      const sRes = await fetch(sUrl, { ...sOpts, signal: AbortSignal.timeout(5000) });
      if (sRes.ok) {
        const sData = await sRes.json();
        const coins = Array.isArray(sData?.coins) ? sData.coins : [];
        const exact = coins.find(c => (c.symbol || '').toUpperCase() === symbol) || null;
        if (exact?.id) {
          const result = await resolveViaCgProfile(exact.id);
          if (result) {
            cacheResult(result);
            return res.json(result);
          }
        }
      }
    } catch (_) { /* CoinGecko search failed, continue */ }

    // 3.5 Try convert_ids if we have a known CoinGecko ID but CoinGecko API failed
    if (knownCgId) {
      const codexAddr = await resolveCodexAddressFromCgId(knownCgId);
      if (codexAddr) {
        const result = {
          symbol,
          name: symbol,
          cgId: knownCgId,
          binancePair: getTokenInfo(symbol)?.binanceSymbol || null,
          address: codexAddr.address,
          networkId: codexAddr.networkId,
        };
        cacheResult(result);
        return res.json(result);
      }
    }

    // 4. Codex filterTokens lookup (for DEX tokens not on CoinGecko)
    let address = null;
    let networkId = null;
    let name = symbol;

    try {
      const searchResult = await executeCodexQuery(
        `query($search:String!,$limit:Int!){
          filterTokens(phrase:$search,limit:$limit,rankings:[{attribute:liquidity,direction:DESC}]){
            results{token{address symbol name networkId}priceUSD liquidity}
          }
        }`,
        { search: symbol, limit: 5 }
      );
      // Dust floor (mirrors MIN_PLATFORM_LIQUIDITY, charts-system §I13): a
      // pick with no real pool is never the token a reader means — it is how
      // a Monad-testnet clone got served as MemeCore's identity (2026-08-25).
      // UNKNOWN IS NOT DUST: Codex omits/nulls `liquidity` for plenty of real
      // rows, and `Number(null) >= 500` is false — a `>=` filter silently
      // dropped those legitimate tokens too. Only a liquidity we can actually
      // READ and that is below the floor disqualifies a candidate.
      const results = (searchResult?.filterTokens?.results || [])
        .filter(r => !(Number(r?.liquidity) < 500));
      const match = results.find(r => (r.token?.symbol || '').toUpperCase() === symbol) || results[0];

      if (match?.token) {
        address = match.token.address || null;
        networkId = match.token.networkId || null;
        name = match.token.name || symbol;
      }
    } catch (codexErr) {
      console.error('Codex filterTokens error during token resolve:', codexErr.message);
    }

    const result = {
      symbol,
      name,
      cgId: null,
      binancePair: getTokenInfo(symbol)?.binanceSymbol || null,
      address,
      networkId,
    };
    cacheResult(result);
    return res.json(result);

  } catch (error) {
    console.error('Token resolve error:', error?.message);
    res.status(500).json({ error: 'Failed to resolve token' });
  }
});

/**
 * Get detailed token info including price, socials, description
 * Used for the main token banner section
 */
app.get('/api/token/details', async (req, res) => {
  try {
    const { address, networkId = 1 } = req.query;

    if (!address) {
      return res.status(400).json({ error: 'Address is required' });
    }

    // Auto-detect Solana addresses (base58, 32-44 chars, no 0x prefix)
    const isSolAddr = address && !address.startsWith('0x') && address.length >= 32 && address.length <= 44;
    const netId = (isSolAddr && parseInt(networkId) === 1) ? 1399811149 : parseInt(networkId);
    const cacheKey = `${address.toLowerCase()}_${netId}`;
    // `_batchShape` entries are written by /api/token/details-batch - a
    // trimmed market-row (no circulatingSupply/totalSupply/socials/decimals/
    // description). Serving one from here poisons every full-details consumer
    // (RightPanel Circ.Supply renders 0, the snapshot endpoint re-distributes
    // the trimmed shape). Treat them as a cache MISS and fetch the full shape.
    const cached = getCached(cache.details, cacheKey, CACHE_TTL_DETAILS_MS);
    if (cached && !cached._batchShape) {
      return res.json(cached);
    }

    // Combined query: token details + market data in a single GraphQL request
    // Saves 1 Codex API call per cache miss (was 2 separate queries)
    const combinedQuery = `
      query GetTokenDetails($address: String!, $networkId: Int!, $networkFilter: [Int!], $phrase: String!) {
        token(input: { address: $address, networkId: $networkId }) {
          address
          name
          symbol
          decimals
          networkId
          info {
            imageThumbUrl
            imageLargeUrl
            circulatingSupply
            totalSupply
            description
          }
          socialLinks {
            twitter
            discord
            telegram
            website
          }
        }
        filterTokens(
          filters: { network: $networkFilter }
          phrase: $phrase
          limit: 1
        ) {
          results {
            priceUSD
            volume24
            liquidity
            marketCap
            change24
            change1
            change4
            change12
            holders
            txnCount24
            createdAt
            token {
              createdAt
            }
          }
        }
      }
    `;

    // Determine if this is a Solana address (case-sensitive, don't lowercase)
    const isSolanaNetwork = netId === 1399811149;
    const queryAddress = isSolanaNetwork ? address : address.toLowerCase();

    // Single combined query + cached pair lookup (30-min TTL)
    const [combinedData, topPairAddress] = await Promise.all([
      executeCodexQuery(combinedQuery, { address: queryAddress, networkId: netId, networkFilter: [netId], phrase: queryAddress }),
      getCachedTopPair(queryAddress, netId),
    ]);
    const tokenData = { token: combinedData?.token };
    const marketData = { filterTokens: combinedData?.filterTokens };
    
    const token = tokenData?.token;
    const market = marketData?.filterTokens?.results?.[0];
    
    if (!token) {
      return res.status(404).json({ error: 'Token not found' });
    }
    
    // Initial liquidity from filterTokens (may be just one pair)
    let liquidity = parseFloat(market?.liquidity) || 0;
    const marketCap = parseFloat(market?.marketCap) || 0;
    
    // Check if liquidity seems suspiciously low for the market cap
    // Normal ratio is usually 1:10 to 1:100 (mcap/liq)
    // If ratio is > 500, likely multiple pairs not aggregated
    const mcapToLiqRatio = marketCap > 0 && liquidity > 0 ? marketCap / liquidity : 0;
    
    if (mcapToLiqRatio > 500 && marketCap > 1000000) {
      // Use liquidityMetadataByToken for aggregated liquidity across all pools
      console.log(`${token.symbol}: High mcap/liq ratio (${mcapToLiqRatio.toFixed(0)}x), fetching aggregated liquidity...`);
      
      try {
        const liquidityQuery = `
          query GetLiquidityMetadata($tokenAddress: String!, $networkId: Int!) {
            liquidityMetadataByToken(
              tokenAddress: $tokenAddress
              networkId: $networkId
            ) {
              totalLiquidityUsd
              lockedLiquidityUsd
            }
          }
        `;
        
        const liquidityData = await executeCodexQuery(liquidityQuery, {
          tokenAddress: queryAddress,
          networkId: netId,
        });
        
        const metadata = liquidityData?.liquidityMetadataByToken;
        
        if (metadata && metadata.totalLiquidityUsd) {
          const totalLiquidity = parseFloat(metadata.totalLiquidityUsd) || 0;
          console.log(`${token.symbol}: Aggregated liquidity: $${totalLiquidity.toLocaleString()} (was $${liquidity.toLocaleString()})`);
          liquidity = totalLiquidity;
        }
      } catch (liqErr) {
        console.log(`Failed to fetch aggregated liquidity for ${token.symbol}:`, liqErr.message);
        // Keep original liquidity
      }
    }

    // Total-pool liquidity from DexScreener (sums the full pool TVL). Codex's
    // filterTokens.liquidity reports ~one side of the pair (~half), so SPECTRE
    // read $162K vs the true $326K. DexScreener matches prod + the chain; override
    // when present, keep the Codex/aggregated figure on a miss. Holders stay Codex
    // (market.holders below) - it matches Etherscan, unlike the Hetzner undercount.
    let dsRow = null;
    try {
      const dsEnr = await enrichFromDexScreener([{ address: token.address || queryAddress, networkId: netId }]);
      dsRow = dsEnr.get(dsNorm(token.address || queryAddress)) || null;
      if (dsRow && dsRow.liquidity > 0) liquidity = dsRow.liquidity;
    } catch (_) { /* keep existing liquidity on enrich miss */ }

    // Parse price and supplies
    const price = parseFloat(market?.priceUSD) || 0;
    const circulatingSupply = parseFloat(token.info?.circulatingSupply) || 0;
    const totalSupply = parseFloat(token.info?.totalSupply) || 0;
    
    // Calculate market cap ourselves instead of trusting API value
    // The API's marketCap field can be incorrect (e.g., for PAAL it shows $38.9M instead of correct value)
    // Our calculation: price × circulatingSupply
    let calculatedMarketCap = 0;
    let resolvedCirculating = circulatingSupply;
    if (price > 0 && circulatingSupply > 0) {
      calculatedMarketCap = price * circulatingSupply;
      console.log(`${token.symbol}: Calculated MCap = $${calculatedMarketCap.toLocaleString()} (price: $${price}, circSupply: ${circulatingSupply.toLocaleString()})`);
    } else if (marketCap > 0) {
      // Fallback to API value if we can't calculate
      calculatedMarketCap = marketCap;
      // Derive circulating supply from marketCap/price when Codex doesn't expose info.circulatingSupply
      // (common for tokens like SPECTRE - the on-chain contract has totalSupply but circulating is metadata)
      if (price > 0 && !resolvedCirculating) {
        resolvedCirculating = marketCap / price;
        console.log(`${token.symbol}: Derived CircSupply = ${resolvedCirculating.toLocaleString()} from MCap/Price`);
      }
      console.log(`${token.symbol}: Using API MCap = $${marketCap.toLocaleString()} (no circulating supply available)`);
    }
    // Codex's info.circulatingSupply is metadata that goes stale (LNQ carried
    // 132.7M vs the real ~424M -> mcap showed $855K instead of ~$2.6M). When
    // the computed mcap and Codex's own marketCap disagree by >1.5x, neither
    // is trustworthy - take DexScreener's circulating mcap (dsRow already
    // fetched above; matches what users benchmark against).
    if (mcapLooksWrong(calculatedMarketCap, marketCap) && dsRow && dsRow.marketCap > 0) {
      console.log(`${token.symbol}: MCap ${calculatedMarketCap.toLocaleString()} vs API ${marketCap.toLocaleString()} divergent - using DexScreener $${dsRow.marketCap.toLocaleString()}`);
      calculatedMarketCap = dsRow.marketCap;
      if (price > 0) resolvedCirculating = dsRow.marketCap / price;
    }
    
    // Calculate token age from createdAt
    const createdAt = market?.createdAt || market?.token?.createdAt;
    let ageInDays = null;
    if (createdAt) {
      const createdDate = new Date(createdAt * 1000); // Unix timestamp
      const now = new Date();
      ageInDays = Math.floor((now - createdDate) / (1000 * 60 * 60 * 24));
    }
    
    // Combine the data
    const result = {
      address: token.address,
      name: token.name,
      symbol: token.symbol,
      decimals: token.decimals,
      networkId: token.networkId,
      logo: token.info?.imageLargeUrl || token.info?.imageThumbUrl,
      description: token.info?.description || '',
      circulatingSupply: resolvedCirculating > 0 ? resolvedCirculating : (token.info?.circulatingSupply || null),
      totalSupply: totalSupply > 0 ? totalSupply : token.info?.totalSupply,
      socials: {
        twitter: token.socialLinks?.twitter,
        discord: token.socialLinks?.discord,
        telegram: token.socialLinks?.telegram,
        website: token.socialLinks?.website,
      },
      price: price,
      volume24: parseFloat(market?.volume24) || 0,
      liquidity: liquidity,
      marketCap: calculatedMarketCap,
      apiMarketCap: marketCap, // Keep the original API value for debugging
      change24: parseFloat(market?.change24) || 0,
      change1h: parseFloat(market?.change1) || 0,
      change4h: parseFloat(market?.change4) || 0,
      change12h: parseFloat(market?.change12) || 0,
      holders: parseInt(market?.holders) || 0,
      // On-chain metrics
      txnCount24: parseInt(market?.txnCount24) || 0,
      createdAt: createdAt,
      age: ageInDays, // Age in days
      topPairAddress: topPairAddress || null,
    };
    
    setCached(cache.details, cacheKey, result, CACHE_TTL_DETAILS_MS);
    res.json(result);

  } catch (error) {
    const msg = error?.message || ''
    console.warn('[token/details] returning null:', msg)
    // 200 + null so LeftPanel's Promise.allSettled cycle doesn't get
    // bombarded with 500s when dev Codex key lacks tokenInfo scope.
    res.setHeader('Cache-Control', 'no-store')
    return res.status(200).json({ token: null, degraded: true, reason: /not activated|429|403/i.test(msg) ? msg : 'details_unavailable' })
  }
});

// ============================================================
// Per-window token stats (mobile Info DexScreener-style panel).
// Mirror: apps/trading/api/codex.js case 'token-stats'.
// getDetailedTokenStats aggregates all pairs for the token -> per window
// (5m/1h/4h/24h): txns, buys/sells, buy/sell volume USD, buyers/sellers/
// traders. Response shape shared verbatim with the prod serverless twin:
// { windows: { '5m'|'1h'|'4h'|'24h': {...} }, ts } (or { windows: null }).
// ============================================================
const CACHE_TTL_TOKEN_STATS_MS = 45 * 1000;
cache.tokenStats = new Map();

app.get('/api/token/stats', async (req, res) => {
  try {
    const { address, networkId = 1 } = req.query;
    if (!address) return res.status(400).json({ error: 'Address is required' });
    const netId = parseInt(networkId) || 1;
    const cacheKey = `${address.toLowerCase()}_${netId}`;
    const cached = getCached(cache.tokenStats, cacheKey, CACHE_TTL_TOKEN_STATS_MS);
    if (cached) return res.json(cached);

    const query = `
      query TokenWindowStats($tokenAddress: String!, $networkId: Int!) {
        getDetailedTokenStats(
          tokenAddress: $tokenAddress
          networkId: $networkId
          durations: [min5, hour1, hour4, day1]
        ) {
          stats_min5 { ...TSWin }
          stats_hour1 { ...TSWin }
          stats_hour4 { ...TSWin }
          stats_day1 { ...TSWin }
        }
      }
      fragment TSWin on WindowedDetailedTokenStats {
        statsUsd {
          volume { currentValue }
          buyVolume { currentValue }
          sellVolume { currentValue }
        }
        statsNonCurrency {
          transactions { currentValue }
          buys { currentValue }
          sells { currentValue }
          buyers { currentValue }
          sellers { currentValue }
          traders { currentValue }
        }
      }
    `;
    const data = await executeCodexQuery(query, { tokenAddress: address, networkId: netId });
    const stats = data?.getDetailedTokenStats;
    const fNum = (m) => { const v = parseFloat(m?.currentValue); return Number.isFinite(v) ? v : 0; };
    const iNum = (m) => { const v = parseInt(m?.currentValue, 10); return Number.isFinite(v) ? v : 0; };
    const normalize = (w) => {
      if (!w) return null;
      const usd = w.statsUsd || {};
      const num = w.statsNonCurrency || {};
      return {
        txns: iNum(num.transactions),
        buys: iNum(num.buys),
        sells: iNum(num.sells),
        volume: fNum(usd.volume),
        buyVolume: fNum(usd.buyVolume),
        sellVolume: fNum(usd.sellVolume),
        buyers: iNum(num.buyers),
        sellers: iNum(num.sellers),
        traders: iNum(num.traders),
      };
    };
    const windows = {};
    for (const [field, key] of [['stats_min5', '5m'], ['stats_hour1', '1h'], ['stats_hour4', '4h'], ['stats_day1', '24h']]) {
      const norm = normalize(stats?.[field]);
      if (norm) windows[key] = norm;
    }
    if (!Object.keys(windows).length) {
      // Don't cache empties - a transient Codex failure would blank the panel
      // for the full TTL.
      res.setHeader('Cache-Control', 'no-store');
      return res.json({ windows: null });
    }
    const result = { windows, ts: Date.now() };
    setCached(cache.tokenStats, cacheKey, result, CACHE_TTL_TOKEN_STATS_MS);
    res.json(result);
  } catch (error) {
    console.warn('[token/stats] returning null:', error?.message || error);
    res.setHeader('Cache-Control', 'no-store');
    return res.status(200).json({ windows: null });
  }
});

// ============================================================
// Top-pair metadata (mobile Info pair strip + Pair Info rows).
// Mirror: apps/trading/api/codex.js case 'pair-info'. Highest-liquidity
// pair's exchange (name/icon), real quote token, pooled amounts, createdAt
// and address. Shape shared verbatim with the prod serverless twin.
// ============================================================
const CACHE_TTL_PAIR_INFO_MS = 5 * 60 * 1000;
cache.pairInfo = new Map();

app.get('/api/token/pair-info', async (req, res) => {
  try {
    const { address, networkId = 1 } = req.query;
    if (!address) return res.status(400).json({ error: 'Address is required' });
    const netId = parseInt(networkId) || 1;
    const cacheKey = `${address.toLowerCase()}_${netId}`;
    const cached = getCached(cache.pairInfo, cacheKey, CACHE_TTL_PAIR_INFO_MS);
    if (cached) return res.json(cached);

    const query = `
      query PairInfo($tokenAddress: String!, $networkId: Int!) {
        listPairsWithMetadataForToken(tokenAddress: $tokenAddress, networkId: $networkId, limit: 1) {
          results {
            liquidity
            exchange { name iconUrl tradeUrl }
            backingToken { address symbol }
            token { address symbol }
            pair { address createdAt token0 pooled { token0 token1 } }
          }
        }
      }
    `;
    const data = await executeCodexQuery(query, { tokenAddress: address, networkId: netId });
    const r = data?.listPairsWithMetadataForToken?.results?.[0];
    if (!r?.pair) {
      res.setHeader('Cache-Control', 'no-store');
      return res.json({ pairAddress: null });
    }
    const tokenIsToken0 = (r.pair.token0 || '').toLowerCase() === (r.token?.address || address).toLowerCase();
    const num = (v) => { const n = parseFloat(v); return Number.isFinite(n) ? n : null; };
    const result = {
      pairAddress: r.pair.address,
      createdAt: r.pair.createdAt || null,
      // Which side of the pair the token sits on - the chart's live-bar stream
      // (Codex onBarsUpdated) is priced per side; the wrong side streams the
      // QUOTE token's price (EMBER/SOL on token1 = SOL at ~$101, measured
      // 2026-09-11). PROD TWIN: apps/trading/api/codex.js handlePairInfo.
      tokenSide: tokenIsToken0 ? 'token0' : 'token1',
      exchange: {
        name: r.exchange?.name || null,
        iconUrl: r.exchange?.iconUrl || null,
        tradeUrl: r.exchange?.tradeUrl || null,
      },
      token: { address: r.token?.address || address, symbol: r.token?.symbol || null },
      quote: { address: r.backingToken?.address || null, symbol: r.backingToken?.symbol || null },
      pooledToken: num(tokenIsToken0 ? r.pair.pooled?.token0 : r.pair.pooled?.token1),
      pooledQuote: num(tokenIsToken0 ? r.pair.pooled?.token1 : r.pair.pooled?.token0),
      liquidity: num(r.liquidity),
      ts: Date.now(),
    };
    setCached(cache.pairInfo, cacheKey, result, CACHE_TTL_PAIR_INFO_MS);
    res.json(result);
  } catch (error) {
    console.warn('[token/pair-info] returning null:', error?.message || error);
    res.setHeader('Cache-Control', 'no-store');
    return res.status(200).json({ pairAddress: null });
  }
});

// ============================================================
// Phase D: aggregate token snapshot
//
// Collapses the cold-load waterfall (details + 1h bars + recent
// trades + brand color = 4 sequential round-trips from the client)
// into a single response, ~300-500ms cold instead of 1.5-3s.
//
// Self-fetches the existing /api/token/details, /api/bars,
// /api/token/trades, and /api/token-color routes in parallel —
// reuses ALL their caching, in-flight dedup, and error handling
// without duplicating logic. Loopback HTTP is ~3-5ms per call
// (negligible vs the upstream Codex roundtrip).
//
// Per-snapshot in-flight dedup coalesces simultaneous clicks on the
// same token to one upstream fan-out. Per-snapshot cache (30s TTL)
// matches the details-cache TTL.
// ============================================================
const _snapshotCache = new Map();
const _snapshotInflight = new Map();
// 60s (was 30s) so the in-memory warm window matches the snapshot s-maxage=60.
// This is the dev process-persistent cache; prod cross-instance warmth is the
// serverless KV tsnap (that twin only - Express is a single long-lived process).
const SNAPSHOT_CACHE_TTL = 60_000;
const _snapSleep = (ms) => new Promise((r) => setTimeout(r, ms));
// Member timeouts: 4000ms on the three sibling fetches (was 8000). Color keeps
// its own 5000ms ceiling - the fast gate races it at 300ms and the client's
// accent pipeline covers a null, so this ceiling only bounds the legacy await.
const _SNAP_MEMBER_TIMEOUT = 4000;
const _SNAP_COLOR_TIMEOUT = 5000;

// Build all four member promises at t=0. Color overlaps trades: it awaits ONLY
// details' logo (not the whole assembly), so it no longer runs as a sequential
// phase-2 after everything else settled. `fullP` is the byte-identical legacy
// payload (NO pending field) - what gets cached + what the no-phase gate awaits.
function _buildSnapshotAssembly({ address, netId, snapRes }) {
  const now = Math.floor(Date.now() / 1000);
  // 300 bars at the chart's BOOT resolution = its first-paint window, so the
  // snapshot carries the bars for the timeframe the chart actually mounts on
  // (no cold full-window fetch on reload — the old hardcoded 1H mismatched any
  // non-1H saved timeframe).
  const _SNAP_BUCKET = { '1':60,'5':300,'15':900,'30':1800,'60':3600,'240':14400,'720':43200,'1D':86400,'1W':604800 };
  const from = now - 300 * (_SNAP_BUCKET[snapRes] || 3600);
  const base = `http://localhost:${PORT}`;

  const detailsUrl = `${base}/api/token/details?address=${encodeURIComponent(address)}&networkId=${netId}`;
  // src=codex keeps the snapshot's bars on the SAME Codex-only tier the trading
  // chart uses AND shares the wide-KV bucket with any direct chart fetch.
  // Contract-shaped addresses only - CoinGecko-slug majors can't resolve on the
  // codex tier and must keep the full tier cascade. Mirrors the trading prod
  // twin (apps/trading/api/token-snapshot.js).
  const isContractAddr = /^0x[0-9a-fA-F]{40}$/.test(address) ||
    (address.length >= 32 && address.length <= 44 && /^[1-9A-HJ-NP-Za-km-z]+$/.test(address));
  const barsSrc = isContractAddr ? '&src=codex' : '';
  const barsUrl = `${base}/api/bars?symbol=${encodeURIComponent(address)}&from=${from}&to=${now}&resolution=${snapRes}&networkId=${netId}${barsSrc}`;
  const tradesUrl = `${base}/api/token/trades?address=${encodeURIComponent(address)}&networkId=${netId}&limit=50`;

  const detailsP = fetch(detailsUrl, { signal: AbortSignal.timeout(_SNAP_MEMBER_TIMEOUT) }).then(r => r.ok ? r.json() : null).catch(() => null);
  const barsP = fetch(barsUrl, { signal: AbortSignal.timeout(_SNAP_MEMBER_TIMEOUT) }).then(r => r.ok ? r.json() : null).catch(() => null);
  const tradesP = fetch(tradesUrl, { signal: AbortSignal.timeout(_SNAP_MEMBER_TIMEOUT) }).then(r => r.ok ? r.json() : null).catch(() => null);
  const colorP = detailsP.then((d) => {
    const logoUrl = d?.logo || null;
    if (!logoUrl) return null;
    return fetch(`${base}/api/token-color?url=${encodeURIComponent(logoUrl)}`, {
      signal: AbortSignal.timeout(_SNAP_COLOR_TIMEOUT),
    }).then(r => r.ok ? r.json() : null).then(j => j?.color || null).catch(() => null);
  }).catch(() => null);

  const fullP = (async () => {
    const [details, bars, trades, color] = await Promise.all([detailsP, barsP, tradesP, colorP]);
    return {
      address: address.toLowerCase(),
      networkId: netId,
      details: details || null,
      bars: bars || null,
      barsResolution: snapRes,
      trades: trades?.trades || [],
      color: color || null,
      ts: Date.now(),
    };
  })();

  return { detailsP, barsP, tradesP, colorP, fullP };
}

// Fast gate: resolve once details+bars settle; trades races a 900ms ceiling,
// color a 300ms ceiling (run concurrently). Members that lose their race are
// returned empty/null and named in `pending` (the client fills them via its
// trades-phase follow-up + its own accent pipeline).
async function _snapshotFastResponse(bundle, { address, netId, snapRes }) {
  const { detailsP, barsP, tradesP, colorP } = bundle;
  const [details, bars] = await Promise.all([detailsP, barsP]);
  const [tradesRaced, colorRaced] = await Promise.all([
    Promise.race([tradesP, _snapSleep(900).then(() => undefined)]),
    Promise.race([colorP, _snapSleep(300).then(() => undefined)]),
  ]);
  const pending = [];
  let trades = [];
  if (tradesRaced === undefined) pending.push('trades');
  else trades = tradesRaced?.trades || [];
  let color = null;
  if (colorRaced === undefined) pending.push('color');
  else color = colorRaced || null;
  return {
    address: address.toLowerCase(),
    networkId: netId,
    details: details || null,
    bars: bars || null,
    barsResolution: snapRes,
    trades,
    color,
    ts: Date.now(),
    pending,
  };
}

app.get('/api/token/snapshot', async (req, res) => {
  try {
    const { address, networkId = 1 } = req.query;
    if (!address) return res.status(400).json({ error: 'Address is required' });
    // Bars resolution = the chart's boot timeframe (the index.html boot script
    // passes localStorage['spectre-timeframe'] -> resolution); default 1H. Part
    // of the cache key so a 12H and a 1H snapshot for the same token don't collide.
    // Phase is NOT in the key: one assembly, two gates (fast vs full).
    const snapRes = String(req.query.resolution || '60');

    // Auto-detect Solana addresses (base58, 32-44 chars, no 0x prefix)
    const isSolAddr = !address.startsWith('0x') && address.length >= 32 && address.length <= 44;
    const netId = (isSolAddr && parseInt(networkId) === 1) ? 1399811149 : parseInt(networkId);
    const cacheKey = `${address.toLowerCase()}:${netId}:${snapRes}`;
    const isFast = req.query.phase === 'fast';

    const cached = _snapshotCache.get(cacheKey);
    if (cached && (Date.now() - cached.ts) < SNAPSHOT_CACHE_TTL) {
      res.set('Cache-Control', 'public, s-maxage=60, stale-while-revalidate=300');
      return res.json(cached.data);
    }

    if (_snapshotInflight.has(cacheKey)) {
      try {
        const bundle = _snapshotInflight.get(cacheKey);
        const data = isFast ? await _snapshotFastResponse(bundle, { address, netId, snapRes }) : await bundle.fullP;
        // Match the cached/fresh branch header so every snapshot response
        // path carries consistent cache semantics.
        res.set('Cache-Control', 'public, s-maxage=60, stale-while-revalidate=300');
        return res.json(data);
      } catch (err) {
        res.set('Cache-Control', 'no-store');
        return res.status(500).json({ error: err?.message || 'snapshot failed' });
      }
    }

    const bundle = _buildSnapshotAssembly({ address, netId, snapRes });
    _snapshotInflight.set(cacheKey, bundle);
    // Patch the cache when the FULL assembly (incl. late trades/color) lands.
    // The Express process persists, so a bare .then() patch survives - no
    // waitUntil needed (that's a serverless-only concern).
    bundle.fullP
      .then((full) => { _snapshotCache.set(cacheKey, { data: full, ts: Date.now() }); })
      .catch(() => { /* assembly failed - nothing to cache */ })
      .finally(() => { if (_snapshotInflight.get(cacheKey) === bundle) _snapshotInflight.delete(cacheKey); });

    const data = isFast
      ? await _snapshotFastResponse(bundle, { address, netId, snapRes })
      : await bundle.fullP;

    res.set('Cache-Control', 'public, s-maxage=60, stale-while-revalidate=300');
    res.json(data);
  } catch (err) {
    console.error('[snapshot] error:', err?.message || err);
    res.status(500).json({ error: err?.message || 'snapshot failed' });
  }
});

// Batch variant - fetch market + metadata for many addresses in one GraphQL
// call per network. Accepts ?ids=address:networkId,address:networkId,...
// Returns { [addressLower]: { ...detailShape }, _missing: [addresses] }
// True when the two Codex-derived mcaps disagree enough that neither can be
// trusted (stale info.circulatingSupply class - LNQ: computed $855K vs API
// $6.45M vs the real ~$2.6M). Cheap gate so DexScreener is only consulted
// for genuinely suspicious rows. Mirror: apps/trading/api/codex.js.
function mcapLooksWrong(computed, api) {
  if (!(computed > 0)) return api > 0; // nothing computed but API has a value - cross-check
  if (!(api > 0)) return true;         // computed but unverifiable - cross-check
  const ratio = computed > api ? computed / api : api / computed;
  return ratio > 1.5;
}

app.get('/api/token/details-batch', async (req, res) => {
  try {
    const raw = String(req.query.ids || '').trim();
    if (!raw) return res.status(400).json({ error: 'ids is required' });

    const pairs = raw.split(',').map(s => s.trim()).filter(Boolean).map(s => {
      const [address, netStr] = s.split(':');
      const isSol = address && !address.startsWith('0x') && address.length >= 32 && address.length <= 44;
      const networkId = netStr ? parseInt(netStr) : (isSol ? 1399811149 : 1);
      return { address, networkId: (isSol && networkId === 1) ? 1399811149 : networkId };
    }).filter(p => p.address);

    if (pairs.length === 0) return res.json({});
    if (pairs.length > 50) return res.status(400).json({ error: 'Max 50 addresses per batch' });

    const out = {};
    const misses = [];
    const freshRows = []; // rows built this request (mcap sanity overlay below)

    // Serve from cache first
    for (const { address, networkId } of pairs) {
      const cacheKey = `${address.toLowerCase()}_${networkId}`;
      const cached = getCached(cache.details, cacheKey, CACHE_TTL_DETAILS_MS);
      if (cached) out[address.toLowerCase()] = cached;
      else misses.push({ address, networkId });
    }

    if (misses.length === 0) return res.json(out);

    // Group remaining by network, query filterTokens once per network
    const byNet = new Map();
    for (const m of misses) {
      if (!byNet.has(m.networkId)) byNet.set(m.networkId, []);
      byNet.get(m.networkId).push(m.address);
    }

    const batchQuery = `
      query BatchTokenDetails($networkFilter: [Int!], $addresses: [String!]!) {
        filterTokens(
          filters: { network: $networkFilter }
          tokens: $addresses
          limit: 100
        ) {
          results {
            token {
              address
              symbol
              name
              networkId
              createdAt
              info {
                imageThumbUrl
                imageLargeUrl
                circulatingSupply
              }
            }
            priceUSD
            volume24
            liquidity
            marketCap
            change24
            change1
            change4
            change12
            holders
            txnCount24
          }
        }
      }
    `;

    await Promise.all([...byNet.entries()].map(async ([netId, addresses]) => {
      const isSol = netId === 1399811149;
      const queryAddrs = isSol ? addresses : addresses.map(a => a.toLowerCase());
      try {
        const data = await executeCodexQuery(batchQuery, {
          networkFilter: [netId],
          addresses: queryAddrs,
        });
        const results = data?.filterTokens?.results || [];
        const byAddr = new Map();
        for (const r of results) {
          const addr = (r?.token?.address || '').toLowerCase();
          if (addr) byAddr.set(addr, r);
        }

        for (const address of addresses) {
          const r = byAddr.get(address.toLowerCase());
          if (!r) continue;
          const token = r.token || {};
          const price = parseFloat(r.priceUSD) || 0;
          const circulatingSupply = parseFloat(token.info?.circulatingSupply) || 0;
          const apiMarketCap = parseFloat(r.marketCap) || 0;
          const calculatedMarketCap = (price > 0 && circulatingSupply > 0)
            ? price * circulatingSupply
            : apiMarketCap;
          const createdAt = token.createdAt || null;
          const ageInDays = createdAt
            ? Math.floor((Date.now() - new Date(createdAt * 1000)) / 86400000)
            : null;

          const result = {
            address: token.address || address,
            name: token.name,
            symbol: token.symbol,
            networkId: token.networkId || netId,
            logo: token.info?.imageLargeUrl || token.info?.imageThumbUrl || null,
            price,
            volume24: parseFloat(r.volume24) || 0,
            liquidity: parseFloat(r.liquidity) || 0,
            marketCap: calculatedMarketCap,
            apiMarketCap,
            change24: parseFloat(r.change24) || 0,
            change1h: parseFloat(r.change1) || 0,
            change4h: parseFloat(r.change4) || 0,
            change12h: parseFloat(r.change12) || 0,
            holders: parseInt(r.holders) || 0,
            txnCount24: parseInt(r.txnCount24) || 0,
            uniqueWallets24: 0,
            createdAt,
            age: ageInDays,
            // Trimmed market-row shape - the batch query deliberately skips
            // info{circulatingSupply,totalSupply}/socials/decimals/description.
            // Flag it so /api/token/details treats this cache entry as a miss
            // instead of serving it to full-details consumers.
            _batchShape: true,
          };

          const cacheKey = `${address.toLowerCase()}_${netId}`;
          setCached(cache.details, cacheKey, result, CACHE_TTL_DETAILS_MS);
          out[address.toLowerCase()] = result;
          freshRows.push(result);
        }
      } catch (err) {
        console.error(`Batch details query failed for network ${netId}:`, err.message);
      }
    }));

    // MCap sanity overlay: Codex's info.circulatingSupply goes stale (LNQ
    // carried 132.7M vs the real ~424M -> watchlist showed $855K instead of
    // ~$2.6M). Where computed and API mcap disagree >1.5x, take DexScreener's
    // circulating mcap (batched + 4-min cached in the enrich helper). The
    // mutation also updates the cache entry - setCached stored the same ref.
    const suspicious = freshRows.filter(r => mcapLooksWrong(r.marketCap, r.apiMarketCap));
    if (suspicious.length > 0) {
      try {
        const dsEnr = await enrichFromDexScreener(
          suspicious.map(r => ({ address: r.address, networkId: r.networkId }))
        );
        for (const r of suspicious) {
          const ds = dsEnr.get(dsNorm(r.address));
          if (ds && ds.marketCap > 0) {
            r.marketCap = ds.marketCap;
            r.mcapSource = 'dexscreener';
          }
        }
      } catch (_) { /* fail-soft: keep the Codex-derived values */ }
    }

    res.json(out);
  } catch (error) {
    console.warn('[token/details-batch] returning empty:', error?.message)
    res.setHeader('Cache-Control', 'no-store')
    return res.status(200).json({})
  }
});

