/**
 * Search tokens by name, symbol, or address (cached 30s)
 */
const _codexSearchCache = new Map(); // key: q+networks, value: { data, ts }
// In-flight dedup: when N clients hit the same query simultaneously, only one
// runs the upstream Codex calls; others await the shared Promise. Critical at
// beta scale (100+ users searching popular tokens like BTC, SOL within the
// 30s cache window will otherwise each fan out to 6 parallel Codex queries).
const _codexSearchInflight = new Map();
const CODEX_SEARCH_CACHE_TTL = 30_000;
const CODEX_SEARCH_CACHE_MAX = 100;

// GMGN-parity search (2026-06-10): Hetzner /v1/search tier for the dev
// Express route, mirroring prod's L4-PR2 handleTokenSearch. Hydrates
// identity rows (no on-chain address upstream) through the registry's
// cgId -> address bridge - rows that don't hydrate are dropped because the
// trading frontend discards address-less results. Shared by the fast=1
// leading-edge tier (Hetzner ONLY, never Codex) and the settled tier
// (Hetzner short-circuit before the Codex text search).
const _devCgIdToKnownToken = (() => {
  const out = new Map();
  try {
    const reg = require('./lib/token-registry');
    const known = reg?.KNOWN_TOKEN_ADDRESSES || {};
    const cgMap = reg?.SYMBOL_TO_COINGECKO_ID || {};
    for (const [sym, info] of Object.entries(known)) {
      const cgId = cgMap[sym];
      if (!info?.address || info?.networkId == null || !cgId) continue;
      out.set(String(cgId).toLowerCase(), { symbol: sym, name: info.name || sym, address: info.address, networkId: info.networkId });
    }
    // Search-hydration expansion (2026-06-10): validated top-CG contracts.
    for (const [cgId, info] of Object.entries(reg?.EXTENDED_CG_TOKENS || {})) {
      if (!out.has(cgId)) out.set(cgId, { symbol: info.symbol, name: info.name || info.symbol, address: info.address, networkId: info.networkId });
    }
  } catch (_) { /* registry unavailable - tier degrades to no hydration */ }
  out.set('dogwifcoin', { symbol: 'WIF', name: 'dogwifhat', address: 'EKpQGSJtjMFqKZ9KQanSqYXRcF8fBopzLHYxdM65zcjm', networkId: 1399811149 });
  out.set('bonk', { symbol: 'BONK', name: 'Bonk', address: 'DezXAZ8z7PnrnRJjz3wXBoRgixCa6xjnB7YaB1pPB263', networkId: 1399811149 });
  out.set('moo-deng', { symbol: 'MOODENG', name: 'Moo Deng', address: 'ED5nyyWEzpPPiWimP8vYm7sD7TD3LAt3Q3gRTWHzPJBY', networkId: 1399811149 });
  return out;
})();

// Hetzner /v1/search returns IDENTITY-ONLY rows (symbol/name/image/rank/cgId -
// no price fields), so a short-circuited search used to paint $0.00 on every
// surface that doesn't run its own details-batch enrichment (mobile search).
// Backfill prices with ONE Hetzner /v1/prices call. Symbols are sorted (the
// box's cache key is order-sensitive) and each merge is address-verified
// against the price row's `contract` - a colliding ticker (the $DOT/Polkadot
// class) keeps its zeros rather than inheriting another coin's price.
// change24 is emitted in RATIO form (pct/100) to match Codex rows, which is
// what the client's readCodexChangePct heuristic expects for |v| <= 1.
// Wall-clock ceiling for the whole `fast=1` search tier (see the fast branch
// in /api/tokens/search). Kept just under the settled tier's typical ~1.1s so
// a fast result always arrives first or not at all.
const FAST_TIER_BUDGET_MS = 900;

async function _spectrePricesBackfillDev(rows, { origin, key, timeoutMs = 900 }) {
  const symbols = [...new Set(rows.map(r => r.token.symbol).filter(Boolean))].sort();
  if (!symbols.length) return;
  try {
    const r = await fetch(`${origin}/v1/prices?${new URLSearchParams({ symbols: symbols.join(',') })}`, {
      headers: { 'X-API-Key': key, Accept: 'application/json' },
      signal: AbortSignal.timeout(timeoutMs),
    });
    if (!r.ok) return;
    const data = (await r.json())?.data || {};
    for (const row of rows) {
      const p = data[row.token.symbol];
      if (!p || !(Number(p.price) > 0)) continue;
      const contract = String(p.contract || '').toLowerCase();
      if (contract && contract !== String(row.token.address).toLowerCase()) continue;
      if (!(row.priceUSD > 0)) row.priceUSD = Number(p.price) || 0;
      if (!(row.marketCap > 0)) row.marketCap = Number(p.market_cap) || 0;
      if (!(row.volume24 > 0)) row.volume24 = Number(p.volume_24h) || 0;
      const chg = Number(p.change && p.change['24h']);
      if (!row.change24 && Number.isFinite(chg)) row.change24 = chg / 100;
    }
  } catch (_) { /* fail-soft - rows stay identity-only */ }
}

// `timeoutMs` is the budget for the WHOLE call, not just the /v1/search leg.
// It used to cover only the search fetch, and the price backfill nested below
// then started its own fresh 900ms clock - so the fast tier's declared 500ms
// budget silently cost up to 1400ms (measured 2026-07-22: every cold fast
// search returned in a suspiciously constant ~1.405s). The backfill now gets
// whatever is LEFT of the budget, so `fast=1` stays inside its promise. Rows
// that miss the shortened backfill stay identity-only for ~300-600ms until the
// settled tier lands with real prices - it already re-paints over them.
async function _spectreSearchHetznerDev(query, timeoutMs = 800) {
  const key = process.env.SPECTRE_DATA_API_KEY || process.env.SPECTRE_API_KEY;
  if (!key) return null;
  const origin = process.env.SPECTRE_API_ORIGIN || 'http://204.168.244.18:3850';
  const startedAt = Date.now();
  try {
    const r = await fetch(`${origin}/v1/search?${new URLSearchParams({ q: query, limit: '15' })}`, {
      headers: { 'X-API-Key': key, Accept: 'application/json' },
      signal: AbortSignal.timeout(timeoutMs),
    });
    if (!r.ok) return null;
    const json = await r.json();
    const coins = json?.data?.coins || json?.coins || [];
    if (!Array.isArray(coins) || coins.length === 0) return null;
    const hydrated = [];
    for (const c of coins) {
      const cgId = (c.coingecko_id || c.id || '').toLowerCase();
      const known = cgId ? _devCgIdToKnownToken.get(cgId) : null;
      const address = c.address || c.contract_address || known?.address || null;
      const networkId = c.networkId || known?.networkId || null;
      if (!address || networkId == null) continue;
      hydrated.push({
        token: {
          address,
          symbol: (c.symbol || known?.symbol || '').toUpperCase(),
          name: c.name || known?.name || '',
          networkId,
          info: { imageThumbUrl: c.image || c.thumb || null, imageLargeUrl: c.image || c.large || null },
        },
        priceUSD: c.price || c.current_price || 0,
        volume24: c.volume_24h || c.total_volume || 0,
        liquidity: c.liquidity || 0,
        marketCap: c.market_cap || c.marketCap || 0,
        change24: c.change_24h || c.price_change_percentage_24h || 0,
        holders: 0,
        _source: 'hetzner',
      });
    }
    if (hydrated.length === 0) return null;
    if (hydrated.some(row => !(row.priceUSD > 0))) {
      // Spend only what's left of the caller's budget (see the note above).
      const remaining = timeoutMs - (Date.now() - startedAt);
      if (remaining >= 150) {
        await _spectrePricesBackfillDev(hydrated, { origin, key, timeoutMs: Math.min(900, remaining) });
      }
    }
    return { results: hydrated };
  } catch (_) {
    return null;
  }
}

// fast=1 fallback when no Hetzner key is configured locally: prefix-match
// the registry so dev without secrets still paints instant rows.
function _registrySearchFallback(query) {
  const qLower = String(query || '').toLowerCase();
  const out = [];
  for (const [, info] of _devCgIdToKnownToken) {
    if (out.length >= 10) break;
    if (info.symbol.toLowerCase().startsWith(qLower) || (info.name || '').toLowerCase().startsWith(qLower)) {
      out.push({
        token: { address: info.address, symbol: info.symbol, name: info.name || info.symbol, networkId: info.networkId, info: {} },
        priceUSD: 0, volume24: 0, liquidity: 0, marketCap: 0, change24: 0, holders: 0,
        _source: 'registry',
      });
    }
  }
  return { results: out };
}

app.get('/api/tokens/search', async (req, res) => {
  const { q, networks } = req.query;
  const isFastTier = req.query.fast === '1';
  // Tier-suffixed key: a Hetzner-only fast entry must NEVER serve a full
  // search request from cache (the details-batch cache-poisoning lesson).
  const cacheKey = `${(q || '').toLowerCase().trim()}|${networks || ''}|${isFastTier ? 'fast' : 'full'}`;

  console.log(`Search request: q="${q}", networks="${networks}"${isFastTier ? ' [fast]' : ''}`);

  if (!q || q.length < 2 || q.length > 100) {
    return res.json({ results: [] });
  }

  // Check cache first
  const cachedEarly = _codexSearchCache.get(cacheKey);
  if (cachedEarly && (Date.now() - cachedEarly.ts) < CODEX_SEARCH_CACHE_TTL) {
    return res.json(cachedEarly.data);
  }

  // If another request for this exact query is in flight, await its result.
  const inflight = _codexSearchInflight.get(cacheKey);
  if (inflight) {
    try {
      const sharedData = await inflight;
      return res.json(sharedData);
    } catch (err) {
      // fall through and try ourselves; the original request's error
      // shouldn't condemn this one
    }
  }

  // Set up a Promise other concurrent callers can await.
  let _resolveInflight, _rejectInflight;
  const inflightPromise = new Promise((resolve, reject) => {
    _resolveInflight = resolve;
    _rejectInflight = reject;
  });
  _codexSearchInflight.set(cacheKey, inflightPromise);
  // Always clear the inflight slot when the Promise settles, so future
  // requests don't await a stale Promise after this handler returns.
  inflightPromise.finally(() => {
    if (_codexSearchInflight.get(cacheKey) === inflightPromise) {
      _codexSearchInflight.delete(cacheKey);
    }
  }).catch(() => {});

  try {
    // fast=1 - leading-edge keystroke tier (GMGN-parity search). Hetzner
    // /v1/search ONLY - structurally never Codex (returns before any
    // executeCodexQuery below). Address-shaped queries fall to the settled
    // path where Codex is canonical for address resolution. Registry
    // prefix-matches stand in when no Hetzner key is configured locally.
    if (isFastTier) {
      const fq = String(q).trim();
      const isAddrShaped = (fq.startsWith('0x') && fq.length === 42) ||
        (!fq.startsWith('0x') && fq.length >= 32 && fq.length <= 44 && /^[1-9A-HJ-NP-Za-km-z]+$/.test(fq));
      let fastData = { results: [], fast: true };
      if (!isAddrShaped) {
        // Hard wall-clock ceiling for the WHOLE fast tier. This tier only
        // earns its name if it beats the settled tier (~1.1s), so every leg
        // below spends against this one deadline instead of starting a fresh
        // timeout of its own.
        const fastDeadline = Date.now() + FAST_TIER_BUDGET_MS;
        const hit = await _spectreSearchHetznerDev(fq, 500);
        if (hit) {
          fastData = { ...hit, fast: true };
        } else {
          // Registry rows are identity-only too - same $0.00 class as the
          // Hetzner rows. Backfill them when a Hetzner key is available
          // (a cold /v1/search can miss the 500ms budget while /v1/prices
          // for a couple of symbols answers well inside its own).
          const reg = _registrySearchFallback(fq);
          const hzKey = process.env.SPECTRE_DATA_API_KEY || process.env.SPECTRE_API_KEY;
          const remaining = fastDeadline - Date.now();
          if (hzKey && remaining >= 150 && reg.results.some(row => !(row.priceUSD > 0))) {
            await _spectrePricesBackfillDev(reg.results, {
              origin: process.env.SPECTRE_API_ORIGIN || 'http://204.168.244.18:3850',
              key: hzKey,
              timeoutMs: Math.min(900, remaining),
            });
          }
          fastData = { ...reg, fast: true };
        }
      }
      _resolveInflight(fastData);
      if (fastData.results.length > 0) {
        _codexSearchCache.set(cacheKey, { data: fastData, ts: Date.now() });
      }
      return res.json(fastData);
    }

    // Use provided networks or default to all
    const networkIds = networks
      ? networks.split(',').map(n => parseInt(n))
      : ALL_NETWORK_IDS;
    
    const searchQuery = q.trim();
    const upperQ = searchQuery.toUpperCase().replace(/^\$/, '');

    // FIX 5: Registry-first — if exact match in TOKEN_REGISTRY, pin to top
    const registryMatch = getTokenInfo(upperQ);
    let pinnedResult = null;
    if (registryMatch && registryMatch.address) {
      pinnedResult = {
        symbol: upperQ,
        name: registryMatch.name || upperQ,
        address: registryMatch.address,
        networkId: registryMatch.networkId,
        isPinned: true,
      };
    }

    console.log(`Searching for: "${searchQuery}" on ${networkIds.length} networks${pinnedResult ? ' (registry match pinned)' : ''}`);

    // Check if searching by contract address
    const isEvmAddress = searchQuery.startsWith('0x') && searchQuery.length === 42;
    const isSolanaAddress = !searchQuery.startsWith('0x') && searchQuery.length >= 32 && searchQuery.length <= 44 && /^[1-9A-HJ-NP-Za-km-z]+$/.test(searchQuery);
    const isContractSearch = isEvmAddress || isSolanaAddress;
    
    if (isContractSearch) {
      console.log(`Searching for ${isSolanaAddress ? 'Solana' : 'EVM'} contract ${searchQuery} across ${networkIds.length} networks...`);
      
      // Search by address across ALL networks in parallel for speed
      const tokenQuery = `
        query GetTokenByAddress($address: String!, $networkId: Int!) {
          token(input: { address: $address, networkId: $networkId }) {
            address
            name
            symbol
            decimals
            networkId
            info {
              imageThumbUrl
              imageLargeUrl
              circulatingSupply
            }
          }
        }
      `;
      
      // Try networks in SMALL ordered batches and stop at the first hit. This
      // used to fire 10 `token` queries at once over the 35-network map for
      // every address search (9 of them "not found" errors), and the deep-link
      // resolver runs this arm on every page load. A Solana address can only
      // live on Solana, so it is one query; an EVM address tries the caller's
      // `networkId` hint first, then the chains that hold nearly every token we
      // ever resolve (Ethereum, Base, BSC), then the long tail.
      const foundTokens = [];
      const hintedNet = parseInt(req.query.networkId);
      const batches = [];
      if (isSolanaAddress) {
        if (networkIds.includes(1399811149)) batches.push([1399811149]);
      } else {
        const evmNets = networkIds.filter(n => n !== 1399811149);
        const seen = new Set();
        // The hint alone first (one query resolves nearly every deep link),
        // then the big three, then the long tail in threes.
        if (Number.isFinite(hintedNet) && evmNets.includes(hintedNet)) { batches.push([hintedNet]); seen.add(hintedNet); }
        const rest = [...[1, 8453, 56, 42161, 137].filter(n => evmNets.includes(n)), ...evmNets].filter(n => !seen.has(n) && seen.add(n));
        for (let i = 0; i < rest.length; i += 3) batches.push(rest.slice(i, i + 3));
      }

      for (const batch of batches) {
        const promises = batch.map(async (networkId) => {
          try {
            // Solana addresses are case-sensitive, EVM addresses should be lowercase
            const queryAddr = isSolanaAddress ? searchQuery : searchQuery.toLowerCase();
            const result = await executeCodexQuery(tokenQuery, { 
              address: queryAddr, 
              networkId 
            });
            
            if (result?.token) {
              return {
                token: result.token,
                networkId,
              };
            }
          } catch (err) {
            // Token not found on this network
          }
          return null;
        });
        
        const batchResults = await Promise.all(promises);
        foundTokens.push(...batchResults.filter(r => r !== null));
        
        // If we found results, break early
        if (foundTokens.length > 0) {
          break;
        }
      }
      
      if (foundTokens.length === 0) {
        console.log('Token not found on any network');
        // Settle the in-flight Promise AND cache the empty result, otherwise
        // concurrent callers awaiting `_codexSearchInflight.get(cacheKey)`
        // hang forever — and even after their await, the next caller within
        // CODEX_SEARCH_CACHE_TTL skips this whole path on cache hit only if
        // the empty result is cached. Without these two lines the empty
        // result silently destroys the search system: the in-flight slot
        // pins the Promise as pending, every subsequent search for the
        // same query awaits a Promise that never resolves. Fixed 2026-05-26.
        const emptyData = { results: [] };
        _codexSearchCache.set(cacheKey, { data: emptyData, ts: Date.now() });
        _resolveInflight(emptyData);
        return res.json(emptyData);
      }
      
      console.log(`Found token on ${foundTokens.length} network(s), fetching market data...`);
      
      // Now fetch market data for found tokens
      const resultsWithMarketData = await Promise.all(foundTokens.map(async ({ token, networkId }) => {
        try {
          // Try filterTokens with token address to get market data
          const marketQuery = `
            query GetTokenMarketData($networkId: [Int!], $address: String!) {
              filterTokens(
                filters: { network: $networkId }
                tokens: [$address]
                limit: 1
              ) {
                results {
                  priceUSD
                  change24
                  volume24
                  liquidity
                  marketCap
                }
              }
            }
          `;
          
          let priceUSD = 0;
          let change24 = 0;
          let volume = 0;
          let liquidity = 0;
          let marketCap = 0;
          
          try {
            const queryAddr = isSolanaAddress ? searchQuery : searchQuery.toLowerCase();
            const marketData = await executeCodexQuery(marketQuery, {
              networkId: [networkId],
              address: queryAddr,
            });
            
            const stats = marketData?.filterTokens?.results?.[0];
            if (stats) {
              priceUSD = stats.priceUSD || 0;
              change24 = stats.change24 || 0;
              volume = stats.volume24 || 0;
              liquidity = stats.liquidity || 0;
              marketCap = stats.marketCap || 0;
            }
          } catch (filterErr) {
            console.log(`filterTokens failed for ${token.symbol}, trying pairs...`);
            
            // Fallback to pairs query
            const pairsQuery = `
              query GetTokenPairs($tokenAddress: String!, $networkId: Int!) {
                listPairsForToken(
                  tokenAddress: $tokenAddress
                  networkId: $networkId
                  limit: 1
                ) {
                  liquidity
                  volume24
                  priceUSD
                }
              }
            `;
            
            try {
              const queryAddr = isSolanaAddress ? searchQuery : searchQuery.toLowerCase();
              const pairsData = await executeCodexQuery(pairsQuery, {
                tokenAddress: queryAddr,
                networkId,
              });
              
              const mainPair = pairsData?.listPairsForToken?.[0];
              if (mainPair) {
                priceUSD = mainPair.priceUSD || 0;
                volume = mainPair.volume24 || 0;
                liquidity = mainPair.liquidity || 0;
              }
            } catch (pairsErr) {
              console.log(`Pairs query also failed for ${token.symbol}`);
            }
          }
          
          // Calculate market cap from circulating supply if available
          if (!marketCap && token.info?.circulatingSupply && priceUSD) {
            marketCap = parseFloat(token.info.circulatingSupply) * priceUSD;
          }
          
          console.log(`Market data for ${token.symbol}: price=$${priceUSD}, vol=$${volume}, liq=$${liquidity}, mcap=$${marketCap}`);
          
          return {
            token: {
              ...token,
              networkId,
              networkName: CODEX_NETWORKS[networkId] || `Network ${networkId}`,
            },
            priceUSD,
            change24,
            volume,
            liquidity,
            marketCap,
          };
        } catch (err) {
          console.error(`Failed to fetch market data for ${token.symbol}:`, err.message);
          // Return token without market data
          return {
            token: {
              ...token,
              networkId,
              networkName: CODEX_NETWORKS[networkId] || `Network ${networkId}`,
            },
            priceUSD: 0,
            change24: 0,
            volume: 0,
            liquidity: 0,
            marketCap: 0,
          };
        }
      }));
      
      // Settle the in-flight Promise AND cache before early return — same
      // reasoning as the foundTokens.length===0 branch above. Forgetting
      // these two lines makes concurrent searches hang on the orphaned
      // Promise. Fixed 2026-05-26.
      const contractData = { results: resultsWithMarketData };
      _codexSearchCache.set(cacheKey, { data: contractData, ts: Date.now() });
      _resolveInflight(contractData);
      return res.json(contractData);
    }

    // Popular-Solana direct fetch, as a THUNK. Pre-2026-07-20 this block ran
    // (2 Codex queries, awaited) BEFORE the Hetzner short-circuit - so the
    // hottest queries (wif/bonk/jup) paid Codex ops + a full round-trip even
    // when Hetzner answered them. Now it only fires AFTER the short-circuit
    // misses, in parallel with the text searches below.
    const searchLowerForPopular = searchQuery.toLowerCase();
    const fetchPopularSolanaDev = async () => {
      const popular = POPULAR_SOLANA_TOKENS[searchLowerForPopular];
      if (!popular) return null;
      try {
        // Fetch token data directly by address
        const tokenQuery = `
          query GetToken($address: String!, $networkId: Int!) {
            token(input: { address: $address, networkId: $networkId }) {
              address
              symbol
              name
              networkId
              info {
                imageThumbUrl
                imageLargeUrl
              }
            }
          }
        `;
        const marketQuery = `
          query GetMarket($networkFilter: [Int!], $phrase: String!) {
            filterTokens(filters: { network: $networkFilter }, phrase: $phrase, limit: 1) {
              results {
                priceUSD
                volume24
                liquidity
                marketCap
                change24
                holders
              }
            }
          }
        `;

        const [tokenData, marketData] = await Promise.all([
          executeCodexQuery(tokenQuery, { address: popular.address, networkId: 1399811149 }),
          executeCodexQuery(marketQuery, { networkFilter: [1399811149], phrase: popular.address }),
        ]);

        if (tokenData?.token) {
          const market = marketData?.filterTokens?.results?.[0] || {};
          console.log(`Found popular Solana token: ${popular.symbol} - MC:${market.marketCap}, Liq:${market.liquidity}`);
          return {
            token: {
              ...tokenData.token,
              networkName: 'Solana',
            },
            priceUSD: market.priceUSD || 0,
            volume24: market.volume24 || 0,
            liquidity: market.liquidity || 0,
            marketCap: market.marketCap || 0,
            change24: market.change24 || 0,
            holders: market.holders || 0,
            volume: market.volume24 || 0,
            qualityScore: 200, // High score for known tokens
          };
        }
      } catch (e) {
        console.log(`Failed to fetch popular Solana token: ${e.message}`);
      }
      return null;
    };

    // L4-PR2 parity (dev): Hetzner Tier-1 short-circuit for text queries,
    // same contract as prod handleTokenSearch. A hit means the Codex text
    // search below never fires - zero Codex on the hottest queries. Same
    // kill switch as prod.
    if (process.env.L4_PR2_DISABLE_HETZNER_SEARCH !== '1') {
      const spectreHit = await _spectreSearchHetznerDev(searchQuery, 800);
      if (spectreHit && spectreHit.results.length > 0) {
        const data = { results: spectreHit.results };
        _codexSearchCache.set(cacheKey, { data, ts: Date.now() });
        if (_codexSearchCache.size > CODEX_SEARCH_CACHE_MAX) {
          const firstKey = _codexSearchCache.keys().next().value;
          _codexSearchCache.delete(firstKey);
        }
        _resolveInflight(data);
        return res.json(data);
      }
    }

    // Text search - prioritize by LIQUIDITY (hardest to fake) not market cap
    const query = `
      query SearchTokens($search: String!, $networkFilter: [Int!], $limit: Int!) {
        filterTokens(
          filters: { network: $networkFilter }
          phrase: $search
          limit: $limit
          rankings: [
            { attribute: liquidity, direction: DESC }
          ]
        ) {
          results {
            token {
              address
              symbol
              name
              networkId
              info {
                imageThumbUrl
                imageLargeUrl
              }
            }
            volume24
            liquidity
            marketCap
            priceUSD
            change24
            holders
          }
        }
      }
    `;
    
    // For text search, use popular networks by default (including Solana!)
    const searchNetworks = networks
      ? networkIds
      : [1399811149, 1, 56, 137, 42161, 8453, 43114, 10, 250, 324, 59144, 81457, 4663]; // Solana + Top EVM networks + Robinhood Chain
    
    // Main search + $-prefixed search + popular-Solana fetch in PARALLEL
    // (was 3 sequential awaits - each a Codex round-trip, up to 5s worst-case
    // apiece on a cold connection). Main-search rejection still propagates to
    // the outer catch exactly as before; the $-search and popular fetch stay
    // fail-soft.
    const emptyFT = { filterTokens: { results: [] } };
    const [popularSolanaResult, result, dollarResults] = await Promise.all([
      fetchPopularSolanaDev(),
      executeCodexQuery(query, {
        search: searchQuery,
        networkFilter: searchNetworks,
        limit: 50 // Fetch more to filter and sort
      }),
      // Also search with $ prefix (many Solana tokens use $ in symbol)
      (!searchQuery.startsWith('$') && searchQuery.length <= 10)
        ? executeCodexQuery(query, {
            search: `$${searchQuery}`,
            networkFilter: searchNetworks,
            limit: 20
          }).catch(() => emptyFT)
        : Promise.resolve(emptyFT),
    ]);

    // Combine results (include popular Solana token if found)
    const combinedResults = [
      ...(popularSolanaResult ? [popularSolanaResult] : []),
      ...(result?.filterTokens?.results || []),
      ...(dollarResults?.filterTokens?.results || [])
    ];
    
    // Deduplicate by address
    const seenAddresses = new Set();
    const rawResults = combinedResults.filter(r => {
      const addr = r.token?.address?.toLowerCase();
      if (!addr || seenAddresses.has(addr)) return false;
      seenAddresses.add(addr);
      return true;
    });
    
    // Smart quality scoring function - ranks tokens by legitimacy
    const calculateQualityScore = (r, searchTerm) => {
      let score = 0;
      
      const mcap = parseFloat(r.marketCap) || 0;
      const liq = parseFloat(r.liquidity) || 0;
      const volume = parseFloat(r.volume24) || 0;
      const holders = parseInt(r.holders) || 0;
      const price = parseFloat(r.priceUSD) || 0;
      const symbol = (r.token?.symbol || '').toLowerCase();
      const name = (r.token?.name || '').toLowerCase();
      const search = searchTerm.toLowerCase();
      
      // INSTANT DISQUALIFY: Obviously fake (trillion mcap with no liquidity)
      if (mcap > 100e9 && liq < 1000) return -1000;
      if (mcap > 1e12) return -1000; // No token is worth a trillion
      // Fake: huge mcap but zero/tiny liquidity
      if (mcap > 1e9 && liq < 100) return -1000;
      
      // MINIMUM REQUIREMENTS: Must have real liquidity AND market cap
      // Filter out micro tokens that are likely dead or scams
      if (liq < 1000) return -1000;  // Less than $1k liquidity = not tradeable
      if (mcap < 1000 && liq < 5000) return -1000;  // Tiny mcap with low liq = dead
      
      // RED FLAG: Liquidity much higher than market cap = fake/honeypot
      // Real tokens: mcap is usually 2-100x liquidity
      // Scam tokens often have huge fake liquidity but tiny mcap
      if (mcap > 0 && liq > 0) {
        const liqToMcapRatio = liq / mcap;
        if (liqToMcapRatio > 50) return -1000;  // Liquidity 50x+ market cap = scam
      }
      
      // Filter spam token names (common patterns in scam tokens)
      const symbolLower = (r.token?.symbol || '').toLowerCase();
      const spamPatterns = ['spawn', 'test', 'scam', 'honeypot', 'rug', 'fake', 'airdrop'];
      for (const pattern of spamPatterns) {
        if (symbolLower.includes(pattern)) return -1000;
      }
      
      // Start with base score
      score = 10;
      
      // Liquidity scoring (most important - scams have $0)
      if (liq >= 1000000) score += 50;      // $1M+ liquidity = very legit
      else if (liq >= 100000) score += 40;  // $100k+
      else if (liq >= 10000) score += 30;   // $10k+
      else if (liq >= 5000) score += 20;    // $5k+
      else if (liq >= 1000) score += 10;    // $1k+
      
      // Volume scoring (real tokens are traded)
      if (volume >= 100000) score += 30;    // $100k+ daily volume
      else if (volume >= 10000) score += 20;
      else if (volume >= 1000) score += 10;
      else if (volume > 0) score += 5;
      
      // Market cap to liquidity ratio (should be reasonable)
      if (liq > 0 && mcap > 0) {
        const ratio = mcap / liq;
        if (ratio < 50) score += 15;        // Healthy ratio
        else if (ratio < 200) score += 5;
        else if (ratio > 10000) score -= 50; // Very suspicious
        else if (ratio > 5000) score -= 20;  // Suspicious
      }
      
      // Holder count (more holders = more legit)
      if (holders >= 10000) score += 15;
      else if (holders >= 1000) score += 10;
      else if (holders >= 100) score += 5;
      
      // Has a price (not dead)
      if (price > 0) score += 5;
      
      // Bonus for name/symbol match (helps find actual token user wants)
      // Handle $ prefix in symbols (e.g., $WIF should match WIF)
      const symbolClean = symbol.replace(/^\$/, '');
      const searchClean = search.replace(/^\$/, '');
      if (symbol === search || symbolClean === searchClean || name === search) score += 30;
      else if (symbol.startsWith(search) || symbolClean.startsWith(searchClean) || name.startsWith(search)) score += 15;
      else if (symbol.includes(search) || symbolClean.includes(searchClean) || name.includes(search)) score += 5;
      
      return score;
    };
    
    // Debug: log first few results before filtering
    if (rawResults.length > 0) {
      console.log(`Search "${searchQuery}" raw samples:`);
      rawResults.slice(0, 3).forEach(r => {
        const mcap = parseFloat(r.marketCap) || 0;
        const liq = parseFloat(r.liquidity) || 0;
        const vol = parseFloat(r.volume24) || 0;
        console.log(`  ${r.token?.symbol}: mcap=$${mcap.toExponential(2)}, liq=$${liq.toFixed(0)}, vol=$${vol.toFixed(0)}`);
      });
    }
    
    let resultsWithNames = rawResults
      .map(r => ({
        ...r,
        volume: r.volume24 || 0,
        // Keep hardcoded score for popular tokens (score >= 200), otherwise calculate
        qualityScore: (r.qualityScore && r.qualityScore >= 200) ? r.qualityScore : calculateQualityScore(r, searchQuery),
        token: {
          ...r.token,
          networkName: CODEX_NETWORKS[r.token.networkId] || `Network ${r.token.networkId}`,
        }
      }))
      // Filter out obvious scams (very negative score only)
      .filter(r => r.qualityScore > -100);
    
    console.log(`Search "${searchQuery}": API returned ${rawResults.length}, after filter: ${resultsWithNames.length}`);
    
    // Sort results: EXACT MATCHES FIRST, then starts-with, then contains
    const searchLower = searchQuery.toLowerCase().trim();
    const searchNoSpaces = searchLower.replace(/\s+/g, '');
    
    // Calculate match tier for each result
    const getMatchTier = (r) => {
      const symbol = (r.token.symbol || '').toLowerCase();
      const name = (r.token.name || '').toLowerCase();
      const symbolNoSpaces = symbol.replace(/\s+/g, '');
      const nameNoSpaces = name.replace(/\s+/g, '');
      // Handle $ prefix (e.g., "$WIF" should match "WIF")
      const symbolClean = symbol.replace(/^\$/, '');
      const searchClean = searchLower.replace(/^\$/, '');
      
      // TIER 1: Exact symbol or name match (e.g., "wif" matches "$WIF" or "WIF")
      if (symbol === searchLower || symbolNoSpaces === searchNoSpaces || symbolClean === searchClean) return 1;
      if (name === searchLower || nameNoSpaces === searchNoSpaces) return 2;
      
      // TIER 2: Symbol or name STARTS WITH search (e.g., "hash" matches "HashAI")
      if (symbol.startsWith(searchLower) || symbolNoSpaces.startsWith(searchNoSpaces) || symbolClean.startsWith(searchClean)) return 3;
      if (name.startsWith(searchLower) || nameNoSpaces.startsWith(searchNoSpaces)) return 4;
      
      // TIER 3: Symbol or name CONTAINS search
      if (symbol.includes(searchLower) || symbolNoSpaces.includes(searchNoSpaces) || symbolClean.includes(searchClean)) return 5;
      if (name.includes(searchLower) || nameNoSpaces.includes(searchNoSpaces)) return 6;
      
      // No match
      return 99;
    };
    
    resultsWithNames.sort((a, b) => {
      const aTier = getMatchTier(a);
      const bTier = getMatchTier(b);
      
      // Different tiers: lower tier wins (exact match = tier 1)
      if (aTier !== bTier) {
        return aTier - bTier;
      }
      
      // Same tier: sort by quality score (liquidity/volume)
      return (b.qualityScore || 0) - (a.qualityScore || 0);
    });
    
    console.log(`Search "${searchQuery}" top results:`, resultsWithNames.slice(0, 3).map(r => 
      `${r.token.symbol}(tier:${getMatchTier(r)},liq:${r.liquidity})`
    ).join(', '));
    
    // Limit to top 15 results
    resultsWithNames = resultsWithNames.slice(0, 15);
    
    console.log(`Search "${searchQuery}": ${resultsWithNames.length} quality results (top score: ${resultsWithNames[0]?.qualityScore || 0})`);
    
    console.log(`Text search for "${searchQuery}" returned ${resultsWithNames.length} results`);
    if (resultsWithNames.length > 0) {
      console.log('First result:', JSON.stringify(resultsWithNames[0], null, 2));
    }
    
    // FIX 5: Prepend pinned registry match (deduplicated). Carry the market
    // data (price/change/mcap/logo) of the row it displaces - the pinned row
    // used to be identity-only, so pinning a major REPLACED its priced Codex
    // row with a $0.00 top result.
    if (pinnedResult) {
      const pinnedAddr = pinnedResult.address?.toLowerCase();
      const displaced = resultsWithNames.find(r =>
        r.token?.address?.toLowerCase() === pinnedAddr
      );
      const deduped = resultsWithNames.filter(r =>
        r.token?.address?.toLowerCase() !== pinnedAddr
      );
      // Wrap pinnedResult in the same shape as other results
      const pinnedWrapped = {
        ...(displaced || {}),
        token: {
          ...(displaced?.token || {}),
          symbol: pinnedResult.symbol,
          name: pinnedResult.name,
          address: pinnedResult.address,
          networkId: pinnedResult.networkId,
        },
        isPinned: true,
        qualityScore: 999,
      };
      if (!(pinnedWrapped.priceUSD > 0)) {
        const hzKey = process.env.SPECTRE_DATA_API_KEY || process.env.SPECTRE_API_KEY;
        if (hzKey) {
          await _spectrePricesBackfillDev([pinnedWrapped], {
            origin: process.env.SPECTRE_API_ORIGIN || 'http://204.168.244.18:3850',
            key: hzKey,
          });
        }
      }
      resultsWithNames = [pinnedWrapped, ...deduped];
    }

    const responseData = { results: resultsWithNames };
    // Cache the result
    _codexSearchCache.set(cacheKey, { data: responseData, ts: Date.now() });
    if (_codexSearchCache.size > CODEX_SEARCH_CACHE_MAX) {
      const firstKey = _codexSearchCache.keys().next().value;
      _codexSearchCache.delete(firstKey);
    }
    _resolveInflight(responseData);
    res.json(responseData);

  } catch (error) {
    const msg = error?.message || ''
    console.warn('[search] returning empty results:', msg)
    _rejectInflight(error);
    // Serve stale cache on error if available
    const stale = _codexSearchCache.get(cacheKey);
    if (stale) return res.json(stale.data);
    // Return 200 + empty array so the frontend treats this as a clean
    // "no matches" response instead of a hard error. The frontend's
    // searchTokens() throws on non-2xx and floods console.error.
    res.setHeader('Cache-Control', 'no-store');
    return res.status(200).json({ results: [], degraded: true, reason: /not activated|429|403/i.test(msg) ? msg : 'search_unavailable' });
  }
});

