/**
 * Well-known token addresses for major cryptocurrencies
 * These are the canonical wrapped versions on their primary networks
 */
// WELL_KNOWN_TOKENS — now sourced from unified TOKEN_REGISTRY (server/lib/token-registry.js)
const WELL_KNOWN_TOKENS = Object.fromEntries(
  Object.entries(TOKEN_REGISTRY)
    .filter(([, info]) => info && info.address)
    .map(([sym, info]) => [sym, { address: info.address, networkId: info.networkId, name: info.name }])
);

/**
 * Internal: get price for one symbol (Codex first, CoinGecko fallback).
 * Returns { symbol, name?, address?, networkId?, price, change, volume, marketCap, liquidity } or null.
 */
async function getPriceForSymbol(symbol) {
  const upperSymbol = (symbol || '').toUpperCase();
  if (!upperSymbol) return null;
  try {
    if (WELL_KNOWN_TOKENS[upperSymbol]) {
      const knownToken = WELL_KNOWN_TOKENS[upperSymbol];
      const addressQuery = `
        query GetTokenByAddress($address: String!, $networkId: Int!) {
          filterTokens(
            filters: { network: [$networkId] }
            tokens: [$address]
            limit: 1
          ) {
            results {
              token { address symbol name networkId }
              priceUSD change24 change1 change4 change12 volume24 marketCap liquidity
            }
          }
        }
      `;
      const result = await executeCodexQuery(addressQuery, {
        address: knownToken.address,
        networkId: knownToken.networkId
      });
      const tokenData = result?.filterTokens?.results?.[0];
      if (tokenData) {
        const price = parseFloat(tokenData.priceUSD) || 0;
        return {
          symbol: upperSymbol,
          name: knownToken.name,
          address: knownToken.address,
          networkId: knownToken.networkId,
          price,
          change: parseFloat(tokenData.change24) || 0,
          change24: parseFloat(tokenData.change24) || 0,
          change1h: parseFloat(tokenData.change1) || 0,
          change7d: 0, // Codex doesn't provide 7d directly, would need separate query
          change30d: 0,
          change1y: 0,
          volume: parseFloat(tokenData.volume24) || 0,
          marketCap: parseFloat(tokenData.marketCap) || 0,
          liquidity: parseFloat(tokenData.liquidity) || 0,
        };
      }
    }
    const popularNetworks = [1, 56, 137, 42161, 8453, 43114, 10, 250];
    const query = `
      query GetTokenPrice($search: String!, $networkFilter: [Int!]) {
        filterTokens(
          filters: { network: $networkFilter }
          phrase: $search
          limit: 30
          rankings: [{ attribute: liquidity, direction: DESC }]
        ) {
          results {
            token { address symbol name networkId }
            priceUSD change24 volume24 marketCap liquidity holders
          }
        }
      }
    `;
    const result = await executeCodexQuery(query, {
      search: symbol,
      networkFilter: popularNetworks
    });
    const results = result?.filterTokens?.results || [];
    const getScore = (r) => {
      let score = 0;
      const liq = parseFloat(r.liquidity) || 0, vol = parseFloat(r.volume24) || 0;
      const mcap = parseFloat(r.marketCap) || 0, holders = parseInt(r.holders) || 0;
      if (mcap > 1e12 || (mcap > 100e9 && liq < 10000)) return -1000;
      score += Math.min(liq / 10000, 100) + Math.min(vol / 5000, 50) + Math.min(holders / 100, 30);
      if (liq > 0 && mcap > 0 && (mcap / liq) > 1000) score -= 50;
      return score;
    };
    const exactMatches = results
      .filter(r => r.token?.symbol?.toUpperCase() === upperSymbol)
      .map(r => ({ ...r, score: getScore(r) }))
      .filter(r => r.score > 0)
      .sort((a, b) => b.score - a.score);
    if (exactMatches.length > 0) {
      const best = exactMatches[0];
      return {
        symbol: best.token.symbol,
        name: best.token.name,
        address: best.token.address,
        networkId: best.token.networkId,
        price: parseFloat(best.priceUSD) || 0,
        change: parseFloat(best.change24) || 0,
        change24: parseFloat(best.change24) || 0,
        change1h: parseFloat(best.change1) || 0,
        change7d: 0,
        change30d: 0,
        change1y: 0,
        volume: parseFloat(best.volume24) || 0,
        marketCap: parseFloat(best.marketCap) || 0,
        liquidity: parseFloat(best.liquidity) || 0,
      };
    }
    const cg = await fetchCoinGeckoPrice(upperSymbol);
    if (cg && cg.price > 0) {
      return {
        symbol: upperSymbol,
        name: upperSymbol,
        price: cg.price,
        change: cg.change,
        change24: cg.change || 0,
        change1h: 0,
        change7d: 0,
        change30d: 0,
        change1y: 0,
        volume: cg.volume || 0,
        marketCap: cg.marketCap || 0,
        liquidity: cg.liquidity || 0,
      };
    }
    return { symbol: upperSymbol, price: 0, change: 0, change24: 0, change1h: 0, change7d: 0, change30d: 0, change1y: 0, volume: 0, marketCap: 0, liquidity: 0 };
  } catch (err) {
    console.error(`Price lookup error for ${symbol}:`, err.message);
    const cg = await fetchCoinGeckoPrice(upperSymbol);
    if (cg && cg.price > 0) {
      return {
        symbol: upperSymbol,
        name: upperSymbol,
        price: cg.price,
        change: cg.change,
        change24: cg.change || 0,
        change1h: 0,
        change7d: 0,
        change30d: 0,
        change1y: 0,
        volume: cg.volume || 0,
        marketCap: cg.marketCap || 0,
        liquidity: cg.liquidity || 0,
      };
    }
    return { symbol: upperSymbol, price: 0, change: 0, change24: 0, change1h: 0, change7d: 0, change30d: 0, change1y: 0, volume: 0, marketCap: 0, liquidity: 0 };
  }
}

/**
 * ONE Codex query for every symbol the registry knows an address for.
 * `filterTokens(tokens: ["address:networkId", ...])` accepts a batch, so the
 * six native symbols the swap panel polls (ETH,SOL,BNB,POL,MATIC,ARB) cost one
 * query per cache window instead of six. Measured 2026-09-11: the per-symbol
 * fan-out was the largest single Codex op on the dev key (~4K/day, most of it
 * this route on a 60s cache behind a 30s client poll). Returns a map keyed by
 * UPPER symbol; symbols the batch did not return fall through to the caller's
 * per-symbol path. In-flight deduped so concurrent cache misses share one query.
 */
// POL is MATIC after the 1:1 migration - same asset, same price. The registry
// only carries MATIC, and without this alias POL paid a phrase search
// (GetTokenPrice) every cache window and usually came back empty.
const _PRICE_SYMBOL_ALIAS = { POL: 'MATIC' };
const _knownPricesInflight = new Map();
async function getPricesForKnownSymbols(upperSymbols) {
  const known = upperSymbols.filter(s => WELL_KNOWN_TOKENS[_PRICE_SYMBOL_ALIAS[s] || s]);
  if (known.length === 0) return {};
  const key = known.slice().sort().join(',');
  if (_knownPricesInflight.has(key)) return _knownPricesInflight.get(key);
  const run = (async () => {
    const entryOf = (s) => WELL_KNOWN_TOKENS[_PRICE_SYMBOL_ALIAS[s] || s];
    const ids = [...new Set(known.map(s => `${entryOf(s).address}:${entryOf(s).networkId}`))];
    const query = `
      query GetKnownPrices($tokens: [String!], $limit: Int!) {
        filterTokens(tokens: $tokens, limit: $limit) {
          results {
            token { address symbol name networkId }
            priceUSD change24 change1 change4 change12 volume24 marketCap liquidity
          }
        }
      }
    `;
    const out = {};
    try {
      const result = await executeCodexQuery(query, { tokens: ids, limit: ids.length });
      const rows = result?.filterTokens?.results || [];
      const byId = new Map(rows.map(r => [`${String(r.token?.address || '').toLowerCase()}:${r.token?.networkId}`, r]));
      for (const sym of known) {
        const k = entryOf(sym);
        const r = byId.get(`${String(k.address).toLowerCase()}:${k.networkId}`);
        if (!r) continue;
        out[sym] = {
          symbol: sym,
          name: k.name,
          address: k.address,
          networkId: k.networkId,
          price: parseFloat(r.priceUSD) || 0,
          change: parseFloat(r.change24) || 0,
          change24: parseFloat(r.change24) || 0,
          change1h: parseFloat(r.change1) || 0,
          change7d: 0,
          change30d: 0,
          change1y: 0,
          volume: parseFloat(r.volume24) || 0,
          marketCap: parseFloat(r.marketCap) || 0,
          liquidity: parseFloat(r.liquidity) || 0,
        };
      }
    } catch (err) {
      console.warn('[prices] batched known-symbol query failed, falling back per symbol:', err.message);
    } finally {
      _knownPricesInflight.delete(key);
    }
    return out;
  })();
  _knownPricesInflight.set(key, run);
  return run;
}

/** Batch: GET /api/tokens/prices?symbols=BTC,ETH,SOL – real-time Codex + CoinGecko fallback */
app.get('/api/tokens/prices', async (req, res) => {
  try {
    const raw = req.query.symbols || '';
    const symbols = raw.split(',').map(s => s.trim()).filter(Boolean);
    if (symbols.length === 0) {
      return res.status(400).json({ error: 'symbols query required (e.g. symbols=BTC,ETH,SOL)' });
    }
    const cacheKey = [...symbols].sort((a, b) => a.localeCompare(b)).join(',').toUpperCase();
    const cached = getCached(cache.prices, cacheKey, CACHE_TTL_PRICES_MS);
    if (cached) {
      return res.json(cached);
    }
    const results = {};
    // One query for everything the registry can address; only the leftovers
    // (unknown symbols, or a row the batch did not return) pay a lookup each.
    const upper = symbols.map(s => s.toUpperCase());
    const batched = await getPricesForKnownSymbols(upper);
    Object.assign(results, batched);
    const leftovers = symbols.filter(s => !results[s.toUpperCase()]);
    await Promise.all(leftovers.map(async (s) => {
      const data = await getPriceForSymbol(s);
      if (data) results[data.symbol] = data;
    }));
    setCached(cache.prices, cacheKey, results, CACHE_TTL_PRICES_MS);
    res.json(results);
  } catch (e) {
    console.error('Batch prices error:', e.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/** Batch: POST /api/tokens/batch-prices - Codex getTokenPrices API (address-based, up to 25 per call) */
app.post('/api/tokens/batch-prices', async (req, res) => {
  try {
    const tokens = req.body?.tokens;
    if (!tokens?.length) {
      return res.status(400).json({ error: 'tokens array required (each: {address, networkId})' });
    }
    const CODEX_KEY = process.env.CODEX_API_KEY;
    if (!CODEX_KEY) {
      return res.status(500).json({ error: 'CODEX_API_KEY not configured' });
    }
    // Split into chunks of 25 (Codex limit)
    const chunks = [];
    for (let i = 0; i < tokens.length; i += 25) {
      chunks.push(tokens.slice(i, i + 25));
    }
    const query = `
      query GetTokenPrices($inputs: [GetPriceInput!]!) {
        getTokenPrices(inputs: $inputs) {
          address
          networkId
          priceUsd
          timestamp
        }
      }
    `;
    const allPrices = [];
    await Promise.all(chunks.map(async (chunk) => {
      try {
        const inputs = chunk.map(t => ({ address: t.address, networkId: parseInt(t.networkId) }));
        const resp = await fetch('https://graph.codex.io/graphql', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'Authorization': CODEX_KEY, 'Origin': CODEX_ORIGIN },
          body: JSON.stringify({ query, variables: { inputs } }),
        });
        const data = await resp.json();
        const prices = data?.data?.getTokenPrices || [];
        allPrices.push(...prices);
      } catch (err) {
        console.error('Batch prices chunk error:', err.message);
      }
    }));
    res.json({ prices: allPrices });
  } catch (e) {
    console.error('Batch prices error:', e.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/** Single: GET /api/tokens/price/:symbol */
