// Top gainers/losers from Binance for anomaly detection
app.get('/api/market/tickers', async (req, res) => {
  try {
    const cached = getMarketCache('tickers');
    if (cached) return res.json(cached);
    const response = await fetch('https://api.binance.com/api/v3/ticker/24hr');
    const data = await response.json();
    // Filter for USDT pairs, sort by absolute price change
    const usdtPairs = data
      .filter(t => t.symbol.endsWith('USDT') && parseFloat(t.quoteVolume) > 1000000)
      .map(t => ({
        symbol: t.symbol.replace('USDT', ''),
        price: parseFloat(t.lastPrice),
        change: parseFloat(t.priceChangePercent),
        volume: parseFloat(t.quoteVolume),
        high: parseFloat(t.highPrice),
        low: parseFloat(t.lowPrice),
      }))
      .sort((a, b) => Math.abs(b.change) - Math.abs(a.change));
    // Always include BTC/ETH/SOL for scenario agent pricing
    const majorCoins = {};
    ['BTC', 'ETH', 'SOL'].forEach(sym => {
      const t = usdtPairs.find(p => p.symbol === sym);
      if (t) majorCoins[sym.toLowerCase()] = t;
    });
    const result = {
      topGainers: usdtPairs.filter(t => t.change > 0).slice(0, 10),
      topLosers: usdtPairs.filter(t => t.change < 0).slice(0, 10),
      majorCoins,
      totalPairs: usdtPairs.length,
    };
    setMarketCache('tickers', result);
    res.json(result);
  } catch (err) {
    console.error('Tickers error:', err.message);
    res.json(getMarketCache('tickers') || { topGainers: [], topLosers: [], totalPairs: 0 });
  }
});

// AI Analyse — funding, liquidations, whale flow, regime.
// Primary: authoritative upstream at appresearchbeta-.../dashboard_ai_market
// (replaces the dead charts service). Fallback: compute locally from Binance
// Futures (funding rates + net taker-buy proxy) and the WS liquidation buffer.
// AI_ANALYSE_UPSTREAM (dashboard_ai_market) — Cloud Run host dead; constant retained as marker.
const AI_ANALYSE_UPSTREAM = '';
app.get('/api/market/ai-analyse', async (req, res) => {
  try {
    const cached = getMarketCache('aiAnalyse');
    if (cached) return res.json(cached);

    try {
      const upstream = await fetch(AI_ANALYSE_UPSTREAM, { signal: AbortSignal.timeout(10000) });
      if (upstream.ok) {
        const data = await upstream.json();
        const result = {
          fundingAvgPct: data.funding_avg_pct ?? 0,
          liquidations: {
            long: data.liquidations_usd?.long ?? 0,
            short: data.liquidations_usd?.short ?? 0,
            total: data.liquidations_usd?.total ?? 0,
          },
          whaleFlowUsd: data.whale_flow_usd?.total ?? 0,
          regime: data.regime ?? 'NEUTRAL',
          state: data.state ?? 'Unknown',
          change24h: data.change_24h_pct ?? {},
          asText: data.as_text ?? {},
          windowMinutes: data.window_minutes ?? 60,
          ts: data.ts_ms ?? Date.now(),
        };
        await enrichAiAnalyse(result);
        setMarketCache('aiAnalyse', result);
        return res.json(result);
      }
      console.error('AI Analyse upstream HTTP', upstream.status);
    } catch (err) {
      console.error('AI Analyse upstream error:', err.message);
    }

    // Fallback path — upstream unreachable.
    const [fundingRaw, klinesRaw] = await Promise.all([
      Promise.all([
        fetch('https://fapi.binance.com/fapi/v1/fundingRate?symbol=BTCUSDT&limit=1', { signal: AbortSignal.timeout(6000) }).then(r => r.ok ? r.json() : null).catch(() => null),
        fetch('https://fapi.binance.com/fapi/v1/fundingRate?symbol=ETHUSDT&limit=1', { signal: AbortSignal.timeout(6000) }).then(r => r.ok ? r.json() : null).catch(() => null),
      ]),
      Promise.all(['BTCUSDT', 'ETHUSDT', 'SOLUSDT'].map(sym =>
        fetch(`https://fapi.binance.com/fapi/v1/klines?symbol=${sym}&interval=1h&limit=24`, { signal: AbortSignal.timeout(6000) })
          .then(r => r.ok ? r.json() : null).catch(() => null)
      )),
    ]);
    const btcFr = Array.isArray(fundingRaw[0]) && fundingRaw[0][0] ? parseFloat(fundingRaw[0][0].fundingRate) : 0;
    const ethFr = Array.isArray(fundingRaw[1]) && fundingRaw[1][0] ? parseFloat(fundingRaw[1][0].fundingRate) : 0;
    const fundingAvgPct = ((btcFr + ethFr) / 2) * 100;
    let whaleFlowUsd = 0;
    for (const rows of klinesRaw) {
      if (!Array.isArray(rows)) continue;
      for (const row of rows) {
        whaleFlowUsd += 2 * (parseFloat(row[10]) || 0) - (parseFloat(row[7]) || 0);
      }
    }
    pruneLiqEvents();
    const liq24 = aggregateLiquidations(24 * 60 * 60 * 1000);
    const result = {
      fundingAvgPct,
      liquidations: { long: liq24.long, short: liq24.short, total: liq24.total },
      whaleFlowUsd,
      regime: 'NEUTRAL',
      state: 'Degraded',
      change24h: {},
      asText: {},
      windowMinutes: 1440,
      ts: Date.now(),
    };
    await enrichAiAnalyse(result);
    setMarketCache('aiAnalyse', result);
    res.json(result);
  } catch (err) {
    console.error('AI Analyse fatal error:', err.message);
    const stale = getMarketCache('aiAnalyse');
    if (stale) return res.json(stale);
    res.json({ fundingAvgPct: 0, liquidations: { long: 0, short: 0, total: 0 }, whaleFlowUsd: 0, regime: 'NEUTRAL', state: 'Unknown', change24h: {}, asText: {} });
  }
});

// Backfill /api/market/ai-analyse with the fields its consumers read but the
// upstream never carries (2026-07-02): `openInterest` (the Liquidation Heatmap
// header read it and ALWAYS got undefined -> $0 OI) and zero liquidation
// windows (the local WS aggregator starts empty after every restart). Both
// come from our own Spectre data-api aggregates; failures leave the result
// untouched.
async function enrichAiAnalyse(result) {
  try {
    if (!result.openInterest) result.openInterest = await spectreTotalOiUsd();
  } catch (_) { /* leave unset - consumers guard */ }
  try {
    if (!result.liquidations?.total) {
      const w = await spectreLiqWindow('24h');
      result.liquidations = { long: w.long, short: w.short, total: w.total };
    }
  } catch (_) { /* keep whatever the primary produced */ }
}

// ═══════════════════════════════════════════════════════════════════════════════
// REAL-TIME LIQUIDATION AGGREGATOR — Binance Futures WebSocket + REST fallback
// Maintains rolling 1h/4h/12h/24h liquidation windows like Coinglass
// ═══════════════════════════════════════════════════════════════════════════════

const LiqWs = require('ws'); // local ref - the global `WebSocket` const is declared later for app WS server
const liquidationEvents = []; // Array of { time, symbol, side, qty, price, usdValue }
const LIQ_MAX_AGE = 24 * 60 * 60 * 1000; // 24 hours
let liqWs = null;
let liqWsRetries = 0;
let liqWsConnected = false;
let liqLastPollTs = 0;

// Prune events older than 24h
function pruneLiqEvents() {
  const cutoff = Date.now() - LIQ_MAX_AGE;
  while (liquidationEvents.length > 0 && liquidationEvents[0].time < cutoff) {
    liquidationEvents.shift();
  }
}

// Aggregate liquidation data for a given time window (in ms)
function aggregateLiquidations(windowMs) {
  const cutoff = Date.now() - windowMs;
  const events = liquidationEvents.filter(e => e.time >= cutoff);
  let totalLong = 0, totalShort = 0;
  const bySymbol = {};

  for (const e of events) {
    const usd = e.usdValue;
    if (e.side === 'SELL') {
      // SELL side liquidation = long position liquidated
      totalLong += usd;
    } else {
      // BUY side liquidation = short position liquidated
      totalShort += usd;
    }
    if (!bySymbol[e.symbol]) bySymbol[e.symbol] = { long: 0, short: 0, count: 0 };
    if (e.side === 'SELL') bySymbol[e.symbol].long += usd;
    else bySymbol[e.symbol].short += usd;
    bySymbol[e.symbol].count++;
  }

  return {
    long: totalLong,
    short: totalShort,
    total: totalLong + totalShort,
    count: events.length,
    bySymbol,
  };
}

// Connect to Binance Futures all-market liquidation stream
function connectLiquidationWs() {
  if (liqWs) {
    try { liqWs.close(); } catch (_) {}
  }

  const wsUrl = 'wss://fstream.binance.com/ws/!forceOrder@arr';
  liqWs = new LiqWs(wsUrl);

  liqWs.on('open', () => {
    liqWsConnected = true;
    liqWsRetries = 0;
    console.log('[Liquidations] WebSocket connected to Binance Futures');
  });

  liqWs.on('message', (raw) => {
    try {
      const msg = JSON.parse(raw);
      // Binance sends { e: 'forceOrder', E: timestamp, o: { s, S, o, f, q, p, ap, X, l, T, ... } }
      const o = msg.o;
      if (!o) return;
      const symbol = (o.s || '').replace('USDT', '');
      const side = o.S; // BUY or SELL
      const qty = parseFloat(o.q) || 0;
      const avgPrice = parseFloat(o.ap) || parseFloat(o.p) || 0;
      const usdValue = qty * avgPrice;
      if (usdValue < 1) return; // skip dust

      liquidationEvents.push({
        time: o.T || Date.now(),
        symbol,
        side,
        qty,
        price: avgPrice,
        usdValue,
      });

      // Prune every ~1000 events to keep memory bounded
      if (liquidationEvents.length % 1000 === 0) pruneLiqEvents();
    } catch (_) {}
  });

  liqWs.on('error', (err) => {
    console.error('[Liquidations] WebSocket error:', err.message);
    liqWsConnected = false;
  });

  liqWs.on('close', () => {
    liqWsConnected = false;
    // Exponential backoff reconnect: 2s, 4s, 8s, 16s, max 60s
    const delay = Math.min(2000 * Math.pow(2, liqWsRetries), 60000);
    liqWsRetries++;
    console.log(`[Liquidations] WebSocket closed, reconnecting in ${delay / 1000}s...`);
    setTimeout(connectLiquidationWs, delay);
  });
}

// REST fallback: poll Binance forceOrders when WebSocket is down
// Uses the public allForceOrders endpoint (no auth needed for recent data)
async function pollLiquidationsFallback() {
  if (liqWsConnected) return; // WebSocket is working, skip polling
  const now = Date.now();
  if (now - liqLastPollTs < 15000) return; // Max once per 15s
  liqLastPollTs = now;

  try {
    // Fetch recent liquidations from top symbols
    const symbols = ['BTCUSDT', 'ETHUSDT', 'SOLUSDT', 'BNBUSDT', 'XRPUSDT', 'DOGEUSDT',
      'ADAUSDT', 'AVAXUSDT', 'LINKUSDT', 'DOTUSDT', 'ARBUSDT', 'OPUSDT', 'SUIUSDT', 'NEARUSDT', 'PEPEUSDT'];
    const results = await Promise.allSettled(
      symbols.map(sym =>
        fetch(`https://fapi.binance.com/fapi/v1/forceOrders?symbol=${sym}&limit=50`, {
          signal: AbortSignal.timeout(5000),
        }).then(r => r.ok ? r.json() : [])
      )
    );

    for (const r of results) {
      if (r.status !== 'fulfilled' || !Array.isArray(r.value)) continue;
      for (const order of r.value) {
        const time = order.time || order.T;
        // Skip if we already have this event (dedupe by time + symbol)
        if (liquidationEvents.some(e => e.time === time && e.symbol === (order.symbol || '').replace('USDT', ''))) continue;
        // Skip if older than 24h
        if (time < Date.now() - LIQ_MAX_AGE) continue;

        const symbol = (order.symbol || '').replace('USDT', '');
        const side = order.side || order.S;
        const qty = parseFloat(order.origQty || order.q) || 0;
        const avgPrice = parseFloat(order.averagePrice || order.ap || order.price || order.p) || 0;
        const usdValue = qty * avgPrice;
        if (usdValue < 1) continue;

        liquidationEvents.push({ time, symbol, side, qty, price: avgPrice, usdValue });
      }
    }

    // Sort by time and prune
    liquidationEvents.sort((a, b) => a.time - b.time);
    pruneLiqEvents();
  } catch (err) {
    console.error('[Liquidations] REST fallback error:', err.message);
  }
}

// Seed historical liquidation data on startup from Binance REST API
// Fetches recent forceOrders for top symbols so the 24h window isn't empty
const liqStartTime = Date.now();
async function seedHistoricalLiquidations() {
  const symbols = [
    'BTCUSDT', 'ETHUSDT', 'SOLUSDT', 'BNBUSDT', 'XRPUSDT', 'DOGEUSDT',
    'ADAUSDT', 'AVAXUSDT', 'LINKUSDT', 'DOTUSDT', 'ARBUSDT', 'OPUSDT',
    'SUIUSDT', 'NEARUSDT', '1000PEPEUSDT', 'WIFUSDT', 'AAVEUSDT',
    'APTUSDT', 'INJUSDT', 'FILUSDT', 'LTCUSDT', 'ATOMUSDT',
    'MATICUSDT', 'TRXUSDT', 'TONUSDT', 'SHIBUSDT', 'FETUSDT',
    'RNDRUSDT', 'TAOUSDT', 'MKRUSDT',
  ];
  let seeded = 0;
  // Batch 5 at a time to avoid hammering Binance
  for (let i = 0; i < symbols.length; i += 5) {
    const batch = symbols.slice(i, i + 5);
    const results = await Promise.allSettled(
      batch.map(sym =>
        fetch(`https://fapi.binance.com/fapi/v1/forceOrders?symbol=${sym}&limit=100`, {
          signal: AbortSignal.timeout(8000),
        }).then(r => r.ok ? r.json() : [])
      )
    );
    for (const r of results) {
      if (r.status !== 'fulfilled' || !Array.isArray(r.value)) continue;
      for (const order of r.value) {
        const time = order.time || order.T;
        if (!time || time < Date.now() - LIQ_MAX_AGE) continue;
        const symbol = (order.symbol || '').replace('USDT', '').replace('1000', '');
        const side = order.side || order.S;
        const qty = parseFloat(order.origQty || order.q) || 0;
        const avgPrice = parseFloat(order.averagePrice || order.ap || order.price || order.p) || 0;
        const usdValue = qty * avgPrice;
        if (usdValue < 1) continue;
        liquidationEvents.push({ time, symbol, side, qty, price: avgPrice, usdValue });
        seeded++;
      }
    }
    // Small delay between batches
    if (i + 5 < symbols.length) await new Promise(r => setTimeout(r, 500));
  }
  liquidationEvents.sort((a, b) => a.time - b.time);
  pruneLiqEvents();
  console.log(`[Liquidations] Seeded ${seeded} historical events from REST API`);
}

