// REST endpoint — serves aggregated liquidation data
// The local WS aggregator has been observed sitting at connected:true /
// eventCount 0 for days - an empty buffer must fall through to the data-api
// derivatives lanes instead of serving zeros as if the market had no
// liquidations. Mirrors the serverless handleMarketLiquidations composition.
let liqDataApiCache = { ts: 0, data: null };
async function composeLiquidationsFromDataApi() {
  if (liqDataApiCache.data && Date.now() - liqDataApiCache.ts < 30_000) return liqDataApiCache.data;
  const [winRes, evRes] = await Promise.allSettled([
    fetchSpectreV1('/derivatives/liquidation-windows'),
    fetchSpectreV1('/derivatives/liquidations?limit=50'),
  ]);
  const w = winRes.status === 'fulfilled'
    ? (winRes.value?.data?.windows || winRes.value?.windows || {})
    : {};
  const rows = evRes.status === 'fulfilled' && Array.isArray(evRes.value?.data)
    ? evRes.value.data
    : [];
  if (!Object.keys(w).length && rows.length === 0) throw new Error('data-api liquidation lanes empty');
  const mk = (k) => ({
    long: Number(w[k]?.long) || 0,
    short: Number(w[k]?.short) || 0,
    total: Number(w[k]?.total) || 0,
    count: Number(w[k]?.count) || 0,
    bySymbol: {},
  });
  const recent = rows.map((r) => ({
    time: Number(r.time_unix) * 1000 || Date.parse(r.time) || Date.now(),
    symbol: String(r.asset || r.symbol || '').toUpperCase(),
    // liquidated-side vocabulary (LONG/SHORT) - the tape renderer accepts it
    side: String(r.side || '').toLowerCase() === 'short' ? 'SHORT' : 'LONG',
    qty: Number(r.quantity) || 0,
    price: Number(r.price) || 0,
    usdValue: Number(r.usd_value ?? r.usdValue) || 0,
  })).filter((e) => e.symbol && e.usdValue > 0);
  const data = {
    connected: true,
    eventCount: recent.length,
    source: 'spectre-v1-derivatives',
    windows: { '1h': mk('1h'), '4h': mk('4h'), '12h': mk('12h'), '24h': mk('24h') },
    recent,
  };
  liqDataApiCache = { ts: Date.now(), data };
  return data;
}

app.get('/api/market/liquidations', async (req, res) => {
  // Ensure we prune before responding
  pruneLiqEvents();

  if (liquidationEvents.length === 0) {
    try {
      res.setHeader('Cache-Control', 'public, max-age=5');
      return res.json(await composeLiquidationsFromDataApi());
    } catch (_) { /* fall through to the local aggregate - honest zeros */ }
  }

  const h1 = aggregateLiquidations(60 * 60 * 1000);
  const h4 = aggregateLiquidations(4 * 60 * 60 * 1000);
  const h12 = aggregateLiquidations(12 * 60 * 60 * 1000);
  const h24 = aggregateLiquidations(24 * 60 * 60 * 1000);

  // Recent events for real-time feed (last 50)
  const recent = liquidationEvents.slice(-50).reverse().map(e => ({
    time: e.time,
    symbol: e.symbol,
    side: e.side,
    qty: e.qty,
    price: e.price,
    usdValue: e.usdValue,
  }));

  res.setHeader('Cache-Control', 'public, max-age=5');
  res.json({
    // "connected" with an empty buffer was a lie the consumers acted on
    // ("Awaiting liquidation events..." forever) - flowing data or honesty
    connected: liqWsConnected && liquidationEvents.length > 0,
    eventCount: liquidationEvents.length,
    uptimeMs: Date.now() - liqStartTime,
    windows: {
      '1h': { long: h1.long, short: h1.short, total: h1.total, count: h1.count, bySymbol: h1.bySymbol },
      '4h': { long: h4.long, short: h4.short, total: h4.total, count: h4.count, bySymbol: h4.bySymbol },
      '12h': { long: h12.long, short: h12.short, total: h12.total, count: h12.count, bySymbol: h12.bySymbol },
      '24h': { long: h24.long, short: h24.short, total: h24.total, count: h24.count, bySymbol: h24.bySymbol },
    },
    recent,
  });
});

