app.get('/api/market/ai-market-text', async (req, res) => {
  const rawTf = String(req.query.timeframe || '24h').toLowerCase();
  if (!AI_MARKET_VALID_TF.includes(rawTf)) {
    return res.status(400).json({ error: `Invalid timeframe. Use one of: ${AI_MARKET_VALID_TF.join(', ')}` });
  }
  // market=stocks routes to the equities strategist agent; default is crypto.
  // Both agents return the same { analysis, macroConditions, positioning } shape.
  const rawMarket = String(req.query.market || 'crypto').toLowerCase();
  const market = AI_MARKET_VALID_MARKETS.includes(rawMarket) ? rawMarket : 'crypto';

  // Only source of truth: our own Groq-backed agents driven by LIVE Spectre data.
  // GCP fallback removed — it served stale/fabricated content that contradicted the live ticker.
  try {
    const agentData = market === 'stocks'
      ? await generateStockMarketAnalysisAgent({ timeframe: rawTf })
      : await generateMarketAnalysisAgent({ timeframe: rawTf });
    if (agentData && (agentData.analysis || agentData.macroConditions || agentData.positioning)) {
      console.log(`[ai-market-text] served ${market} ${rawTf} from ${market === 'stocks' ? 'stockMarketAnalysisAgent' : 'marketAnalysisAgent'}`);
      return res.json({
        analysis: agentData.analysis || '',
        macroConditions: agentData.macroConditions || '',
        positioning: agentData.positioning || '',
        sources: agentData.sources || [],
        timeframe: agentData.timeframe || rawTf,
        market,
        lastUpdated: agentData.lastUpdated || new Date().toISOString(),
      });
    }
    console.warn(`[ai-market-text] agent returned empty for ${market} ${rawTf} — GROQ_API_KEY missing or prompt error`);
    return res.status(503).json({ error: 'AI Market analysis unavailable', timeframe: rawTf, market });
  } catch (err) {
    console.error(`[ai-market-text] agent error for ${market} ${rawTf}:`, err.message);
    return res.status(503).json({ error: 'AI Market analysis failed', timeframe: rawTf, market });
  }
});

// Sector performance from Command Center API (cached 5 min)
const sectorCacheMap = new Map();
const SECTOR_TTL = 300000;

app.get('/api/market/sectors', async (req, res) => {
  try {
    const { order, sector_limit } = req.query;
    const params = new URLSearchParams();
    if (order) params.set('order', order);
    if (sector_limit) params.set('sector_limit', sector_limit);
    const qs = params.toString();
    const cacheKey = qs || '_default';

    const cached = sectorCacheMap.get(cacheKey);
    if (cached && Date.now() - cached.ts < SECTOR_TTL) {
      return res.json(cached.data);
    }

    // CG /coins/categories has change_24h + volume; adapt to legacy welcome/sectors shape.
    const cgKey = process.env.COINGECKO_API_KEY || '';
    const cgBase = cgKey ? 'https://pro-api.coingecko.com/api/v3' : 'https://api.coingecko.com/api/v3';
    const cgHeaders = { accept: 'application/json' };
    if (cgKey) cgHeaders['x-cg-pro-api-key'] = cgKey;
    const resp = await fetch(`${cgBase}/coins/categories`, { headers: cgHeaders, signal: AbortSignal.timeout(8000) });
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const cats = await resp.json();
    const limit = Math.min(parseInt(sector_limit, 10) || 30, cats.length);
    const sectors = cats.filter(c => c?.id && c?.name).slice(0, limit).map(c => {
      const change = Number(c.market_cap_change_24h ?? 0);
      const cap = Number(c.market_cap ?? 0);
      const lifecycle = cap > 50e9 ? 'mature' : cap > 5e9 ? 'established' : Math.abs(change) > 5 ? 'growth' : 'established';
      const performance = change >= 8 ? 'very_strong' : change >= 3 ? 'strong' : change <= -5 ? 'weak' : change <= -1 ? 'flat' : 'positive';
      return { sector_id: c.id, sector_name: c.name, change_24h: change, volume: Number(c.volume_24h ?? 0), market_cap: cap, lifecycle, performance };
    });
    const json = { sectors, cached_at: new Date().toISOString() };
    sectorCacheMap.set(cacheKey, { data: json, ts: Date.now() });
    res.json(json);
  } catch (err) {
    console.error('Sector proxy error:', err.message);
    const fallback = sectorCacheMap.get('_default');
    if (fallback) return res.json(fallback.data);
    res.status(502).json({ error: 'Sector data unavailable' });
  }
});

