// Sector snapshot — one endpoint that fans out to CoinGecko once per sector,
// merges the result, caches 5 min. Replaces N parallel client-side
// /api/coingecko/coins/markets?category=... calls that were hitting 429s.
const SECTOR_SNAPSHOT_TTL = 5 * 60 * 1000;
const DEFAULT_SNAPSHOT_CATEGORIES = [
  'meme-token',
  'layer-1',
  'decentralized-finance-defi',
  'layer-2',
  'gaming',
  'artificial-intelligence',
  'privacy-coins',
  'real-world-assets-rwa',
];
const SNAPSHOT_TOKENS_PER_SECTOR = 5;
const sectorSnapshotCache = new Map(); // key -> { payload, ts }

app.get('/api/market/sectors/snapshot', async (req, res) => {
  const requested = String(req.query.categories || '')
    .split(',')
    .map(s => s.trim())
    .filter(Boolean);
  const categories = requested.length ? requested : DEFAULT_SNAPSHOT_CATEGORIES;
  const cacheKey = categories.join(',');

  const cached = sectorSnapshotCache.get(cacheKey);
  if (cached && Date.now() - cached.ts < SECTOR_SNAPSHOT_TTL) {
    return res.json(cached.payload);
  }

  try {
    const cgKey = process.env.COINGECKO_API_KEY || '';
    const cgBase = cgKey ? 'https://pro-api.coingecko.com/api/v3' : 'https://api.coingecko.com/api/v3';
    const headers = { accept: 'application/json' };
    if (cgKey) headers['x-cg-pro-api-key'] = cgKey;

    const sectors = await Promise.all(categories.map(async slug => {
      try {
        const url = `${cgBase}/coins/markets?vs_currency=usd&category=${encodeURIComponent(slug)}&order=market_cap_desc&per_page=${SNAPSHOT_TOKENS_PER_SECTOR}&page=1&sparkline=true`;
        const r = await fetch(url, { headers, signal: AbortSignal.timeout(15000) });
        if (!r.ok) return { id: slug, tokens: [] };
        const arr = await r.json();
        if (!Array.isArray(arr)) return { id: slug, tokens: [] };
        const tokens = arr
          .map(row => {
            const prices = row?.sparkline_in_7d?.price;
            if (!Array.isArray(prices) || prices.length < 2) return null;
            return { symbol: (row.symbol || '').toUpperCase(), sparkline: prices };
          })
          .filter(Boolean);
        return { id: slug, tokens };
      } catch {
        return { id: slug, tokens: [] };
      }
    }));

    const payload = { sectors, cached_at: new Date().toISOString() };
    sectorSnapshotCache.set(cacheKey, { payload, ts: Date.now() });
    res.json(payload);
  } catch (err) {
    console.error('Sector snapshot error:', err.message);
    if (cached?.payload) return res.json(cached.payload);
    res.status(502).json({ error: 'Sector snapshot unavailable' });
  }
});

