// SPECTRE BRAIN PROXY — forwards to api.spectreai.io/v1/brain
// ═══════════════════════════════════════════════════════════════════════════════
// 2026-05-27: use SPECTRE_API_ORIGIN env (defaults to Hetzner direct origin)
// so /api/brain/* doesn't hit CF-blocked api.spectreai.io and 502.
const BRAIN_API_ORIGIN = (process.env.SPECTRE_API_ORIGIN || 'http://204.168.244.18:3850').replace(/\/+$/, '');
const BRAIN_API_BASE = `${BRAIN_API_ORIGIN}/v1/brain`;
const BRAIN_API_KEY = process.env.SPECTRE_DATA_API_KEY;

app.get('/api/brain', async (req, res) => {
  try {
    const r = await fetch(BRAIN_API_BASE, { headers: { 'X-API-Key': BRAIN_API_KEY }, signal: AbortSignal.timeout(8000) });
    if (!r.ok) throw new Error(`${r.status}`);
    res.json(await r.json());
  } catch (e) { res.status(502).json({ error: 'Brain unavailable' }); }
});

// /api/brain/* — wildcard catch-all so multi-segment paths like
// /api/brain/awareness/full and /api/brain/synthesis/wave reach upstream.
// Express's single-segment `:path` param can't match `awareness/full`.
app.get(/^\/api\/brain\/(.+)$/, async (req, res) => {
  try {
    const subPath = req.params[0];
    const qs = new URLSearchParams(req.query).toString();
    const url = `${BRAIN_API_BASE}/${subPath}${qs ? '?' + qs : ''}`;
    // awareness/full is large (~110KB) and the synthesizer takes ~1.3s — bump timeout.
    const timeout = subPath.startsWith('awareness') ? 20000 : 8000;
    const r = await fetch(url, { headers: { 'X-API-Key': BRAIN_API_KEY }, signal: AbortSignal.timeout(timeout) });
    if (!r.ok) {
      const body = await r.text().catch(() => '');
      return res.status(502).json({ error: 'Brain unavailable', upstream_status: r.status, detail: body.slice(0, 200) });
    }
    // Edge cache + SWR — awareness/full is expensive to compute upstream.
    const cacheTtl = subPath.startsWith('awareness') ? 30 : 15;
    res.setHeader('Cache-Control', `public, s-maxage=${cacheTtl}, stale-while-revalidate=${cacheTtl * 4}`);
    res.json(await r.json());
  } catch (e) {
    console.error(`[brain] /${req.params[0]} proxy error:`, e.message);
    res.status(502).json({ error: 'Brain unavailable', detail: e.message });
  }
});


// Fear & Greed Index (cached 5 min)
let fearGreedCache = { data: null, ts: 0 };
const FEAR_GREED_TTL = 300000; // 5 minutes

app.get('/api/market/fear-greed', async (req, res) => {
  try {
    if (fearGreedCache.data && Date.now() - fearGreedCache.ts < FEAR_GREED_TTL) {
      return res.json(fearGreedCache.data);
    }

    function classifyFG(value) {
      if (value <= 20) return 'Extreme Fear';
      if (value <= 40) return 'Fear';
      if (value <= 60) return 'Neutral';
      if (value <= 80) return 'Greed';
      return 'Extreme Greed';
    }

    let result = null;

    // Primary: CoinMarketCap F&G (same source as the F&G subpage)
    try {
      const now = Math.floor(Date.now() / 1000);
      const start = now - 7 * 86400;
      const cmcRes = await fetch(
        `https://api.coinmarketcap.com/data-api/v3/fear-greed/chart?start=${start}&end=${now}`,
        { signal: AbortSignal.timeout(5000) }
      );
      if (cmcRes.ok) {
        const cmcData = await cmcRes.json();
        const list = cmcData?.data?.dataList;
        if (list?.length) {
          const history = list.map(e => ({
            value: e.score,
            label: e.name || classifyFG(e.score),
            timestamp: Math.floor(new Date(e.timestamp).getTime() / 1000) || e.timestamp,
          }));
          const current = history[history.length - 1];
          const yesterday = history.length >= 2 ? history[history.length - 2] : null;
          const lastWeek = history[0] || null;
          result = { current, yesterday, lastWeek, history };
        }
      }
    } catch (cmcErr) {
      console.warn('[Fear&Greed] CMC failed, trying Alternative.me:', cmcErr.message);
    }

    // Fallback: Alternative.me
    if (!result) {
      const response = await fetch('https://api.alternative.me/fng/?limit=7', { signal: AbortSignal.timeout(5000) });
      if (!response.ok) throw new Error(`Alternative.me returned ${response.status}`);
      const json = await response.json();
      const entries = json.data || [];
      const history = entries.map(e => ({
        value: parseInt(e.value, 10),
        label: e.value_classification || classifyFG(parseInt(e.value, 10)),
        timestamp: parseInt(e.timestamp, 10),
      }));
      result = {
        current: history[0] || { value: 50, label: 'Neutral', timestamp: 0 },
        yesterday: history[1] ? { value: history[1].value, label: history[1].label } : null,
        lastWeek: history[6] ? { value: history[6].value, label: history[6].label } : null,
        history,
      };
    }

    fearGreedCache = { data: result, ts: Date.now() };
    res.setHeader('Cache-Control', 'public, s-maxage=300, stale-while-revalidate=600');
    res.json(result);
  } catch (err) {
    console.error('Fear & Greed error:', err.message);
    if (fearGreedCache.data) return res.json(fearGreedCache.data);
    res.status(502).json({ error: 'Failed to fetch Fear & Greed index' });
  }
});

// ═══════════════════════════════════════════════════════════════════════════════
// EXTERNAL CHARTS PROXY — Liquidation heatmap + candles
// 2026-05-13 rewrite: Hetzner Postgres is wedged so the Spectre derivatives
// upstream returns empty. New source = Binance Futures public OI + klines
// synthesized into a Coinglass-style 2D cluster grid. Same envelope as the
// Vercel handler at apps/research/api/_lib/handlers/charts-proxy.js so the
// frontend behaves identically in dev and prod.
// ═══════════════════════════════════════════════════════════════════════════════
const chartsProxyCache = new Map();
const CHARTS_LIQ_TTL_MS = 120_000;
const CHARTS_EXL_TTL_MS = 60_000;

function chartsCacheGet(key, ttl) {
  const e = chartsProxyCache.get(key);
  if (!e || Date.now() - e.ts > ttl) return null;
  return e.data;
}
function chartsCacheSet(key, data) {
  chartsProxyCache.set(key, { data, ts: Date.now() });
  if (chartsProxyCache.size > 200) {
    const oldest = chartsProxyCache.keys().next().value;
    chartsProxyCache.delete(oldest);
  }
}

// Dynamic ESM import — the synthesizer is shipped as an ES module so the
// Vercel serverless build can tree-shake it. Express loads it lazily here.
async function loadChartsLiqSynth() {
  return await import('../../apps/research/api/_lib/handlers/liq-heatmap-binance.js');
}

// Liquidation MAP — price-axis projection of the same cohort model (tiers +
// cumulative curves). Dev parity with /api/data-api?fn=charts-proxy&route=liq-map.
app.get('/api/charts/liq-map', async (req, res) => {
  const symbol = req.query.symbol || 'BTCUSDT';
  const interval = req.query.interval || '1d';
  const cacheKey = `liqmap-${symbol}-${interval}`;
  const cached = chartsCacheGet(cacheKey, CHARTS_LIQ_TTL_MS);
  if (cached) {
    res.setHeader('Cache-Control', 'public, max-age=30, stale-while-revalidate=120');
    return res.json(cached);
  }
  try {
    const { buildBinanceLiqMap } = await loadChartsLiqSynth();
    const payload = { success: true, data: await buildBinanceLiqMap(symbol, interval), _source: 'binance-cohort-map' };
    chartsCacheSet(cacheKey, payload);
    res.setHeader('Cache-Control', 'public, max-age=30, stale-while-revalidate=120');
    return res.json(payload);
  } catch (err) {
    console.error('[charts] liq-map error:', err.message);
    return res.json({ success: false, data: null, _error: err.message });
  }
});

app.get('/api/charts/liq-heatmap', async (req, res) => {
  const exchange = req.query.exchange || 'All';
  const symbol = req.query.symbol || 'BTCUSDT';
  const interval = req.query.interval || '1d';
  const leverage = [10, 25, 50, 100].includes(Number(req.query.leverage)) ? Number(req.query.leverage) : null;
  const cacheKey = `liq-${exchange}-${symbol}-${interval}-${leverage || 'all'}`;
  const cached = chartsCacheGet(cacheKey, CHARTS_LIQ_TTL_MS);
  if (cached) {
    res.setHeader('Cache-Control', 'public, max-age=30, stale-while-revalidate=120');
    return res.json(cached);
  }

  try {
    const { buildBinanceLiqHeatmap } = await loadChartsLiqSynth();
    const hm = await buildBinanceLiqHeatmap(symbol, interval, { exchange, leverage });
    const envelope = {
      success: true,
      code: '1',
      data: {
        liqHeatMap: {
          chartInterval: hm.timeframe,
          end: hm.timeArray.length ? hm.timeArray[hm.timeArray.length - 1] : Date.now(),
          chartTimeArray: hm.timeArray,
          priceArray: hm.priceArray,
          data: hm.grid.map(g => [g.col, g.row, g.value]),
        },
      },
      _source: hm._source,
      _stats: hm._stats,
    };
    chartsCacheSet(cacheKey, envelope);
    res.setHeader('Cache-Control', 'public, max-age=30, stale-while-revalidate=120');
    res.json(envelope);
  } catch (err) {
    console.error('[Charts Proxy] liq-heatmap error:', err.message);
    res.json({
      success: true,
      code: '1',
      data: { liqHeatMap: { chartInterval: interval, end: Date.now(), chartTimeArray: [], priceArray: [], data: [] } },
      _source: 'empty',
      _error: err.message,
    });
  }
});

