// GET /api/fear-greed/movers — Top gainers and losers
app.get('/api/fear-greed/movers', async (req, res) => {
  res.set('Cache-Control', 'public, s-maxage=300, stale-while-revalidate=600');
  try {
    const cached = getCached(cache.cmcGainersLosers, 'movers', CACHE_TTL_CMC_MOVERS_MS);
    if (cached) return res.json(cached);

    // Try CMC first
    if (CMC_API_KEY && breakers.cmc.isAvailable()) {
      try {
        const start = Date.now();
        const response = await cmcFetch(`${CMC_BASE}/v1/cryptocurrency/trending/gainers-losers?limit=5&time_period=24h`);
        if (response.ok) {
          const json = await response.json();
          breakers.cmc.recordSuccess(Date.now() - start);
          const mapCoin = c => ({
            id: c.id,
            name: c.name,
            symbol: c.symbol,
            price: c.quote?.USD?.price || 0,
            change: c.quote?.USD?.percent_change_24h || 0,
            volume: c.quote?.USD?.volume_24h || 0,
            marketCap: c.quote?.USD?.market_cap || 0,
          });
          const gainers = (json?.data?.gainers || []).slice(0, 5).map(mapCoin);
          const losers = (json?.data?.losers || []).slice(0, 5).map(mapCoin);
          if (gainers.length === 0 && losers.length === 0) {
            throw new Error('CMC returned empty gainers/losers');
          }
          const result = { gainers, losers, source: 'coinmarketcap' };
          setCached(cache.cmcGainersLosers, 'movers', result, CACHE_TTL_CMC_MOVERS_MS);
          return res.json(result);
        } else {
          throw new Error(`CMC responded ${response.status}`);
        }
      } catch (cmcErr) {
        breakers.cmc.recordFailure(cmcErr);
        console.warn('[Fear&Greed] CMC movers failed, falling back to Binance:', cmcErr.message);
      }
    }

    // Fallback: Binance 24h tickers
    const binRes = await fetch('https://api.binance.com/api/v3/ticker/24hr', { signal: AbortSignal.timeout(8000) });
    const data = await binRes.json();
    const asciiOnly = /^[A-Z0-9]+$/;
    const pairs = data
      .filter(t => t.symbol.endsWith('USDT') && parseFloat(t.quoteVolume) > 5000000 && asciiOnly.test(t.symbol.replace('USDT', '')))
      .map(t => ({
        symbol: t.symbol.replace('USDT', ''),
        name: t.symbol.replace('USDT', ''),
        price: parseFloat(t.lastPrice),
        change: parseFloat(t.priceChangePercent),
        volume: parseFloat(t.quoteVolume),
        high24h: parseFloat(t.highPrice),
        low24h: parseFloat(t.lowPrice),
        trades: parseInt(t.count, 10) || 0,
        marketCap: 0,
      }));
    const sorted = [...pairs].sort((a, b) => b.change - a.change);
    const result = {
      gainers: sorted.filter(t => t.change > 0).slice(0, 5),
      losers: sorted.filter(t => t.change < 0).sort((a, b) => a.change - b.change).slice(0, 5),
      source: 'binance',
    };
    setCached(cache.cmcGainersLosers, 'movers', result, CACHE_TTL_CMC_MOVERS_MS);
    res.json(result);
  } catch (err) {
    console.error('[Fear&Greed] movers error:', err.message);
    const stale = getCached(cache.cmcGainersLosers, 'movers', Infinity);
    if (stale) return res.json(stale);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ═══════════════════════════════════════════════════════════════════════════════
// Market dominance — current snapshot + 30d history (CG-backed).
// 2026-05-15: registered to unblock DominanceChart.jsx (home page widget).
// ═══════════════════════════════════════════════════════════════════════════════
const dominanceCache = { current: null, history: null };
const DOMINANCE_TTL_MS = 5 * 60 * 1000;

// Altcoin Season Index - CoinMarketCap's canonical gauge (same one CMC shows on
// its Altcoin Season chart). Uses CMC's PUBLIC web data-api (no pro key needed,
// same family as the F&G data-api call above). Replaces the old dominance-derived
// estimate. The index moves ~daily, so cache 10 min. Prod parity lives in the
// market-intel serverless handler (route=alt-season).
function normalizeAltSeason(data) {
  const d = data || {};
  const hv = d.historicalValues || {};
  const points = Array.isArray(d.points) ? d.points : [];
  const last = points.length ? points[points.length - 1] : null;
  const pick = (o) => (o && o.altcoinIndex != null && Number.isFinite(Number(o.altcoinIndex)) ? Math.round(Number(o.altcoinIndex)) : null);
  const index = pick(hv.now) ?? pick(last);
  return {
    index,
    value: index,
    market_cap_usd: Number(hv.now?.altcoinMarketcap ?? last?.altcoinMarketcap) || null,
    yesterday: pick(hv.yesterday),
    last_week: pick(hv.lastWeek),
    last_month: pick(hv.lastMonth),
    yearly_high: pick(hv.yearlyHigh),
    yearly_low: pick(hv.yearlyLow),
    source: 'coinmarketcap',
    generated_at: new Date().toISOString(),
  };
}
const ALT_SEASON_TTL_MS = 10 * 60 * 1000;
const altSeasonCache = { current: null };
app.get('/api/market/alt-season', async (req, res) => {
  if (altSeasonCache.current && Date.now() - altSeasonCache.current.ts < ALT_SEASON_TTL_MS) {
    return res.json(altSeasonCache.current.data);
  }
  try {
    const now = Math.floor(Date.now() / 1000);
    const start = now - 10 * 24 * 3600;
    const r = await fetch(
      `https://api.coinmarketcap.com/data-api/v3/altcoin-season/chart?start=${start}&end=${now}`,
      { headers: { Accept: 'application/json' }, signal: AbortSignal.timeout(8000) }
    );
    if (!r.ok) throw new Error(`cmc ${r.status}`);
    const j = await r.json();
    const out = normalizeAltSeason(j?.data);
    if (out.index == null) throw new Error('no altcoinIndex in payload');
    altSeasonCache.current = { data: out, ts: Date.now() };
    res.json(out);
  } catch (err) {
    console.error('[market/alt-season] error:', err.message);
    if (altSeasonCache.current) return res.json({ ...altSeasonCache.current.data, stale: true });
    res.status(200).json({ index: null, value: null, degraded: true, error: err.message });
  }
});

// /api/market/dominance (Express) was deleted 2026-08-18: zero frontend
// consumers (the app reads /data-api/v1/market/dominance via spectreMarketApi)
// and the prod catch-all 400s on it — proven dead. dominance-history stays.

app.get('/api/market/dominance-history', async (req, res) => {
  const days = Math.min(Math.max(parseInt(req.query.days, 10) || 30, 1), 365);
  const cacheKey = `hist:${days}`;
  if (dominanceCache.history && dominanceCache.history.key === cacheKey && Date.now() - dominanceCache.history.ts < DOMINANCE_TTL_MS) {
    return res.json(dominanceCache.history.data);
  }
  try {
    const opts = { headers: {}, signal: AbortSignal.timeout(15000) };
    if (COINGECKO_API_KEY) opts.headers[COINGECKO_HEADER_KEY] = COINGECKO_API_KEY;
    const [btcRes, ethRes, totalRes] = await Promise.all([
      fetch(`${COINGECKO_BASE}/coins/bitcoin/market_chart?vs_currency=usd&days=${days}&interval=daily`, opts),
      fetch(`${COINGECKO_BASE}/coins/ethereum/market_chart?vs_currency=usd&days=${days}&interval=daily`, opts),
      fetch(`${COINGECKO_BASE}/global/market_cap_chart?days=${days}`, opts),
    ]);
    if (!btcRes.ok || !ethRes.ok || !totalRes.ok) throw new Error('cg market chart failed');
    const [btc, eth, total] = await Promise.all([btcRes.json(), ethRes.json(), totalRes.json()]);
    const totalSeries = total?.market_cap_chart?.market_cap || total?.market_caps || [];
    const btcMcap = btc?.market_caps || [];
    const ethMcap = eth?.market_caps || [];
    const totalByDay = new Map(totalSeries.map(([t, v]) => [Math.floor(t / 86400000), v]));
    const ethByDay = new Map(ethMcap.map(([t, v]) => [Math.floor(t / 86400000), v]));
    const series = [];
    btcMcap.forEach(([ts, b]) => {
      const day = Math.floor(ts / 86400000);
      const t = totalByDay.get(day);
      if (!t) return;
      const e = ethByDay.get(day) || 0;
      const btcPct = (b / t) * 100;
      const ethPct = (e / t) * 100;
      series.push({ ts, btc: +btcPct.toFixed(2), eth: +ethPct.toFixed(2), others: +(100 - btcPct - ethPct).toFixed(2) });
    });
    const out = { days, series, source: 'coingecko', generated_at: new Date().toISOString() };
    dominanceCache.history = { data: out, key: cacheKey, ts: Date.now() };
    res.json(out);
  } catch (err) {
    console.error('[market/dominance-history] error:', err.message);
    if (dominanceCache.history?.data) return res.json({ ...dominanceCache.history.data, stale: true });
    res.status(200).json({ days, series: [], degraded: true, error: err.message });
  }
});

