// Token fundamentals (GET) — CG /coins/{id} profile, no LLM dependency.
// 2026-05-15: GET sibling to the existing POST /api/token/fundamentals.
// Returns price, supply, ATH/ATL, community, dev stats. Pure CG, 5min cache.
// ═══════════════════════════════════════════════════════════════════════════════
const fundamentalsGetCache = new Map();
const FUNDAMENTALS_GET_TTL_MS = 5 * 60 * 1000;
app.get('/api/token/fundamentals', async (req, res) => {
  const cgId = String(req.query.id || req.query.cgId || req.query.cg_id || '').trim().toLowerCase();
  if (!cgId || !/^[a-z0-9-]{1,80}$/.test(cgId)) {
    return res.status(400).json({ error: 'id parameter required (CoinGecko id)' });
  }
  const cached = fundamentalsGetCache.get(cgId);
  if (cached && Date.now() - cached.ts < FUNDAMENTALS_GET_TTL_MS) return res.json(cached.data);
  try {
    const opts = { headers: {}, signal: AbortSignal.timeout(10000) };
    if (COINGECKO_API_KEY) opts.headers[COINGECKO_HEADER_KEY] = COINGECKO_API_KEY;
    const r = await fetch(`${COINGECKO_BASE}/coins/${cgId}?localization=false&tickers=false&community_data=true&developer_data=true&sparkline=false`, opts);
    if (!r.ok) throw new Error(`cg ${r.status}`);
    const c = await r.json();
    const m = c.market_data || {};
    const out = {
      id: c.id,
      symbol: c.symbol,
      name: c.name,
      image: c.image?.small || c.image?.thumb || null,
      market_cap_rank: c.market_cap_rank,
      categories: c.categories || [],
      description: c.description?.en?.split('. ').slice(0, 3).join('. ') || null,
      links: {
        homepage: c.links?.homepage?.[0] || null,
        twitter: c.links?.twitter_screen_name ? `https://x.com/${c.links.twitter_screen_name}` : null,
        github: c.links?.repos_url?.github?.[0] || null,
      },
      price: {
        usd: m.current_price?.usd || 0,
        change_24h_pct: m.price_change_percentage_24h || 0,
        change_7d_pct: m.price_change_percentage_7d || 0,
        change_30d_pct: m.price_change_percentage_30d || 0,
        change_1y_pct: m.price_change_percentage_1y || 0,
        ath: m.ath?.usd || 0,
        ath_change_pct: m.ath_change_percentage?.usd || 0,
        atl: m.atl?.usd || 0,
        atl_change_pct: m.atl_change_percentage?.usd || 0,
      },
      supply: {
        circulating: m.circulating_supply || 0,
        total: m.total_supply || 0,
        max: m.max_supply || 0,
        fully_diluted_valuation_usd: m.fully_diluted_valuation?.usd || 0,
      },
      market: {
        market_cap_usd: m.market_cap?.usd || 0,
        volume_24h_usd: m.total_volume?.usd || 0,
        volume_to_mcap: (m.market_cap?.usd && m.total_volume?.usd) ? +(m.total_volume.usd / m.market_cap.usd).toFixed(4) : 0,
      },
      community: c.community_data || null,
      developer: c.developer_data || null,
      genesis_date: c.genesis_date || null,
      hashing_algorithm: c.hashing_algorithm || null,
      source: 'coingecko',
      generated_at: new Date().toISOString(),
    };
    fundamentalsGetCache.set(cgId, { data: out, ts: Date.now() });
    res.json(out);
  } catch (err) {
    console.error('[token/fundamentals GET] error:', err.message);
    if (cached) return res.json({ ...cached.data, stale: true });
    res.status(200).json({ id: cgId, degraded: true, error: err.message });
  }
});

