// GET /api/cmc/listings — Top cryptocurrencies by market cap
app.get('/api/cmc/listings', async (req, res) => {
  try {
    const limit = Math.min(Math.max(parseInt(req.query.limit, 10) || 200, 1), 5000);
    const start = Math.max(parseInt(req.query.start, 10) || 1, 1);
    const category = req.query.category || '';
    const cacheKey = `listings_${start}_${limit}_${category}`;

    const cached = getCached(cache.cmcListings, cacheKey, CACHE_TTL_CMC_LISTINGS_MS);
    if (cached) {
      res.set('Cache-Control', 'public, s-maxage=300');
      return res.json(cached);
    }

    if (!CMC_API_KEY) {
      return res.status(503).json({ error: 'CMC API key not configured', data: [], total: 0, source: 'none' });
    }

    if (!breakers.cmc.isAvailable()) {
      return res.status(503).json({ error: 'CMC circuit breaker open', data: [], total: 0, source: 'none' });
    }

    const params = new URLSearchParams({ start: String(start), limit: String(limit), convert: 'USD' });
    if (category) params.set('category', category);
    const startTs = Date.now();
    const response = await cmcFetch(`${CMC_BASE}/v1/cryptocurrency/listings/latest?${params}`);

    if (!response.ok) {
      breakers.cmc.recordFailure(new Error(`CMC responded ${response.status}`));
      return res.status(502).json({ error: `CMC responded ${response.status}`, data: [], total: 0, source: 'none' });
    }

    const json = await response.json();
    breakers.cmc.recordSuccess(Date.now() - startTs);

    const coins = (json?.data || []).map(c => ({
      id: c.id,
      name: c.name,
      symbol: c.symbol,
      slug: c.slug,
      cmc_rank: c.cmc_rank,
      logo: `https://s2.coinmarketcap.com/static/img/coins/64x64/${c.id}.png`,
      price: c.quote?.USD?.price || 0,
      percent_change_1h: c.quote?.USD?.percent_change_1h || 0,
      percent_change_24h: c.quote?.USD?.percent_change_24h || 0,
      percent_change_7d: c.quote?.USD?.percent_change_7d || 0,
      percent_change_30d: c.quote?.USD?.percent_change_30d || 0,
      market_cap: c.quote?.USD?.market_cap || 0,
      volume_24h: c.quote?.USD?.volume_24h || 0,
    }));

    const result = { data: coins, total: json?.status?.total_count || coins.length, source: 'cmc' };
    setCached(cache.cmcListings, cacheKey, result, CACHE_TTL_CMC_LISTINGS_MS);
    res.set('Cache-Control', 'public, s-maxage=300');
    res.json(result);
  } catch (err) {
    console.error('[CMC] listings error:', err.message);
    res.status(500).json({ error: 'Internal server error', data: [], total: 0, source: 'none' });
  }
});

