// ═══════════════════════════════════════════════════════════════════════════════
// PHASE S3: MARKET HOURS + STATUS AWARENESS
// ═══════════════════════════════════════════════════════════════════════════════

function computeMarketStatus() {
  const now = new Date();
  // Extract ET time components reliably using Intl.DateTimeFormat
  const etFormatter = new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/New_York',
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
    hour12: false, weekday: 'short',
  });
  const parts = {};
  for (const { type, value } of etFormatter.formatToParts(now)) {
    parts[type] = value;
  }
  const day = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].indexOf(parts.weekday);
  const hours = parseInt(parts.hour === '24' ? '0' : parts.hour);
  const minutes = parseInt(parts.minute);
  const timeNum = hours * 100 + minutes;
  const todayStr = `${parts.year}-${parts.month}-${parts.day}`;
  const currentTimeET = `${parts.month}/${parts.day}/${parts.year}, ${parts.hour}:${parts.minute}:${parts.second}`;

  // US market holidays 2025-2026
  const holidays = [
    '2025-01-01', '2025-01-20', '2025-02-17', '2025-04-18',
    '2025-05-26', '2025-06-19', '2025-07-04', '2025-09-01',
    '2025-11-27', '2025-12-25',
    '2026-01-01', '2026-01-19', '2026-02-16', '2026-04-03',
    '2026-05-25', '2026-06-19', '2026-07-03', '2026-09-07',
    '2026-11-26', '2026-12-25',
  ];
  const isHoliday = holidays.includes(todayStr);

  let status, label, nextEvent, nextEventTime;

  // Helper: build an approximate ET timestamp string for "next event" display
  // We use the todayStr (YYYY-MM-DD) which is already in ET
  function etTime(h, m) { return `${todayStr}T${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:00`; }

  if (day === 0 || day === 6 || isHoliday) {
    status = 'CLOSED';
    label = isHoliday ? 'Holiday' : 'Weekend';
    nextEvent = 'Market opens';
    // Rough next open — just informational
    const daysUntilMon = day === 0 ? 1 : day === 6 ? 2 : 1;
    const nextDate = new Date(now.getTime() + daysUntilMon * 86400000);
    const ndFmt = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/New_York', year: 'numeric', month: '2-digit', day: '2-digit' });
    nextEventTime = `${ndFmt.format(nextDate)}T09:30:00`;
  } else if (timeNum < 400) {
    status = 'CLOSED';
    label = 'Overnight';
    nextEvent = 'Pre-market opens';
    nextEventTime = etTime(4, 0);
  } else if (timeNum >= 400 && timeNum < 930) {
    status = 'PRE_MARKET';
    label = 'Pre-Market';
    nextEvent = 'Market opens';
    nextEventTime = etTime(9, 30);
  } else if (timeNum >= 930 && timeNum < 1600) {
    status = 'OPEN';
    label = 'Market Open';
    nextEvent = 'Market closes';
    nextEventTime = etTime(16, 0);
  } else if (timeNum >= 1600 && timeNum < 2000) {
    status = 'AFTER_HOURS';
    label = 'After Hours';
    nextEvent = 'After-hours ends';
    nextEventTime = etTime(20, 0);
  } else {
    status = 'CLOSED';
    label = 'Closed';
    nextEvent = 'Pre-market opens';
    const nextDate = new Date(now.getTime() + 86400000);
    const ndFmt = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/New_York', year: 'numeric', month: '2-digit', day: '2-digit' });
    nextEventTime = `${ndFmt.format(nextDate)}T04:00:00`;
  }

  return { status, label, nextEvent, nextEventTime, currentTimeET, isHoliday };
}

// Next-earnings for a batch of tickers (dev twin of api/stocks.js handleEarnings).
// Default set = the curated index-moving mega-caps; ?symbols= overrides. Returns
// date + Street EPS/revenue estimates from Yahoo calendarEvents (via
// fetchStockFundamentals), sorted soonest-first. Countdown is computed client-side.
const EARNINGS_WATCHLIST = ['NVDA', 'AAPL', 'MSFT', 'AMZN', 'GOOGL', 'AVGO', 'META', 'TSLA', 'MU', 'AMD', 'INTC', 'SPCX'];
const EARNINGS_NAMES = {
  NVDA: 'NVIDIA', AAPL: 'Apple', MSFT: 'Microsoft', AMZN: 'Amazon', GOOGL: 'Alphabet',
  AVGO: 'Broadcom', META: 'Meta Platforms', TSLA: 'Tesla', MU: 'Micron Technology',
  AMD: 'Advanced Micro Devices', INTC: 'Intel', SPCX: 'SpaceX',
};
app.get('/api/stocks/earnings', async (req, res) => {
  try {
    const raw = String(req.query.symbols || '').split(',').map(s => s.trim().toUpperCase()).filter(Boolean);
    const symbols = (raw.length ? raw : EARNINGS_WATCHLIST).slice(0, 30);

    const cacheKey = `earnings_batch_${symbols.join(',')}`;
    const cached = getCached(cache.stockFundamentals, cacheKey, CACHE_TTL_STOCK_FUNDAMENTALS_MS);
    if (cached) return res.json(cached);

    const rows = await Promise.all(symbols.map(async (symbol) => {
      try {
        const fund = await fetchStockFundamentals(symbol);
        if (!fund?.earningsDate) return null;
        return {
          symbol,
          name: EARNINGS_NAMES[symbol] || symbol,
          earningsDate: fund.earningsDate,
          earningsDateEnd: null,
          epsEstimate: fund.earningsAvg ?? null,
          revenueEstimate: fund.revenueAvg ?? null,
          isEstimate: false,
        };
      } catch { return null; }
    }));

    const earnings = rows.filter(Boolean)
      .sort((a, b) => new Date(a.earningsDate).getTime() - new Date(b.earningsDate).getTime());
    const result = { earnings, count: earnings.length, updatedAt: new Date().toISOString() };
    setCached(cache.stockFundamentals, cacheKey, result);
    res.json(result);
  } catch (err) {
    console.error('[stocks/earnings]', err.message);
    res.status(502).json({ earnings: [], error: 'Failed to fetch earnings' });
  }
});

app.get('/api/stocks/market-status', async (req, res) => {
  try {
    const cached = getCached(cache.marketStatus, 'us', CACHE_TTL_MARKET_STATUS_MS);
    if (cached) return res.json(cached);

    const marketInfo = computeMarketStatus();

    // VIX as fear indicator
    let vix = null;
    try {
      const vixData = await fetchYahooChartPrice('^VIX');
      if (vixData && vixData.price) {
        vix = {
          value: vixData.price,
          change: vixData.change,
          label: vixData.price < 15 ? 'Low Volatility' :
                 vixData.price < 20 ? 'Normal' :
                 vixData.price < 30 ? 'Elevated' :
                 vixData.price < 40 ? 'High Fear' : 'Extreme Fear',
        };
      }
    } catch (e) { /* VIX is optional */ }

    const result = { ...marketInfo, vix, updatedAt: new Date().toISOString() };
    setCached(cache.marketStatus, 'us', result, CACHE_TTL_MARKET_STATUS_MS);
    res.json(result);
  } catch (err) {
    console.error('Market status error:', err.message);
    res.json({ status: 'UNKNOWN', label: 'Unknown' });
  }
});

// ═══════════════════════════════════════════════════════════════════════════════
// PHASE S4: AI STOCK ANALYSIS — Claude → OpenAI → rule-based fallback
// ═══════════════════════════════════════════════════════════════════════════════

function buildStockContext(symbol, quote, profile, analysts, news) {
  let ctx = `Stock: ${symbol}`;
  if (quote) {
    ctx += `\nPrice: $${quote.price}, Change: ${quote.change > 0 ? '+' : ''}${quote.change}%`;
    if (quote.pe) ctx += `, P/E: ${quote.pe}`;
    if (quote.week52High) ctx += `, 52w High: $${quote.week52High}, 52w Low: $${quote.week52Low}`;
    if (quote.volume) ctx += `, Volume: ${(quote.volume / 1_000_000).toFixed(1)}M`;
    if (quote.marketCap) ctx += `, Market Cap: $${(quote.marketCap / 1_000_000_000).toFixed(1)}B`;
  }
  if (profile) {
    ctx += `\nCompany: ${profile.name}, Sector: ${profile.finnhubIndustry || 'N/A'}`;
    if (profile.marketCapitalization) ctx += `, MCap: $${profile.marketCapitalization.toFixed(0)}M`;
  }
  if (analysts && analysts.length > 0) {
    const latest = analysts[0];
    ctx += `\nAnalyst Consensus (${latest.period}): ${(latest.strongBuy || 0) + (latest.buy || 0)} Buy, ${latest.hold || 0} Hold, ${(latest.sell || 0) + (latest.strongSell || 0)} Sell`;
  }
  if (news && news.length > 0) {
    ctx += `\nRecent Headlines:`;
    news.slice(0, 5).forEach(n => { ctx += `\n- ${n.headline || n.title || ''}`; });
  }
  return ctx;
}

async function generateStockAnalysisClaude(symbol, context) {
  const response = await fetch('https://api.anthropic.com/v1/messages', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-api-key': process.env.ANTHROPIC_API_KEY,
      'anthropic-version': '2023-06-01',
    },
    body: JSON.stringify({
      model: 'claude-sonnet-4-20250514',
      max_tokens: 600,
      system: 'You are Spectre AI, a concise institutional-grade equity analyst. Given stock data, produce a 3-paragraph analysis: (1) Current position & price action, (2) Fundamental thesis with key metrics, (3) Risk factors & outlook. Be opinionated but balanced. No disclaimers. No bullet points. Write like Bloomberg Intelligence, not a chatbot. Max 150 words total.',
      messages: [{ role: 'user', content: context }],
    }),
    signal: AbortSignal.timeout(15000),
  });
  if (!response.ok) throw new Error(`Claude API ${response.status}`);
  const data = await response.json();
  const text = data.content?.[0]?.text || null;
  if (!text) return null;
  return { text, source: 'claude', generatedAt: new Date().toISOString() };
}

async function generateStockAnalysisOpenAI(symbol, context) {
  const response = await fetch('https://api.openai.com/v1/chat/completions', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${process.env.OPENAI_API_KEY}`,
    },
    body: JSON.stringify({
      model: 'gpt-4o-mini',
      max_tokens: 500,
      messages: [
        { role: 'system', content: 'You are Spectre AI, a concise institutional-grade equity analyst. Given stock data, produce a 3-paragraph analysis: (1) Current position & price action, (2) Fundamental thesis with key metrics, (3) Risk factors & outlook. Be opinionated but balanced. No disclaimers. No bullet points. Write like Bloomberg Intelligence. Max 150 words.' },
        { role: 'user', content: context },
      ],
    }),
    signal: AbortSignal.timeout(15000),
  });
  if (!response.ok) throw new Error(`OpenAI API ${response.status}`);
  const data = await response.json();
  const text = data.choices?.[0]?.message?.content || null;
  if (!text) return null;
  return { text, source: 'openai', generatedAt: new Date().toISOString() };
}

function generateStockAnalysisRuleBased(symbol, quote, profile, analysts) {
  const parts = [];
  const name = profile?.name || quote?.name || symbol;
  const price = quote?.price || 0;
  const change = quote?.change || 0;
  const pe = quote?.pe || null;
  const w52h = quote?.week52High || 0;
  const w52l = quote?.week52Low || 0;

  const changeWord = change > 2 ? 'rallying' : change > 0 ? 'edging higher' : change > -2 ? 'pulling back' : 'selling off';
  const w52pos = w52h > 0 && w52h !== w52l ? ((price - w52l) / (w52h - w52l) * 100).toFixed(0) : null;
  parts.push(`${name} is ${changeWord} at $${price.toFixed(2)}, ${change > 0 ? '+' : ''}${change.toFixed(2)}% on the session.${w52pos ? ` Trading at the ${w52pos}% mark of its 52-week range ($${w52l.toFixed(2)}–$${w52h.toFixed(2)}).` : ''}`);

  if (pe) {
    const peWord = pe > 40 ? 'stretched valuation' : pe > 25 ? 'growth-priced' : pe > 15 ? 'reasonably valued' : 'value territory';
    parts.push(`At a P/E of ${pe.toFixed(1)}, ${symbol} sits in ${peWord}${profile?.finnhubIndustry ? ` within the ${profile.finnhubIndustry} sector` : ''}. ${pe > 30 ? 'Premium multiples demand continued execution on growth.' : 'The valuation leaves room for expansion if earnings momentum holds.'}`);
  }

  if (analysts && analysts.length > 0) {
    const r = analysts[0];
    const buys = (r.strongBuy || 0) + (r.buy || 0);
    const sells = (r.sell || 0) + (r.strongSell || 0);
    const total = buys + (r.hold || 0) + sells;
    if (total > 0) {
      const pctBuy = ((buys / total) * 100).toFixed(0);
      parts.push(`Wall Street consensus leans ${buys > sells ? 'bullish' : 'cautious'} with ${pctBuy}% of analysts rating ${symbol} a Buy. ${buys > sells * 3 ? 'Overwhelming conviction, though crowded positioning warrants attention.' : 'The split reflects genuine debate on the risk-reward setup here.'}`);
    }
  }

  if (parts.length === 0) {
    parts.push(`${name} at $${price.toFixed(2)}. Insufficient data for deep analysis — fundamentals and analyst coverage pending.`);
  }

  return { text: parts.join(' '), source: 'rule_based', generatedAt: new Date().toISOString() };
}

app.get('/api/stocks/ai-analysis/:symbol', async (req, res) => {
  try {
    const symbol = (req.params.symbol || '').toUpperCase();
    if (!symbol) return res.status(400).json({ error: 'Missing symbol' });

    const cacheKey = `ai_analysis_${symbol}`;
    const cached = getCached(cache.aiStockAnalysis, cacheKey, CACHE_TTL_AI_STOCK_ANALYSIS_MS);
    if (cached) return res.json(cached);

    const from3d = new Date(Date.now() - 3 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
    const today = new Date().toISOString().split('T')[0];

    const [quoteRes, profileRes, analystsRes, newsRes] = await Promise.allSettled([
      fetchYahooChartPrice(symbol),
      fetchFinnhubProfile(symbol),
      fetchFinnhubData(`/stock/recommendation?symbol=${symbol}`),
      fetchFinnhubData(`/company-news?symbol=${symbol}&from=${from3d}&to=${today}`),
    ]);

    const quote = quoteRes.status === 'fulfilled' ? quoteRes.value : null;
    const profile = profileRes.status === 'fulfilled' ? profileRes.value : null;
    const analysts = analystsRes.status === 'fulfilled' ? analystsRes.value : [];
    const news = newsRes.status === 'fulfilled' ? newsRes.value : [];

    // Enrich quote with fallback data
    if (quote) {
      const fb = FALLBACK_STOCK_DATA[symbol];
      if (fb) {
        if (!quote.pe) quote.pe = fb.pe || null;
        if (!quote.marketCap || quote.marketCap === 0) quote.marketCap = fb.marketCap || 0;
      }
    }

    const context = buildStockContext(symbol, quote, profile, Array.isArray(analysts) ? analysts : [], Array.isArray(news) ? news : []);

    let analysis = null;

    // Tier 1: Claude
    if (!analysis && process.env.ANTHROPIC_API_KEY) {
      try { analysis = await generateStockAnalysisClaude(symbol, context); }
      catch (e) { console.warn(`[AI Stock] Claude failed for ${symbol}:`, e.message); }
    }

    // Tier 2: OpenAI
    if (!analysis && process.env.OPENAI_API_KEY) {
      try { analysis = await generateStockAnalysisOpenAI(symbol, context); }
      catch (e) { console.warn(`[AI Stock] OpenAI failed for ${symbol}:`, e.message); }
    }

    // Tier 3: Rule-based
    if (!analysis) {
      analysis = generateStockAnalysisRuleBased(symbol, quote, profile, Array.isArray(analysts) ? analysts : []);
    }

    const result = {
      symbol,
      name: profile?.name || quote?.name || FALLBACK_STOCK_DATA[symbol]?.name || symbol,
      analysis,
      dataUsed: {
        hasQuote: !!quote,
        hasProfile: !!profile,
        hasAnalysts: Array.isArray(analysts) && analysts.length > 0,
        newsCount: Array.isArray(news) ? news.length : 0,
      },
      cachedAt: new Date().toISOString(),
    };

    setCached(cache.aiStockAnalysis, cacheKey, result, CACHE_TTL_AI_STOCK_ANALYSIS_MS);
    res.json(result);
  } catch (err) {
    console.error('AI stock analysis error:', err.message);
    res.json({ symbol: req.params.symbol?.toUpperCase(), analysis: null, error: err.message });
  }
});

