function isStockSymbol(symbol) {
  return POPULAR_STOCK_SYMBOLS.includes(symbol) || !!FALLBACK_STOCK_DATA[symbol];
}

// Resolve a ticker — stock or crypto
app.get('/api/ext/resolve', async (req, res) => {
  try {
    const ticker = (req.query.ticker || '').toUpperCase();
    if (!ticker) return res.status(400).json({ error: 'Missing ticker' });

    const cacheKey = `ext_resolve_${ticker}`;
    const cached = getCached(cache.extResolve, cacheKey, CACHE_TTL_EXT_RESOLVE_MS);
    if (cached) return res.json(cached);

    // Check if it's a stock
    if (isStockSymbol(ticker)) {
      const fb = FALLBACK_STOCK_DATA[ticker];
      const domain = COMPANY_DOMAINS[ticker] || `${ticker.toLowerCase()}.com`;

      // Fetch chart price AND live fundamentals in parallel
      const [quoteRes, fundRes] = await Promise.allSettled([
        fetchYahooChartPrice(ticker),
        fetchStockFundamentals(ticker),
      ]);
      const quote = quoteRes.status === 'fulfilled' ? quoteRes.value : null;
      const fund = fundRes.status === 'fulfilled' ? fundRes.value : null;

      const result = {
        resolved: true,
        assetType: 'stock',
        stock: {
          symbol: ticker,
          name: quote?.name || fb?.name || ticker,
          sector: fb?.sector || quote?.sector || '',
          exchange: quote?.exchange || fb?.exchange || '',
          logo: `https://www.google.com/s2/favicons?domain=${domain}&sz=128`,
        },
        price: quote ? {
          price: quote.price,
          change24: quote.change,
          // Use LIVE fundamentals for marketCap/PE/volume (from Yahoo quoteSummary)
          marketCap: fund?.marketCap || fb?.marketCap || 0,
          volume: fund?.volume || quote.volume || 0,
          pe: fund?.pe || fb?.pe || null,
          forwardPe: fund?.forwardPe || null,
          eps: fund?.eps || null,
          week52High: quote.week52High || null,
          week52Low: quote.week52Low || null,
          avgVolume: fund?.avgVolume || 0,
          beta: fund?.beta || null,
        } : (fb ? {
          price: fb.price,
          change24: fb.change,
          marketCap: fund?.marketCap || fb.marketCap,
          volume: fund?.volume || fb.volume,
          pe: fund?.pe || fb.pe,
          forwardPe: fund?.forwardPe || null,
          eps: fund?.eps || null,
          week52High: null,
          week52Low: null,
          avgVolume: fund?.avgVolume || 0,
          beta: fund?.beta || null,
        } : null),
        market: computeMarketStatus(),
        source: quote ? (fund?.source === 'yahoo_summary' ? 'yahoo+fundamentals' : 'yahoo') : 'fallback',
        cachedAt: new Date().toISOString(),
      };

      setCached(cache.extResolve, cacheKey, result, CACHE_TTL_EXT_RESOLVE_MS);
      return res.json(result);
    }

    // Not a stock — try crypto resolution via TOKEN_REGISTRY + Binance/CoinGecko
    const tokenInfo = getTokenInfo(ticker);
    if (tokenInfo) {
      // Known crypto token from our registry
      let price = null, change24 = null, mCap = null, vol = null, logo = null;

      // Try Binance REST for price (fastest)
      if (tokenInfo.binanceSymbol) {
        try {
          const bResp = await fetch(`https://api.binance.com/api/v3/ticker/24hr?symbol=${tokenInfo.binanceSymbol}`, {
            signal: AbortSignal.timeout(3000),
          });
          if (bResp.ok) {
            const bData = await bResp.json();
            price = parseFloat(bData.lastPrice) || null;
            change24 = parseFloat(bData.priceChangePercent) || 0;
            vol = parseFloat(bData.quoteVolume) || 0;
          }
        } catch {}
      }

      // Try CoinGecko for logo + market cap
      if (tokenInfo.coingeckoId) {
        try {
          const cgUrl = `https://api.coingecko.com/api/v3/coins/${tokenInfo.coingeckoId}?localization=false&tickers=false&community_data=false&developer_data=false`;
          const opts = { signal: AbortSignal.timeout(4000), headers: {} };
          if (COINGECKO_API_KEY) opts.headers[COINGECKO_HEADER_KEY] = COINGECKO_API_KEY;
          const cgResp = await fetch(cgUrl, opts);
          if (cgResp.ok) {
            const cgData = await cgResp.json();
            if (!price) price = cgData.market_data?.current_price?.usd || null;
            if (!change24) change24 = cgData.market_data?.price_change_percentage_24h || 0;
            mCap = cgData.market_data?.market_cap?.usd || null;
            if (!vol) vol = cgData.market_data?.total_volume?.usd || 0;
            logo = cgData.image?.small || cgData.image?.thumb || null;
          }
        } catch {}
      }

      const result = {
        resolved: true,
        assetType: 'crypto',
        token: {
          symbol: ticker,
          name: tokenInfo.name || ticker,
          address: tokenInfo.address,
          networkId: tokenInfo.networkId,
          coingeckoId: tokenInfo.coingeckoId,
        },
        price: {
          price,
          change24: change24,
          marketCap: mCap,
          volume: vol,
        },
        logo,
        source: price ? 'binance+coingecko' : 'registry',
        cachedAt: new Date().toISOString(),
      };
      setCached(cache.extResolve, cacheKey, result, CACHE_TTL_EXT_RESOLVE_MS);
      return res.json(result);
    }

    // Unknown — not a stock, not in our crypto registry
    res.json({ resolved: false, assetType: 'unknown', ticker });
  } catch (err) {
    console.error('Ext resolve error:', err.message);
    res.json({ resolved: false, error: 'resolve failed' });
  }
});

