// Persistent signal board - each token carried forward from its first PG
// timestamp with a lifecycle phase (fresh / developing / runner / ... ). Mirrors
// the prod social-proxy `momentum-signals` route so the PG board works in dev.
app.get('/api/momentum/setups/signals', async (req, res) => {
  try {
    const params = new URLSearchParams({
      timeframe: req.query.timeframe === '24h' ? '24h' : '7d',
      bucket: req.query.bucket === 'top20' ? 'top20' : 'top10',
      watch_days: String(Math.min(Math.max(parseInt(req.query.watch_days, 10) || 10, 1), 60)),
      limit: String(Math.min(Math.max(parseInt(req.query.limit, 10) || 50, 1), 100)),
    });
    const path = `/api/momentum/setups/signals?${params}`;
    const cacheKey = `setups-signals:${params.toString()}`;
    const raw = await xdashFetch(path, cache.momentum, cacheKey, CACHE_TTL_MOMENTUM_SETUPS_MS, 15000);
    // Strip phantom glitched tokens (ANSEM/the-black-bull frozen at $90.9M) so
    // they don't show as fresh signals + dupe the reconciled receipts. Mirrors
    // stripGlitchedSignals in apps/research/api/_lib/momentum-reconcile.js.
    let data = raw;
    if (raw && Array.isArray(raw.tokens)) {
      const kept = raw.tokens.filter((r) => String((r && r.token && (r.token.cg_id || r.token.symbol)) || '').toLowerCase() !== 'the-black-bull');
      if (kept.length !== raw.tokens.length) data = { ...raw, tokens: kept, count: kept.length };
    }
    res.set('Cache-Control', 'public, s-maxage=60, stale-while-revalidate=120');
    res.json(data);
  } catch (err) {
    console.error('Momentum signals error:', err.message);
    res.status(502).json({ error: 'Potential Gainers signals temporarily unavailable' });
  }
});

