// Token detail - falls back to Spectre API /v1/bubbles for basic data
app.get('/api/xdash/token/:cgId', async (req, res) => {
  try {
    let path = `/api/token/${encodeURIComponent(req.params.cgId)}`;
    const queryParts = [];
    if (req.query.author_scope) queryParts.push(`author_scope=${encodeURIComponent(req.query.author_scope)}`);
    if (req.query.author_id) queryParts.push(`author_id=${encodeURIComponent(req.query.author_id)}`);
    if (req.query.force === '1') queryParts.push('force=1');
    // 2026-05-21: forward `timeframe` (24h | 7d). Alaa's X-Dash service
    // rebuilds the carrier rollup against the chosen window — without
    // forwarding this param, the proxy always served 24h regardless of the
    // page-level toggle.
    if (req.query.timeframe) queryParts.push(`timeframe=${encodeURIComponent(req.query.timeframe)}`);
    if (req.query.page) queryParts.push(`page=${encodeURIComponent(req.query.page)}`);
    if (req.query.per_page) queryParts.push(`per_page=${encodeURIComponent(req.query.per_page)}`);
    if (queryParts.length) path += `?${queryParts.join('&')}`;

    const ttl = req.query.force === '1' ? 0 : CACHE_TTL_XDASH_TOKEN_MS;
    const cacheKey = `token:${path}`;
    const data = await xdashFetch(path, cache.xDashToken, cacheKey, ttl);
    res.json(data);
  } catch (err) {
    console.error('X Dash token error:', err.message, '- returning minimal fallback');
    // Return minimal token shape so pages don't break
    const cgId = req.params.cgId;
    res.json({
      token: {
        token: { cg_id: cgId, name: cgId, symbol: cgId.toUpperCase(), handle: cgId },
        metrics: { mentions_24h: 0, unique_authors_24h: 0, total_weighted_engagement: 0 },
      },
      authors: [],
      mentions: [],
      top_mentions: [],
      _source: 'fallback',
    });
  }
});

