// Social Market Read (thesis) — editorial "what's working / conviction /
// froth" read distilled from the social corpus. This lives on the Spectre
// Data API (Hetzner), NOT the X Dash dashboard backend, so it goes through
// spectreXBubblesFetch (Spectre key + direct Hetzner origin), mirroring the
// Vercel route=thesis branch in social-proxy.js.
app.get('/api/xdash/thesis', async (req, res) => {
  const scope = ['general', '24h', 'combined'].includes(req.query.scope) ? req.query.scope : 'combined';
  try {
    const raw = await spectreXBubblesFetch('/v1/social/thesis', `scope=${encodeURIComponent(scope)}`);
    // Data API wraps as { data: <payload>, meta, stale? }; unwrap to the bare
    // payload the panel consumes (regime / general_7d / timeframed_24h / proof).
    const data = raw && raw.data ? { ...raw.data, stale: raw.stale === true } : raw;
    res.json(data);
  } catch (err) {
    console.error('X Dash thesis error:', err.message);
    res.json({
      generated_at: new Date().toISOString(),
      reference_now: new Date().toISOString(),
      stale: true,
      _source: 'fallback',
    });
  }
});

