// ── Spectre X-Bubbles (Sunny's social heatmap + constellation) ─────────────
// Proxies to api.spectreai.io/v1/social/x-bubbles which joins social_metrics +
// assets + social_mention_snapshots into a single payload (logos, growth %,
// momentum, top tweets). Auth via SPECTRE_API_KEY env var.
async function spectreXBubblesFetch(path, params = '') {
  // Hit the direct Hetzner origin to bypass the Cloudflare WAF that blocks
  // server-to-server calls to api.spectreai.io. Order matters: SPECTRE_API_ORIGIN
  // (used by every other Spectre proxy in this file) wins, fall back to
  // api.spectreai.io only when env is missing entirely.
  const SPECTRE_API_BASE = process.env.SPECTRE_API_ORIGIN || process.env.SPECTRE_API_BASE || 'http://204.168.244.18:3850';
  const SPECTRE_API_KEY = process.env.SPECTRE_DATA_API_KEY || process.env.SPECTRE_API_KEY || '';
  const url = `${SPECTRE_API_BASE}${path}${params ? `?${params}` : ''}`;
  const res = await fetch(url, {
    headers: { Accept: 'application/json', ...(SPECTRE_API_KEY ? { 'X-API-Key': SPECTRE_API_KEY } : {}) },
    signal: AbortSignal.timeout(6000),
  });
  if (!res.ok) throw new Error(`Spectre API ${res.status}`);
  return res.json();
}

const xBubblesCache = { leaderboard: new Map(), token: new Map(), persistentPatches: new Map() };

// ───────────────────────────────────────────────────────────────────────────
// /api/x-bubbles-live — bypass the broken Spectre x-bubbles materialized
// view (which emits mentions_24h=1 sentinel for ~77% of tokens). Reads
// X-Dash bootstrap directly with pagination, normalizes to the same shape
// the X-Bubbles frontend expects.
//
// Diagnosis (2026-05-08): /v1/social/x-bubbles returns m24h=1 for 1011 of
// 1313 tokens (ONDO/$1.7B mcap is one of them). X-Dash bootstrap has the
// real numbers (ONDO=133 mentions, 272 authors). Until the upstream
// xdash-mentions-mirror worker is fixed, this route is the source of truth.
// ───────────────────────────────────────────────────────────────────────────

const X_DASH_DIRECT_URL = process.env.X_DASH_DIRECT_URL || 'http://5.78.199.87:8092';
const X_DASH_KEY = process.env.XDASH_API_TOKEN || process.env.X_DASH_API_KEY || process.env.DASHBOARD_API_KEY;

const xDashLiveCache = new Map();

async function fetchXDashBootstrapPage({ page = 1, perPage = 200, ranking = 'mentions', timeframe = '24h' } = {}) {
  const params = new URLSearchParams({
    page: String(page),
    per_page: String(perPage),
    ranking,
    timeframe,
  });
  const url = `${X_DASH_DIRECT_URL}/api/bootstrap?${params}`;
  const ctrl = new AbortController(); const t = setTimeout(() => ctrl.abort(), 10_000);
  try {
    const r = await fetch(url, {
      headers: X_DASH_KEY
        ? { 'Authorization': `Bearer ${X_DASH_KEY}`, 'X-Internal-Key': X_DASH_KEY, 'x-api-key': X_DASH_KEY, Accept: 'application/json' }
        : { Accept: 'application/json' },
      signal: ctrl.signal,
    });
    if (!r.ok) throw new Error(`bootstrap HTTP ${r.status}`);
    return await r.json();
  } finally { clearTimeout(t); }
}

function normalizeXDashToken(entry, fallbackRank) {
  // X-Dash bootstrap returns nested entries: { state, token, metrics, top_authors, ... }
  const t = entry.token || entry;
  const m = entry.metrics || t.metrics || {};
  const cgId = t.cg_id || t.coingecko_id || null;
  const sym = (t.symbol || t.cashtag_symbol || cgId || t.name || '').toString().toUpperCase().replace(/^\$/, '');
  return {
    asset: sym,
    name: t.name || t.display_name || sym,
    image: t.image_url || t.image || null,
    coingecko_id: cgId,
    rank: entry.rank_position || t.market_cap_rank || fallbackRank || null,
    categories: Array.isArray(t.categories) ? t.categories : (t.categories ? [t.categories] : []),
    price_usd: Number(t.price_usd) || null,
    market_cap_usd: Number(t.market_cap_usd) || null,
    market_cap_rank: t.market_cap_rank || null,
    volume_usd: Number(t.volume_usd_24h || t.volume_usd) || null,
    price_change_24h: Number(t.price_change_24h) || null,
    price_change_7d: Number(t.price_change_7d) || null,
    sparkline_7d: Array.isArray(t.sparkline_7d) ? t.sparkline_7d : null,
    mentions_24h: Number(m.external_mentions_24h ?? m.mentions_24h ?? 0),
    mentions_7d_avg: Number(m.external_mentions_prev_daily_avg ?? m.mentions_7d_avg ?? 0),
    mindshare_pct: Number(m.mindshare_pct ?? 0) || null,
    velocity_ratio: Number(m.velocity_ratio ?? 0) || null,
    growth_pct: Number(m.growth_pct ?? 0) || null,
    color: m.color || null,
    unique_authors: Number(m.unique_external_authors_24h ?? m.unique_authors ?? 0),
    sentiment: m.weighted_sentiment ?? m.sentiment ?? null,
    momentum: m.momentum || null,
    handle: cgId,
    cashtag: t.cashtag_symbol ? `$${t.cashtag_symbol}` : (sym ? `$${sym}` : null),
    primary_category: Array.isArray(t.categories) ? t.categories[0] : null,
    updated_at: m.updated_at || entry.latest_mention_at || t.last_polled_at || null,
    has_tweets: Boolean(t.has_tweets ?? (Number(m.external_mentions_24h ?? m.mentions_24h ?? 0) > 0)),
  };
}

app.get('/api/x-bubbles-live', async (req, res) => {
  try {
    const limit = Math.min(parseInt(req.query.limit) || 800, 2000);
    const ranking = String(req.query.ranking || 'mentions').toLowerCase();
    const minVolume = Math.max(parseInt(req.query.min_volume) || 1, 1);
    const cacheKey = `live:${limit}:${ranking}:${minVolume}`;
    const cached = getCached(xDashLiveCache, cacheKey, 30_000);
    if (cached) return res.json(cached);

    if (!X_DASH_KEY) {
      return res.status(500).json({ error: 'X_DASH_API_KEY not configured' });
    }

    // Paginate. X-Dash defaults page_size to 10; we crank to 200 for fewer round-trips.
    const perPage = 50;
    const tokens = [];
    const engagementByCg = new Map();
    let totalCount = null;
    for (let page = 1; tokens.length < limit; page++) {
      const j = await fetchXDashBootstrapPage({ page, perPage, ranking });
      console.error('[xbl] page', page, 'keys:', Object.keys(j||{}), 'tokens.len:', (j?.tokens||[]).length);
      const pageTokens = Array.isArray(j?.tokens) ? j.tokens : [];
      const pag = j?.pagination || {};
      totalCount = totalCount ?? pag.filtered_count ?? j?.token_count ?? null;
      if (!pageTokens.length) break;
      for (const t of pageTokens) {
        tokens.push(normalizeXDashToken(t, tokens.length + 1));
        const cg = String(t?.token?.cg_id || '').toLowerCase();
        const eng = Number(t?.metrics?.external_weighted_engagement_24h || 0);
        if (cg && eng > 0) engagementByCg.set(cg, eng);
        if (tokens.length >= limit) break;
      }
      if (pag.page_count && page >= pag.page_count) break;
      if (page > 30) break; // hard ceiling — paranoia stop
    }

    // Apply min_volume client-side post-normalize. X-Dash entries don't carry
    // volume_usd; skip the filter when undefined so we don't drop every token.
    const filtered = postProcessFlatMentions(tokens.filter((t) => {
      if (!minVolume) return true;
      if (t.volume_usd == null) return true;
      return Number(t.volume_usd) >= minVolume;
    }), engagementByCg);

    const payload = {
      data: filtered,                        // matches existing /api/x-bubbles shape (array)
      meta: {
        source: 'x-dash-direct',
        upstream_total: totalCount,
        returned: filtered.length,
        ranking,
        ts: new Date().toISOString(),
      },
    };
    setCached(xDashLiveCache, cacheKey, payload, 30_000);
    res.json(payload);
  } catch (err) {
    console.error('x-bubbles-live error:', err.message);
    console.error('[x-bubbles] live upstream error:', err.message);
    res.status(502).json({ error: 'X-Bubbles live upstream unavailable', data: [] });
  }
});

// Per-token live lookup mirror — also reads from X-Dash directly.
app.get('/api/x-bubbles-live/:asset', async (req, res) => {
  try {
    const asset = String(req.params.asset || '').trim();
    if (!asset) return res.status(400).json({ error: 'Missing :asset' });
    if (!X_DASH_KEY) return res.status(500).json({ error: 'X_DASH_API_KEY not configured' });
    const cacheKey = `live-tok:${asset.toLowerCase()}`;
    const cached = getCached(xDashLiveCache, cacheKey, 60_000);
    if (cached) return res.json(cached);

    const url = `${X_DASH_DIRECT_URL}/api/token/${encodeURIComponent(asset.toLowerCase())}`;
    const ctrl = new AbortController(); const t = setTimeout(() => ctrl.abort(), 10_000);
    let j;
    try {
      const r = await fetch(url, {
        headers: { 'Authorization': `Bearer ${X_DASH_KEY}`, 'X-Internal-Key': X_DASH_KEY, 'x-api-key': X_DASH_KEY, Accept: 'application/json' },
        signal: ctrl.signal,
      });
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      j = await r.json();
    } finally { clearTimeout(t); }

    const m = j?.metrics || {};
    const tok = j?.token || {};
    const payload = {
      data: {
        asset: (tok.symbol || tok.cg_id || asset).toUpperCase(),
        name: tok.name || asset,
        image: tok.image_url || null,
        coingecko_id: tok.cg_id || null,
        socials: tok.socials || {},
        metrics: {
          mentions_24h: Number(m.external_mentions_24h ?? m.mentions_24h ?? 0),
          mentions_7d_avg: Number(m.external_mentions_prev_daily_avg ?? m.mentions_7d_avg ?? 0),
          unique_authors: Number(m.unique_external_authors_24h ?? m.unique_authors ?? 0),
          velocity_ratio: Number(m.velocity_ratio ?? 0) || null,
          growth_pct: Number(m.growth_pct ?? 0) || null,
          sentiment: m.weighted_sentiment ?? m.sentiment ?? null,
          momentum: m.momentum || null,
          updated_at: m.updated_at || j?.latest_mention_at || null,
        },
        history: j?.history || [],
        tweets: j?.top_mentions || j?.mentions || [],
      },
      meta: { source: 'x-dash-direct', ts: new Date().toISOString() },
    };
    setCached(xDashLiveCache, cacheKey, payload, 60_000);
    res.json(payload);
  } catch (err) {
    console.error('x-bubbles-live token error:', err.message);
    console.error('[x-bubbles] live upstream error:', err.message);
    res.status(502).json({ error: 'X-Bubbles live upstream unavailable' });
  }
});

app.get('/api/x-bubbles', async (req, res) => {
  try {
    const limit = Math.min(parseInt(req.query.limit) || 120, 1500);
    const minVolume = Math.max(parseInt(req.query.min_volume) || 1, 1);
    const ranking = String(req.query.ranking || 'mentions').toLowerCase();
    const cacheKey = `lb:${limit}:${minVolume}:${ranking}`;
    const cached = getCached(xBubblesCache.leaderboard, cacheKey, 600_000);
    if (cached) return res.json(cached);

    const params = new URLSearchParams({
      limit: String(limit),
      min_volume: String(minVolume),
      ranking,
    }).toString();

    // FAST PATH: hit only the upstream Spectre API and reply immediately.
    // The X-Dash merge (which is slow due to ~12 sequential bootstrap pages
    // + per-token rescue) runs in the background and refreshes the cache.
    const data = await spectreXBubblesFetch('/v1/social/x-bubbles', params).catch(() => null);

    // Stale-while-revalidate: if upstream failed AND we have ANY previous
    // cache entry (even expired), serve it instead of an empty response.
    // Prevents the warmer from poisoning the cache with null when upstream
    // is briefly slow.
    const hasGoodData = !!(data && Array.isArray(data.data) && data.data.length > 0);
    if (!hasGoodData) {
      const stale = xBubblesCache.leaderboard.get(cacheKey);
      if (stale?.data && Array.isArray(stale.data.data) && stale.data.data.length > 0) {
        res.json(stale.data);
        return;
      }
      // No prior cache and upstream failed — return empty without caching.
      res.json(data || { data: [], meta: { error: 'upstream unavailable' } });
      return;
    }

    // Apply persistent patch ledger (truth from prior Phase B runs that survived
    // cache eviction). Tokens patched in the last 30 minutes get real values
    // immediately, even on a cold cache.
    const PATCH_TTL = 30 * 60 * 1000;
    let persistentPatched = 0;
    const persistentEngagement = new Map();
    if (Array.isArray(data.data) && xBubblesCache.persistentPatches.size > 0) {
      data.data = data.data.map((row) => {
        const cg = String(row.coingecko_id || '').toLowerCase();
        const entry = xBubblesCache.persistentPatches.get(cg);
        if (!entry || Date.now() - entry.ts > PATCH_TTL) return row;
        persistentPatched++;
        const live = entry.live;
        if (live.engagement_24h > 0) persistentEngagement.set(cg, live.engagement_24h);
        return {
          ...row,
          mentions_24h: live.mentions_24h,
          mentions_7d_avg: live.mentions_7d_avg ?? row.mentions_7d_avg,
          unique_authors: live.unique_authors ?? row.unique_authors,
          velocity_ratio: live.velocity_ratio ?? row.velocity_ratio,
          growth_pct: live.growth_pct ?? row.growth_pct,
          sentiment: live.sentiment ?? row.sentiment,
        };
      });
      // Rescale ambiguous majors using engagement carried in the patch ledger.
      data.data = postProcessFlatMentions(data.data, persistentEngagement);
    }
    data.meta = { ...(data.meta || {}), live_merge: { pending: true, persistent_patched: persistentPatched } };
    setCached(xBubblesCache.leaderboard, cacheKey, data, 600_000);
    res.json(data);

    // Dedup: only one bg merge per cache key at a time.
    if (!xBubblesCache.bgInflight) xBubblesCache.bgInflight = new Set();
    if (xBubblesCache.bgInflight.has(cacheKey)) return;
    xBubblesCache.bgInflight.add(cacheKey);

    // BACKGROUND MERGE — bootstrap + per-token rescue together.
    (async () => {
      try {
        if (!data || !Array.isArray(data.data) || !X_DASH_KEY) {
          console.log('[x-bubbles] bg-skip data=' + !!data + ' arr=' + Array.isArray(data?.data) + ' key=' + !!X_DASH_KEY);
          return;
        }
        console.log('[x-bubbles] bg-start rows=' + data.data.length);
        let bgData = data;

        // Phase A: paginate X-Dash bootstrap (the cheap, fast pass that covers
        // ~553 high-activity tokens). Run pages in chunks of 4 in parallel
        // to cut latency from ~18s sequential to ~5s.
        const liveTokens = [];
        let pageCount = 30;
        // First page sequentially to learn page_count.
        const p1 = await fetchXDashBootstrapPage({ page: 1, perPage: 50, ranking }).catch(() => null);
        if (p1 && Array.isArray(p1.tokens)) {
          pageCount = Math.min(pageCount, p1.pagination?.page_count || pageCount);
          for (const e of p1.tokens) {
            const m = e.metrics || {}, t = e.token || {};
            liveTokens.push({
              cg_id: t.cg_id || null,
              symbol: (t.symbol || '').toUpperCase(),
              mentions_24h: Number(m.external_mentions_24h ?? m.mentions_24h ?? 0),
              mentions_7d_avg: Number(m.external_mentions_prev_daily_avg ?? m.mentions_7d_avg ?? 0),
              unique_authors: Number(m.unique_external_authors_24h ?? m.unique_authors ?? 0),
              velocity_ratio: Number(m.velocity_ratio ?? 0) || null,
              growth_pct: Number(m.growth_pct ?? 0) || null,
              sentiment: m.weighted_sentiment ?? m.sentiment ?? null,
              engagement_24h: Number(m.external_weighted_engagement_24h ?? 0) || 0,
            });
          }
        }
        // Remaining pages in chunks of 4 parallel.
        if (pageCount > 1) {
          const remaining = [];
          for (let p = 2; p <= pageCount; p++) remaining.push(p);
          const PAGE_CHUNK = 4;
          for (let i = 0; i < remaining.length; i += PAGE_CHUNK) {
            const slice = remaining.slice(i, i + PAGE_CHUNK);
            const results = await Promise.allSettled(slice.map((page) => fetchXDashBootstrapPage({ page, perPage: 50, ranking })));
            for (const r of results) {
              if (r.status !== 'fulfilled' || !r.value?.tokens) continue;
              for (const e of r.value.tokens) {
                const m = e.metrics || {}, t = e.token || {};
                liveTokens.push({
                  cg_id: t.cg_id || null,
                  symbol: (t.symbol || '').toUpperCase(),
                  mentions_24h: Number(m.external_mentions_24h ?? m.mentions_24h ?? 0),
                  mentions_7d_avg: Number(m.external_mentions_prev_daily_avg ?? m.mentions_7d_avg ?? 0),
                  unique_authors: Number(m.unique_external_authors_24h ?? m.unique_authors ?? 0),
                  velocity_ratio: Number(m.velocity_ratio ?? 0) || null,
                  growth_pct: Number(m.growth_pct ?? 0) || null,
                  sentiment: m.weighted_sentiment ?? m.sentiment ?? null,
                  engagement_24h: Number(m.external_weighted_engagement_24h ?? 0) || 0,
                });
              }
            }
            await new Promise((r) => setTimeout(r, 150));
          }
        }
        const liveByCg = new Map(), liveBySym = new Map();
        for (const l of liveTokens) {
          if (l.cg_id) liveByCg.set(String(l.cg_id).toLowerCase(), l);
          if (l.symbol) liveBySym.set(l.symbol, l);
        }
        let phaseAPatched = 0;
        let merged = bgData.data.map((row) => {
          const cg = String(row.coingecko_id || row.cg_id || '').toLowerCase();
          const sym = String(row.asset || row.symbol || '').toUpperCase();
          const live = liveByCg.get(cg) || liveBySym.get(sym);
          if (!live) return row;
          const upstreamM = Number(row.mentions_24h || 0);
          if (upstreamM > 1 && live.mentions_24h <= upstreamM) return row;
          phaseAPatched++;
          return {
            ...row,
            mentions_24h: live.mentions_24h,
            mentions_7d_avg: live.mentions_7d_avg ?? row.mentions_7d_avg,
            unique_authors: live.unique_authors ?? row.unique_authors,
            velocity_ratio: live.velocity_ratio ?? row.velocity_ratio,
            growth_pct: live.growth_pct ?? row.growth_pct,
            sentiment: live.sentiment ?? row.sentiment,
          };
        });
        // Engagement-normalize ambiguous-cashtag majors (BTC/ETH/XRP/ADA/etc.)
        // whose handle-only crawl undercounts mentions vs. peers with $TICKER search.
        const engagementByCgA = new Map();
        for (const l of liveTokens) {
          if (l.cg_id && l.engagement_24h > 0) {
            engagementByCgA.set(String(l.cg_id).toLowerCase(), l.engagement_24h);
          }
        }
        merged = postProcessFlatMentions(merged, engagementByCgA);
        bgData = { ...bgData, data: merged, meta: { ...(bgData.meta || {}), live_merge: { phase_a_patched: phaseAPatched, live_count: liveTokens.length, pending: 'phase_b' } } };
        console.log('[x-bubbles] Phase A done patched=' + phaseAPatched + ' live=' + liveTokens.length);
        // Update cache after Phase A so frontends within TTL get the partial merge.
        setCached(xBubblesCache.leaderboard, cacheKey, bgData, 600_000);

        // Cooldown: skip Phase B if it ran less than 4 minutes ago (avoid hammering X-Dash).
        if (xBubblesCache.lastPhaseB && Date.now() - xBubblesCache.lastPhaseB < 180_000) {
          console.log('[x-bubbles] Phase B skipped (cooldown)');
          return;
        }
        xBubblesCache.lastPhaseB = Date.now();


        // Phase B: rotating per-token rescue for sentinel tokens.
        //   - Pick tokens currently at m24h ≤ 2 (the upstream sentinel range)
        //     within market_cap_rank ≤ 250 (real tokens worth fixing).
        //   - Skip tokens we've already patched in the last 25 minutes.
        //   - This way each 4-min Phase B cycle drains a different batch of
        //     sentinels. Over ~5 cycles (~20 min) the entire top-250 is real.
        if (!xBubblesCache.recentlyPatched) xBubblesCache.recentlyPatched = new Map();
        const RECENTLY_PATCHED_TTL = 25 * 60 * 1000; // 25 min
        // Evict expired entries from the recently-patched set.
        for (const [cg, ts] of xBubblesCache.recentlyPatched) {
          if (Date.now() - ts > RECENTLY_PATCHED_TTL) xBubblesCache.recentlyPatched.delete(cg);
        }
        const candidates = bgData.data
          .filter((row) => {
            const r = Number(row.market_cap_rank || 0);
            const m = Number(row.mentions_24h || 0);
            const cgLower = String(row.coingecko_id || '').toLowerCase();
            if (!cgLower) return false;
            if (r <= 0 || r > 250) return false;
            // Re-check top 30 every cycle; for ranks 31-250 skip if recently patched.
            if (r > 30 && xBubblesCache.recentlyPatched.has(cgLower)) return false;
            // Prioritize sentinel tokens (m ≤ 2). Top-30 always re-fetched
            // regardless because they're the tokens users see most.
            return r <= 30 || m <= 2;
          })
          .sort((a, b) => (Number(a.market_cap_rank) || 9999) - (Number(b.market_cap_rank) || 9999))
          .slice(0, 80);
        const liveByCgB = new Map();
        async function processChunk(chunk) {
          await Promise.allSettled(chunk.map(async (row) => {
            const cg = String(row.coingecko_id).toLowerCase();
            try {
              const ctrl = new AbortController(); const t = setTimeout(() => ctrl.abort(), 14000);
              const r = await fetch(`${X_DASH_DIRECT_URL}/api/token/${encodeURIComponent(cg)}`, {
                headers: { 'Authorization': `Bearer ${X_DASH_KEY}`, 'X-Internal-Key': X_DASH_KEY, 'x-api-key': X_DASH_KEY, Accept: 'application/json' },
                signal: ctrl.signal,
              });
              clearTimeout(t);
              if (!r.ok) return;
              const j = await r.json();
              const m = j?.metrics || {};
              const m24 = Number(m.external_mentions_24h ?? m.mentions_24h ?? 0);
              if (m24 > 0) liveByCgB.set(cg, {
                mentions_24h: m24,
                mentions_7d_avg: Number(m.external_mentions_prev_daily_avg ?? m.mentions_7d_avg ?? 0),
                unique_authors: Number(m.unique_external_authors_24h ?? m.unique_authors ?? 0),
                velocity_ratio: Number(m.velocity_ratio ?? 0) || null,
                growth_pct: Number(m.growth_pct ?? 0) || null,
                sentiment: m.weighted_sentiment ?? m.sentiment ?? null,
                engagement_24h: Number(m.external_weighted_engagement_24h ?? 0) || 0,
              });
              // Capture upstream's query_policy too — Phase B per-token responses
              // expose it under state.coverage. Learn ambiguous tokens at runtime
              // so the seed list doesn't have to be exhaustive.
              const policy = j?.state?.coverage?.query_policy;
              if (policy === 'ambiguous_cashtag_handle_only') learnedAmbiguousCgIds.add(cg);
            } catch { /* swallow */ }
          }));
        }
        const CHUNK = 6;
        for (let i = 0; i < candidates.length; i += CHUNK) {
          await processChunk(candidates.slice(i, i + CHUNK));
          if (i + CHUNK < candidates.length) await new Promise((r) => setTimeout(r, 250));
        }
        // Mark every successfully-patched cg as recently-patched + write to the
        // persistent patch ledger so it survives cache evictions.
        for (const [cg, live] of liveByCgB) {
          xBubblesCache.recentlyPatched.set(cg, Date.now());
          xBubblesCache.persistentPatches.set(cg, { live, ts: Date.now() });
        }
        if (liveByCgB.size === 0) {
          const failedPayload = {
            ...bgData,
            meta: { ...(bgData.meta || {}), live_merge: { ...(bgData.meta?.live_merge || {}), second_pass_patched: 0, second_pass_attempted: candidates.length, phase_b_failed: true } },
          };
          setCached(xBubblesCache.leaderboard, cacheKey, failedPayload, 600_000);
          console.log('[x-bubbles] Phase B got 0 results from', candidates.length, 'candidates');
          return;
        }
        console.log('[x-bubbles] Phase B got', liveByCgB.size, 'live tokens from', candidates.length, 'candidates');
        let secondPassPatched = 0;
        const upgraded = bgData.data.map((row) => {
          const cg = String(row.coingecko_id || '').toLowerCase();
          const live = liveByCgB.get(cg);
          if (!live) return row;
          secondPassPatched++;
          return {
            ...row,
            mentions_24h: live.mentions_24h,
            mentions_7d_avg: live.mentions_7d_avg ?? row.mentions_7d_avg,
            unique_authors: live.unique_authors ?? row.unique_authors,
            velocity_ratio: live.velocity_ratio ?? row.velocity_ratio,
            growth_pct: live.growth_pct ?? row.growth_pct,
            sentiment: live.sentiment ?? row.sentiment,
          };
        });
        // Combine engagement from Phase A bootstrap + Phase B per-token results
        // so the ambiguous-cashtag rescale has the most complete signal.
        const engagementByCgB = new Map(engagementByCgA);
        for (const [cg, live] of liveByCgB) {
          if (live.engagement_24h > 0) engagementByCgB.set(cg, live.engagement_24h);
        }
        const rescaled = postProcessFlatMentions(upgraded, engagementByCgB);
        const upgradedPayload = {
          ...bgData,
          data: rescaled,
          meta: { ...(bgData.meta || {}), live_merge: { ...(bgData.meta?.live_merge || {}), second_pass_patched: secondPassPatched, second_pass_attempted: candidates.length } },
        };
        // Refresh the cache so the next call within TTL gets the patched data.
        setCached(xBubblesCache.leaderboard, cacheKey, upgradedPayload, 600_000);
      } catch (e) {
        console.error('x-bubbles bg rescue error:', e?.message || e);
      } finally {
        xBubblesCache.bgInflight.delete(cacheKey);
      }
    })();
    return;

  } catch (err) {
    console.error('x-bubbles leaderboard error:', err.message);
    console.error('[x-bubbles] upstream error:', err.message);
    res.status(502).json({ error: 'X-Bubbles upstream unavailable', data: [] });
  }
});

// Asset sidebar — hits X-Dash directly so the "fresh tweets" section actually
// has tweets. Resolves symbol → coingecko_id from the leaderboard cache.
function resolveCgFromLeaderboard(sym) {
  const upper = String(sym || '').toUpperCase();
  for (const entry of xBubblesCache.leaderboard.values()) {
    if (Date.now() > entry.expires) continue;
    const rows = entry?.data?.data;
    if (!Array.isArray(rows)) continue;
    const hit = rows.find((r) => String(r.asset || '').toUpperCase() === upper);
    if (hit?.coingecko_id) return { cg: String(hit.coingecko_id).toLowerCase(), row: hit };
  }
  return null;
}

function shapeTweet(item) {
  const tw = item?.tweet || {};
  const au = item?.author || {};
  const handle = au.screen_name || au.handle || null;
  return {
    tweet_id: tw.tweet_id || null,
    full_text: tw.full_text || tw.text || '',
    url: tw.x_url || (tw.tweet_id && handle ? `https://x.com/${handle}/status/${tw.tweet_id}` : null),
    created_at: tw.created_at_utc || tw.created_at || null,
    author: {
      name: au.name || handle || null,
      handle,
      avatar: au.profile_image_url_https || au.avatar || null,
      followers: au.followers_count ?? au.followers ?? null,
      verified: !!(au.is_blue_verified || au.verified),
    },
    metrics: {
      likes: tw.favorite_count ?? tw.likes ?? null,
      retweets: tw.retweet_count ?? tw.retweets ?? null,
      replies: tw.reply_count ?? tw.replies ?? null,
      views: tw.views_count ?? tw.views ?? null,
    },
  };
}

app.get('/api/x-bubbles/:asset', async (req, res) => {
  try {
    const asset = String(req.params.asset || '').toUpperCase().trim();
    if (!asset) return res.status(400).json({ error: 'Missing :asset' });
    const cacheKey = `tok:${asset}`;
    const cached = getCached(xBubblesCache.token, cacheKey, 60_000);
    if (cached) return res.json(cached);

    if (!X_DASH_KEY) {
      return res.status(503).json({ error: 'X_DASH_API_KEY not configured' });
    }

    // Resolve symbol → coingecko_id via the leaderboard cache (covers all
    // tokens currently rendered in the bubbles page). If nothing's cached
    // yet, fall through with the symbol lowercased — X-Dash sometimes
    // accepts symbols too.
    const resolved = resolveCgFromLeaderboard(asset);
    const cg = resolved?.cg || asset.toLowerCase();
    const lbRow = resolved?.row || null;

    const url = `${X_DASH_DIRECT_URL}/api/token/${encodeURIComponent(cg)}`;
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), 16_000);
    let j = null;
    let xdashError = null;
    try {
      const r = await fetch(url, {
        headers: { 'Authorization': `Bearer ${X_DASH_KEY}`, 'X-Internal-Key': X_DASH_KEY, 'x-api-key': X_DASH_KEY, Accept: 'application/json' },
        signal: ctrl.signal,
      });
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      j = await r.json();
    } catch (e) {
      xdashError = e?.message || String(e);
    } finally { clearTimeout(t); }

    const tok = j?.token || {};
    const m = j?.metrics || {};
    const sentiment = Number(m.weighted_sentiment ?? 0);
    const color = sentiment > 0.15 ? 'bull' : sentiment < -0.15 ? 'bear' : 'neutral';
    const tweets = Array.isArray(j?.top_mentions) ? j.top_mentions.map(shapeTweet) : [];

    const payload = {
      data: {
        asset: (tok.symbol || asset).toUpperCase(),
        name: tok.name || lbRow?.name || asset,
        image: tok.image_small || tok.image_url || lbRow?.image || null,
        coingecko_id: tok.cg_id || cg,
        rank: lbRow?.rank ?? lbRow?.market_cap_rank ?? null,
        categories: tok.tags || lbRow?.categories || [],
        socials: {
          twitter: tok.handle ? `https://x.com/${tok.handle}` : null,
          website: tok.website || null,
        },
        metrics: (() => {
          const pick = (xdash, lb) => {
            const xn = Number(xdash);
            const ln = Number(lb);
            if (Number.isFinite(xn) && xn > 0) return xn;
            if (Number.isFinite(ln) && ln > 0) return ln;
            return Number.isFinite(xn) ? xn : (Number.isFinite(ln) ? ln : 0);
          };
          return {
            mentions_24h: pick(m.external_mentions_24h ?? m.mentions_24h, lbRow?.mentions_24h),
            mentions_7d_avg: pick(m.external_mentions_prev_daily_avg ?? m.mentions_7d_avg, lbRow?.mentions_7d_avg),
            unique_authors: pick(m.unique_external_authors_24h ?? m.unique_authors, lbRow?.unique_authors),
            velocity_ratio: pick(m.velocity_ratio, lbRow?.velocity_ratio) || null,
            growth_pct: pick(m.growth_pct, lbRow?.growth_pct) || null,
            sentiment,
            color,
          };
        })(),
        tweets,
        snapshot_ts: j?.generated_at_utc || j?.latest_mention_at || new Date().toISOString(),
        degraded: !!xdashError,
        error: xdashError,
      },
      meta: { source: xdashError ? 'leaderboard-fallback' : 'x-dash-direct', ts: new Date().toISOString() },
    };
    // Cache successful responses for 60s, degraded for 15s (so retry happens sooner).
    setCached(xBubblesCache.token, cacheKey, payload, xdashError ? 15_000 : 60_000);
    res.json(payload);
  } catch (err) {
    console.error('x-bubbles token error:', err.message);
    console.error('[x-bubbles] upstream error:', err.message);
    res.status(502).json({ error: 'X-Bubbles upstream unavailable' });
  }
});

