// ═══════════════════════════════════════════════════
// FIX 6: Extension Health / Diagnostics Endpoint
// ═══════════════════════════════════════════════════
// The Codex ping is a BILLED query, and this route is polled by monitors about
// once a minute (dashboard: ~1.3K getNetworks/day - the only caller of that
// query anywhere). A health probe does not need a fresh answer every minute:
// cache it 5 min. Latency reported is the cached probe's.
const _codexPingCache = { at: 0, ok: false, latency: null };
const CODEX_PING_TTL_MS = 5 * 60 * 1000;
async function _codexPing() {
  if (Date.now() - _codexPingCache.at < CODEX_PING_TTL_MS) return _codexPingCache;
  let ok = false;
  let latency = null;
  try {
    const t0 = Date.now();
    const testResult = await executeCodexQuery(`{ getNetworks { name } }`, {});
    ok = !!(testResult?.getNetworks);
    latency = Date.now() - t0;
  } catch { ok = false; }
  _codexPingCache.at = Date.now();
  _codexPingCache.ok = ok;
  _codexPingCache.latency = latency;
  return _codexPingCache;
}

app.get('/api/ext/health', async (req, res) => {
  try {
    // 1. Circuit breaker states
    const circuitBreakers = Object.values(breakers).map(b => b.getStatus());

    // 2. Codex ping (cached, see _codexPing)
    const ping = await _codexPing();
    const codexOk = ping.ok;
    const codexLatency = ping.latency;

    // 3. Binance ping
    let binanceOk = false;
    let binanceLatency = null;
    try {
      const t0 = Date.now();
      const resp = await fetch('https://api.binance.com/api/v3/ping', { signal: AbortSignal.timeout(3000) });
      binanceOk = resp.ok;
      binanceLatency = Date.now() - t0;
    } catch { binanceOk = false; }

    // 4. WebSocket stats (lazy ref — wsStats defined in WS section, declare stub if not yet)
    const wsStatsSnapshot = typeof wsStats !== 'undefined' ? { ...wsStats } : {};
    wsStatsSnapshot.activeConnections = 0;
    wsStatsSnapshot.activePollers = 0;
    wsStatsSnapshot.subscriptions = 0;
    try {
      if (typeof wss !== 'undefined') {
        wsStatsSnapshot.activeConnections = wss.clients?.size || 0;
      }
      if (typeof activePricePollers !== 'undefined') {
        wsStatsSnapshot.activePollers = activePricePollers.size;
      }
      if (typeof priceSubscriptions !== 'undefined') {
        wsStatsSnapshot.subscriptions = priceSubscriptions.size;
      }
    } catch {}

    // 5. Token registry stats
    const registryStats = {
      totalTokens: getAllSymbols().length,
      withCodexAddress: getAllSymbols().filter(s => hasCodexAddress(s)).length,
      withBinancePair: getBinanceSymbols().length,
    };

    // 6. Cache stats
    const cacheStats = {};
    for (const [name, map] of Object.entries(cache)) {
      if (map instanceof Map) {
        cacheStats[name] = map.size;
      }
    }

    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: Math.floor(process.uptime()),
      sources: {
        codex: { ok: codexOk, latencyMs: codexLatency },
        binance: { ok: binanceOk, latencyMs: binanceLatency },
        circuitBreakers,
      },
      websocket: wsStatsSnapshot,
      registry: registryStats,
      caches: cacheStats,
    });
  } catch (err) {
    res.status(500).json({ status: 'error', error: 'Internal server error' });
  }
});

