// ═══════════════════════════════════════════════════════════════════════════════
// WEBSOCKET — Real-time price streaming for active tokens
// Polls Codex /token/details every 5s and pushes price changes to subscribers
// ═══════════════════════════════════════════════════════════════════════════════
const http = require('http');
const WebSocket = require('ws');
const httpServer = http.createServer(app);
const wss = new WebSocket.Server({ server: httpServer, path: '/ws' });

// Track subscriptions: { address_networkId: Set<ws clients> }
const priceSubscriptions = new Map();
// Track active polling intervals per token
const activePricePollers = new Map();
// Last known price per token (avoid sending duplicates)
const lastKnownPrices = new Map();

// FIX 3: Error tracking per poller — notify clients when data is stale
const pollerErrorCounts = new Map();  // key → consecutive error count
const pollerLastSuccess = new Map();  // key → timestamp of last successful poll
const MAX_POLL_ERRORS = 5;           // After this many consecutive errors, notify stale
const STALE_NOTIFY_INTERVAL = 30000; // Re-notify stale every 30s
const pollerStaleNotified = new Map(); // key → last stale notification timestamp

// WebSocket stats for /api/ext/health
let wsStats = {
  totalConnections: 0,
  messagesReceived: 0,
  priceUpdatesSent: 0,
  errorsTotal: 0,
};

function startPricePoller(address, networkId) {
  const key = `${address.toLowerCase()}_${networkId}`;
  if (activePricePollers.has(key)) return;

  console.log(`[WS] Starting price poller for ${key}`);

  const poll = async () => {
    const subscribers = priceSubscriptions.get(key);
    if (!subscribers || subscribers.size === 0) {
      // No subscribers left, stop polling
      clearInterval(activePricePollers.get(key));
      activePricePollers.delete(key);
      lastKnownPrices.delete(key);
      pollerErrorCounts.delete(key);
      pollerLastSuccess.delete(key);
      pollerStaleNotified.delete(key);
      console.log(`[WS] Stopped price poller for ${key} (no subscribers)`);
      return;
    }

    try {
      const formattedAddress = address.startsWith('0x') ? address.toLowerCase() : address;
      const tokenSymbol = `${formattedAddress}:${networkId}`;

      // Quick price query via Codex
      const priceQuery = `
        query GetTokenPrice($symbol: String!) {
          getTokenBars(
            symbol: $symbol
            from: ${Math.floor(Date.now() / 1000) - 120}
            to: ${Math.floor(Date.now() / 1000)}
            resolution: "1"
          ) {
            o h l c t volume
          }
        }
      `;

      const result = await executeCodexQuery(priceQuery, { symbol: tokenSymbol });
      const bars = result?.getTokenBars;

      if (bars && bars.t && bars.t.length > 0) {
        const lastIdx = bars.t.length - 1;
        const price = parseFloat(bars.c[lastIdx]);
        const volume = parseFloat(bars.volume?.[lastIdx]) || 0;
        const open = parseFloat(bars.o[0]);

        // FIX 3: Reset error count on success
        pollerErrorCounts.set(key, 0);
        pollerLastSuccess.set(key, Date.now());
        pollerStaleNotified.delete(key);

        // Only send if price changed
        const lastPrice = lastKnownPrices.get(key);
        if (lastPrice !== price) {
          lastKnownPrices.set(key, price);

          const msg = JSON.stringify({
            type: 'price_update',
            address,
            networkId,
            price,
            volume,
            open,
            change: open > 0 ? ((price - open) / open) : 0,
            timestamp: bars.t[lastIdx],
          });

          subscribers.forEach(ws => {
            if (ws.readyState === WebSocket.OPEN) {
              ws.send(msg);
              wsStats.priceUpdatesSent++;
            }
          });
        }
      } else {
        // No data returned — count as soft error
        const errCount = (pollerErrorCounts.get(key) || 0) + 1;
        pollerErrorCounts.set(key, errCount);
      }
    } catch (err) {
      // FIX 3: Track consecutive errors, notify clients when stale
      wsStats.errorsTotal++;
      const errCount = (pollerErrorCounts.get(key) || 0) + 1;
      pollerErrorCounts.set(key, errCount);

      if (errCount >= MAX_POLL_ERRORS) {
        const lastNotify = pollerStaleNotified.get(key) || 0;
        if (Date.now() - lastNotify > STALE_NOTIFY_INTERVAL) {
          pollerStaleNotified.set(key, Date.now());
          const lastSuccess = pollerLastSuccess.get(key);
          const staleSec = lastSuccess ? Math.floor((Date.now() - lastSuccess) / 1000) : null;
          const staleMsg = JSON.stringify({
            type: 'price_stale',
            address,
            networkId,
            consecutiveErrors: errCount,
            lastSuccessSecondsAgo: staleSec,
            message: `Price data may be stale (${errCount} consecutive poll failures)`,
          });
          subscribers.forEach(ws => {
            if (ws.readyState === WebSocket.OPEN) {
              ws.send(staleMsg);
            }
          });
          console.warn(`[WS] Stale data for ${key}: ${errCount} consecutive errors`);
        }
      }
    }
  };

  // Poll every 60s. SSE relay provides real-time prices for trading app; this
  // poller is for tokens not on the SSE feed (long-tail DEX). 15s was billing
  // ~4x more getTokenBars/day than necessary on Codex.
  poll();
  activePricePollers.set(key, setInterval(poll, 60000));
}

// Keep-alive ping every 25s to prevent idle disconnect
const wsKeepAlive = setInterval(() => {
  wss.clients.forEach(ws => {
    if (ws.isAlive === false) return ws.terminate();
    ws.isAlive = false;
    ws.ping();
  });
}, 25000);
wss.on('close', () => clearInterval(wsKeepAlive));

wss.on('connection', (ws) => {
  ws.isAlive = true;
  wsStats.totalConnections++;
  ws.on('pong', () => { ws.isAlive = true; });
  let subscribedKeys = new Set();

  ws.on('message', (raw) => {
    wsStats.messagesReceived++;
    try {
      const msg = JSON.parse(raw);

      if (msg.type === 'subscribe' && msg.address) {
        const networkId = msg.networkId || 1;
        const key = `${msg.address.toLowerCase()}_${networkId}`;

        if (!priceSubscriptions.has(key)) {
          priceSubscriptions.set(key, new Set());
        }
        priceSubscriptions.get(key).add(ws);
        subscribedKeys.add(key);

        // Start polling for this token if not already
        startPricePoller(msg.address, networkId);

        ws.send(JSON.stringify({ type: 'subscribed', address: msg.address, networkId }));
      }

      if (msg.type === 'unsubscribe' && msg.address) {
        const networkId = msg.networkId || 1;
        const key = `${msg.address.toLowerCase()}_${networkId}`;
        const subs = priceSubscriptions.get(key);
        if (subs) {
          subs.delete(ws);
          subscribedKeys.delete(key);
        }
      }
    } catch (e) {
      // Ignore malformed messages
    }
  });

  ws.on('close', () => {
    // Clean up all subscriptions for this client
    subscribedKeys.forEach(key => {
      const subs = priceSubscriptions.get(key);
      if (subs) subs.delete(ws);
    });
  });
});

// ══════════════════════════════════════════════
// Sector Chart endpoints — CG-backed (2026-05-15)
// Dead Haitam charts-277369611639 + sector-compare-277369611639 removed.
// /api/sector/lines now derives from CoinGecko via the existing
// /api/market/sectors/snapshot endpoint (server fan-out + 5min cache, L7925).
// /api/sector/compare proxies to CoinGecko /coins/markets directly.
// ══════════════════════════════════════════════
const SECTOR_LINES_CG_MAP = {
  'meme-token': 'MEME',
  'layer-1': 'L1',
  'decentralized-finance-defi': 'DEFI',
  'layer-2': 'L2',
  'gaming': 'GAMING',
  'artificial-intelligence': 'AI',
  'privacy-coins': 'PRIVACY',
};
const SECTOR_LINES_WINDOW_HOURS = 168;
const SECTOR_LINES_OUTLIER_PCT = 120;

let sectorLineCache = { data: null, ts: 0 };
app.get('/api/sector/lines', async (req, res) => {
  if (sectorLineCache.data && Date.now() - sectorLineCache.ts < 120000) {
    return res.json(sectorLineCache.data);
  }
  try {
    const slugs = Object.keys(SECTOR_LINES_CG_MAP).join(',');
    const internal = await fetch(`http://localhost:${PORT}/api/market/sectors/snapshot?categories=${slugs}`, {
      signal: AbortSignal.timeout(15000),
    });
    if (!internal.ok) throw new Error(`snapshot ${internal.status}`);
    const snapshot = await internal.json();

    const rows = [];
    const nowSec = Math.floor(Date.now() / 1000);
    const stepSec = 3600;
    (snapshot?.sectors || []).forEach((entry) => {
      const sectorLabel = SECTOR_LINES_CG_MAP[entry?.id];
      if (!sectorLabel) return;
      (entry.tokens || []).forEach((tok) => {
        const prices = Array.isArray(tok?.sparkline) ? tok.sparkline.slice(-SECTOR_LINES_WINDOW_HOURS) : null;
        if (!prices || prices.length < 2) return;
        const startPrice = prices[0];
        const endPrice = prices[prices.length - 1];
        if (!startPrice || !isFinite(startPrice)) return;
        const movePct = ((endPrice - startPrice) / startPrice) * 100;
        if (Math.abs(movePct) > SECTOR_LINES_OUTLIER_PCT) return;
        const startTs = nowSec - (prices.length - 1) * stepSec;
        prices.forEach((p, i) => {
          if (typeof p !== 'number' || !isFinite(p)) return;
          rows.push([startTs + i * stepSec, tok.symbol, p, sectorLabel]);
        });
      });
    });

    const out = { d: rows, source: 'coingecko-sector-snapshot', cached_at: new Date().toISOString() };
    sectorLineCache = { data: out, ts: Date.now() };
    res.json(out);
  } catch (e) {
    console.error('Sector lines (CG) error:', e.message);
    if (sectorLineCache.data) return res.json({ ...sectorLineCache.data, stale: true });
    res.status(200).json({ d: [], degraded: true, error: e.message });
  }
});

let sectorCompareCache = {};
app.get('/api/sector/compare', async (req, res) => {
  const { token_ids, sector } = req.query;
  const cacheKey = `${token_ids || ''}_${sector || ''}`;
  if (sectorCompareCache[cacheKey] && Date.now() - sectorCompareCache[cacheKey].ts < 120000) {
    return res.json(sectorCompareCache[cacheKey].data);
  }
  try {
    const ids = String(token_ids || '').split(',').map(s => s.trim()).filter(Boolean);
    if (!ids.length) return res.status(400).json({ error: 'token_ids required' });
    const cgUrl = `http://localhost:${PORT}/api/coingecko/coins/markets?vs_currency=usd&ids=${encodeURIComponent(ids.join(','))}&sparkline=true&price_change_percentage=24h,7d`;
    const resp = await fetch(cgUrl, { signal: AbortSignal.timeout(15000) });
    if (!resp.ok) throw new Error(`cg ${resp.status}`);
    const data = await resp.json();
    const out = { sector: sector || null, tokens: Array.isArray(data) ? data : [], source: 'coingecko' };
    sectorCompareCache[cacheKey] = { data: out, ts: Date.now() };
    res.json(out);
  } catch (e) {
    console.error('Sector compare (CG) error:', e.message);
    res.status(200).json({ sector: sector || null, tokens: [], degraded: true, error: e.message });
  }
});

