// Solana JSON-RPC proxy (method allowlist) - dev twin of
// apps/trading/api/solana-rpc.js. The public Solana RPC blocks browser
// origins (CORS), so the client's web3.js Connection AND the Privy v3 kit
// RPC (config.solana.rpcs) point at this same-origin endpoint.
// sendTransaction IS allowed: Privy v3 broadcasts through the app-configured
// RPC (not Privy infra), and it only relays ALREADY-SIGNED bytes - this
// endpoint cannot sign anything. Routing sends here gives standard JSON-RPC
// error shapes (publicnode's nonstandard preflight errors crash
// @solana/kit's error parser) + server-side logging of send failures.
const SOLANA_RPC_PROXY_METHODS = new Set([
  'getBalance', 'getTokenAccountBalance', 'getTokenAccountsByOwner',
  'getAccountInfo', 'getMultipleAccounts', 'getLatestBlockhash',
  'getSignatureStatuses', 'getVersion', 'getSlot', 'simulateTransaction',
  'getTransaction', 'getParsedTransaction',
  // Privy v3 kit send + confirm path
  'sendTransaction', 'getBlockHeight', 'getEpochInfo', 'getFeeForMessage',
  'getRecentPrioritizationFees', 'getMinimumBalanceForRentExemption',
  'getGenesisHash', 'getHealth',
]);
app.post('/api/solana-rpc', async (req, res) => {
  const body = req.body;
  const entries = Array.isArray(body) ? body : [body];
  const valid = entries.length > 0 && entries.length <= 25 && entries.every(
    (e) => e && typeof e === 'object' && typeof e.method === 'string' && SOLANA_RPC_PROXY_METHODS.has(e.method)
  );
  if (!valid) return res.status(400).json({ error: 'Unsupported RPC request' });
  // Fallback rotation - the free public mainnet-beta endpoint rate-limits
  // aggressively; 429/5xx/network failure rotates to the next host.
  const rpcCandidates = [
    process.env.HELIUS_RPC_URL,
    process.env.SOLANA_RPC_URL,
    'https://api.mainnet-beta.solana.com',
    'https://solana-rpc.publicnode.com',
  ].filter(Boolean);

  // sendTransaction: fan out to ALL upstreams in parallel - the first node
  // that ACCEPTS the tx (body carries "result") wins. Signed txs are
  // idempotent (same signature), so multi-submit is safe, lands faster, and
  // never pays a lagging primary's timeout serially. All-reject returns the
  // first upstream's JSON-RPC error body so the client parses a real error.
  const sendEntry = entries.length === 1 && entries[0].method === 'sendTransaction';
  if (sendEntry && rpcCandidates.length > 1) {
    const bodyStr = JSON.stringify(body);
    try {
      const winner = await Promise.any(rpcCandidates.map(async (rpcUrl) => {
        const upstream = await fetch(rpcUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: bodyStr,
          signal: AbortSignal.timeout(8000),
        });
        const text = await upstream.text();
        if (!upstream.ok || !text.includes('"result"')) {
          throw new Error(text || `status ${upstream.status}`);
        }
        return text;
      }));
      res.set('Content-Type', 'application/json');
      return res.send(winner);
    } catch (aggErr) {
      const firstBody = aggErr && aggErr.errors && aggErr.errors[0] && aggErr.errors[0].message;
      console.warn('[solana-rpc] sendTransaction rejected by all upstreams:', String(firstBody).slice(0, 400));
      if (firstBody && firstBody.trim().startsWith('{')) {
        res.set('Content-Type', 'application/json');
        return res.send(firstBody);
      }
      return res.status(502).json({ error: 'RPC upstream failed' });
    }
  }

  let rpcLastErr = null;
  for (const rpcUrl of rpcCandidates) {
    try {
      const upstream = await fetch(rpcUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
        signal: AbortSignal.timeout(12000),
      });
      if (upstream.status === 429 || upstream.status >= 500) { rpcLastErr = new Error(rpcUrl + ' -> ' + upstream.status); continue; }
      const data = await upstream.text();
      // Surface send failures in the server log - the browser-side kit error
      // formatter has crashed on malformed shapes before; this is the
      // debuggable source of truth.
      if (entries.some((e) => e.method === 'sendTransaction') && data.includes('"error"')) {
        console.warn('[solana-rpc] sendTransaction error:', data.slice(0, 500));
      }
      res.set('Content-Type', 'application/json');
      return res.status(upstream.status).send(data);
    } catch (err) {
      rpcLastErr = err;
    }
  }
  console.error('[solana-rpc] all upstreams failed:', rpcLastErr && rpcLastErr.message);
  res.status(502).json({ error: 'RPC upstream failed' });
});

// Solana balance proxy - avoids CORS when querying from browser
app.get('/api/solana-balance', async (req, res) => {
  const { address } = req.query;
  if (!address) return res.status(400).json({ error: 'address required' });

  try {
    const rpcUrl = process.env.SOLANA_RPC_URL || 'https://api.mainnet-beta.solana.com';
    const rpcRes = await fetch(rpcUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        jsonrpc: '2.0', id: 1,
        method: 'getBalance',
        params: [address],
      }),
    });
    const data = await rpcRes.json();
    res.json({ balance: data.result?.value || 0 });
  } catch (err) {
    console.error('[solana-balance] Error:', err.message);
    res.status(500).json({ error: 'Failed to fetch balance' });
  }
});

