// Quota config - persisted to disk so it survives restarts
const QUOTA_CONFIG_FILE = path.join(__dirname, 'data', 'codex-metrics', 'quota-config.json')

function loadQuotaConfig() {
  try {
    if (fs.existsSync(QUOTA_CONFIG_FILE)) return JSON.parse(fs.readFileSync(QUOTA_CONFIG_FILE, 'utf-8'))
  } catch {}
  return { limit: 1000000, offset: 0, cycleStart: null, cycleEnd: null, note: '' }
}

function saveQuotaConfig(config) {
  try {
    const dir = path.dirname(QUOTA_CONFIG_FILE)
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true })
    fs.writeFileSync(QUOTA_CONFIG_FILE, JSON.stringify(config, null, 2))
  } catch (e) { console.error('[codex-metrics] Save quota config failed:', e.message) }
}

codexStreamRouter.get('/metrics', (_req, res) => {
  const days = parseInt(_req.query.days) || 7
  const metrics = codexMetrics.getMetrics(days)

  // Add streaming status
  const streamStatus = codexStreamRouter._getStreamStatus?.() || null

  // Compute tracked total from history
  const trackedTotal = (metrics.history || []).reduce((s, d) => s + (d.totalQueries || 0) + (d.totalSubEvents || 0), 0)
  const quotaConfig = loadQuotaConfig()

  res.json({
    ...metrics,
    streaming: streamStatus,
    quota: {
      ...quotaConfig,
      trackedTotal,
      estimatedUsed: quotaConfig.offset + trackedTotal,
    },
    optimizations: {
      cacheTTLs: {
        prices: CACHE_TTL_PRICES_MS / 1000 + 's',
        details: CACHE_TTL_DETAILS_MS / 1000 + 's',
        trending: CACHE_TTL_TRENDING_MS / 1000 + 's',
        pairs: CACHE_TTL_PAIRS_MS / 1000 + 's',
      },
      pricePollerInterval: '15s',
      trendingPollDefault: '60s',
      tokenDetailsPollDefault: '60s',
    },
  })
})

// POST /api/codex/quota - set quota offset and cycle dates
codexStreamRouter.post('/quota', express.json(), (req, res) => {
  const current = loadQuotaConfig()
  const updated = { ...current }
  if (req.body.offset !== undefined) updated.offset = parseInt(req.body.offset) || 0
  if (req.body.limit !== undefined) updated.limit = parseInt(req.body.limit) || 1000000
  if (req.body.cycleStart !== undefined) updated.cycleStart = req.body.cycleStart
  if (req.body.cycleEnd !== undefined) updated.cycleEnd = req.body.cycleEnd
  if (req.body.note !== undefined) updated.note = req.body.note
  saveQuotaConfig(updated)
  res.json({ ok: true, quota: updated })
})

