// Alerts CRUD - proxy createWebhooks/getWebhooks/deleteWebhooks to Codex GraphQL
app.all('/api/alerts', async (req, res) => {
  try {
    const WEBHOOK_SECRET = process.env.CODEX_WEBHOOK_SECRET || 'spectre-alerts-default'
    const CALLBACK_URL = process.env.WEBHOOK_CALLBACK_URL
    if (req.method === 'POST' && req.body?.type === 'pct') {
      // Cron (pct) rules have no Codex webhook and no dev KV - just echo the
      // shape back so the alerts sheet stays functional locally. Checked
      // before the CALLBACK_URL guard below: pct creation must not depend
      // on webhook env (cron rules never touch Codex).
      return res.status(201).json({ id: 'r_dev_pct', dev: true, ...req.body })
    }

    // CALLBACK_URL is only needed when CREATING webhooks (POST). Listing (GET)
    // and deleting (DELETE) work without it, so don't 503 the whole endpoint
    // in local dev where WEBHOOK_CALLBACK_URL is unset (webhooks can't reach
    // localhost anyway).
    if (req.method === 'POST' && !CALLBACK_URL) {
      return res.status(503).json({ error: 'WEBHOOK_CALLBACK_URL env required for creating alerts' })
    }

    if (req.method === 'POST') {
      const { tokenAddress, networkId, priceTarget, direction = 'above', name } = req.body
      if (!tokenAddress || !networkId || !priceTarget) return res.status(400).json({ error: 'tokenAddress, networkId, priceTarget required' })
      const priceCondition = direction === 'above' ? { gte: String(priceTarget) } : { lte: String(priceTarget) }
      const data = await executeCodexQuery(`
        mutation CreatePriceAlert($input: CreateWebhooksInput!) {
          createWebhooks(input: $input) { tokenPriceEventWebhooks { id name status } }
        }
      `, { input: { tokenPriceEventWebhooksInput: { webhooks: [{
        name: name || `${direction} $${priceTarget}`,
        callbackUrl: CALLBACK_URL,
        securityToken: WEBHOOK_SECRET,
        alertRecurrence: 'ONCE',
        conditions: { address: { eq: tokenAddress.startsWith('0x') ? tokenAddress.toLowerCase() : tokenAddress }, networkId: { eq: parseInt(networkId) }, priceUsd: priceCondition },
        retrySettings: { maxRetries: 3, maxRetryDelay: 30 },
        deduplicate: true,
      }] } } })
      const created = data?.createWebhooks?.tokenPriceEventWebhooks?.[0]
      cache.prices.delete('alerts:webhooks')
      return res.status(201).json({ id: created?.id, name: created?.name, tokenAddress, networkId: parseInt(networkId), priceTarget: parseFloat(priceTarget), direction })
    }

    if (req.method === 'GET') {
      // The bell polls this every few minutes from every open tab and the
      // list only changes through our own POST/DELETE below - so serve a
      // short cache (invalidated by those writes) instead of one getWebhooks
      // per poll (~300 Codex queries/day on the dev key for a list that
      // never moved).
      const cachedAlerts = getCached(cache.prices, 'alerts:webhooks', 60 * 1000)
      if (cachedAlerts) return res.json(cachedAlerts)
      const data = await executeCodexQuery(`query { getWebhooks { items { id name webhookType status created conditions { ... on TokenPriceEventWebhookCondition { address { eq } networkId { eq } priceUsd { gt gte lt lte eq } } } } } }`)
      const alerts = (data?.getWebhooks?.items || []).filter(w => w.webhookType === 'TOKEN_PRICE_EVENT').map(w => ({
        id: w.id, name: w.name, status: w.status, created: w.created,
        tokenAddress: w.conditions?.address?.eq || '',
        networkId: w.conditions?.networkId?.eq || 0,
        priceTarget: parseFloat(w.conditions?.priceUsd?.gte || w.conditions?.priceUsd?.lte || 0),
        direction: w.conditions?.priceUsd?.gte ? 'above' : 'below',
      }))
      // Dev has no per-user KV trigger store (that's prod-only, keyed by
      // Privy userId) - empty list is the documented fail-safe.
      const payload = { rules: [], alerts, triggered: [] }
      setCached(cache.prices, 'alerts:webhooks', payload, 60 * 1000)
      return res.json(payload)
    }

    if (req.method === 'PATCH') return res.json({ ok: true, dev: true })

    if (req.method === 'DELETE') {
      const { id, triggeredId, ruleId } = req.query
      if (triggeredId) {
        // No per-user KV trigger store in dev - no-op success.
        return res.json({ ok: true, dev: true })
      }
      if (ruleId) return res.json({ ok: true, dev: true })
      if (!id) return res.status(400).json({ error: 'id required' })
      const data = await executeCodexQuery(`mutation($input: DeleteWebhooksInput!) { deleteWebhooks(input: $input) { deletedIds } }`, { input: { webhookIds: [id] } })
      cache.prices.delete('alerts:webhooks')
      return res.json({ deleted: data?.deleteWebhooks?.deletedIds || [] })
    }

    res.status(405).json({ error: 'Method not allowed' })
  } catch (err) {
    const msg = err?.message || ''
    console.warn('[alerts]', msg)
    // Graceful degradation: GET upstream failures (dev key lacks webhook
    // scope, rate limits) become empty list 200 instead of 500.
    if (req.method === 'GET' && /not activated|webhook|rate limit|429|403/i.test(msg)) {
      res.setHeader('Cache-Control', 'no-store')
      return res.status(200).json({ rules: [], alerts: [], triggered: [], degraded: true, reason: msg })
    }
    res.status(500).json({ error: 'alerts unavailable' })
  }
})

